    [44] = {
        step = 44,
        title = [[Guía de Leveo - Sección #05]],
        text = [[
01) Once done, go find the tauren Gann Stonespire /target, he patrols up and down the main path to the right of Blackthorn Ridge around 46.81.  From him, accept "Gann's Reclamation".
02) Go down south to Bael Modan (entrance is 47.85)...
03) Do "Gann's Reclamation": kill the Bael'dun dwarves and kill/loot Prospector Khazgorm down in Bael Modan 48.86.
04) Find the tauren Gann Stonespire /target along the main path (around 46.81, #1 on map) and turn in "Gann's Reclamation", accept "Revenge of Gann".
05) Make sure "Chen's Empty Keg" is finished by kill/looting the Stormhides, Greater Thunderhawks and kodos.
06) Hearth to Camp Taurajo.  NOTE:  DONT vendor items yet!
07) North at CT by the Forge, turn in "Weapons of Choice" 45.58.
08) Turn in (if you haven't yet) "Owatanka", "Washte Pawne" and (if you did it) "The Harvester" 45.59.
09) Go to the quilboar in the cage and turn in "Betrayal from Within" 45.59, accept the next part.
10) At the Wind Rider Master 44.59 next to you, fly to XRs.
11) West in XRs, turn in "Egg Hunt" 51.30.  After turning this in you can destroy any remaining Silithid Eggs left.
12) Go to the orc at the bottom of the watchtower and turn in "Betrayal from Within" 52.31.  Make sure you are repaired/resupplied now.
13) Go east (above Ratchet) and do "Ishamuhale".  First find and kill/loot a Zhevra along the way there.  Then use the Fresh Zhevra Carcass quest item at the dead tree 60.30, then kill/loot Ishamuhale /target when he appears.
14) Go SE to Ratchet and next to the bank turn in "Deepmoss Spider Eggs" 62.38.  NOTE:  If you have any leftover Deepmoss Eggs, you can destroy them.
15) Turn in "Chen's Empty Keg" (male orc next to the Plate-n-Chain hut, 62.38).  NOTE:  This quest is now repeatable, but you do not get additional XP from it.
16) Next to the Flight Master turn in "Further Instructions" 63.37, accept the next part.
17) At the Flight Master 63.37 next to you fly to Sun Rock Retreat, Stonetalon Mountains.
        ]],
        image = "",
    },
    [45] = {
        step = 45,
        title = [[25 Stonetalon Mountains]],
        text = [[
01) At Sun Rock Retreat, accept Cenarius' Legacy" at the blood elf 46.60.
02) At the tauren by the Inn, accept "Harpies Threaten" 47.61.
03) Go in the Inn next to you and make Sun Rock Retreat your new home from the Innkeeper 47.62.  NOTE: Upstairs in the Inn is a vendor 48.62 that can sell healing/mana potions (on a timer).
04) Follow the path SW of Sun Rock Retreat entrance 45.62 and from the water elemental, accept "Elemental War" 47.64.
05) Go north to Mirkfallon Lake around 50.43 and do "Cycle of Rebirth": loot Gaea Seeds from the ground around the lake.  Also start working on "Jin'Zil's Forest Magic" by kill/looting the deer around the lake.
06) Work your way north while kill/looting deer & saps for "Jin'Zil's Forest Magic".  Once you get to Stonetalon Peak around 36.13 do "Cenarius' Legacy": kill the Cenarion night elf mobs around the middle of Stonetalon Peak.  Keep the next step in mind:
07) Go to the south and west side of Stonetalon Peak and finish up "Jin'Zil's Forest Magic": kill the deer, cats (west), saps (south), and fey dragons.  There are 3 spawn locations for the fey dragons, (see map for locations).
08) Once done, Hearth to Sun Rock Retreat, get resupplied at Innkeeper, then go to the goblin in the hut and turn in "Further Instructions" 59.63, accept "Gerenzo Wrenchwhistle".
        ]],
        image = "",
    },
    [46] = {
        step = 46,
        title = [[Horde - The Barrens]],
        text = [[
01) Go north into Windshear Crag and do "Shredding Machines": kill the two shredder machines.  XT:9 patrols around the south side of the river in Windshear Crag and XT:4 patrols around the north side of the river around 65.46.  TIP:  Use /target xt to find either of them.  Keep the next step in mind:
02) N/A
03) Go NE to the path at 70.41...
04) Do "Gerenzo Wrenchwhistle": follow the path up to the construction site and go down to kill/loot Gerenzo Wrenchwhistle (has several spawn locations on the platforms around 64.40 /target). (See Video)
05) Go back to the goblin in the hut and turn in "Gerenzo Wrenchwhistle" 59.63.
06) N/A
07) N/A
08) Go SE to the witch doctor in the cave and turn in "Jin'Zil's Forest Magic" 75.98.
09) Go east to the border of Stonetalon & Barrens and turn in "Shredding Machines" (35.28 in The Barrens).
10) Hearth if you can, if not consider waiting until you can hearth or just run back to Sun Rock Retreat.
        ]],
        image = "",
    },
    [47] = {
        step = 47,
        title = [[Tauren - Mulgore]],
        text = [[
01) At the female tauren, turn in "Cycle of Rebirth" 47.58.  Accept "New Life".
02) At the blood elf, turn in "Cenarius' Legacy" 46.60, SKIP "Ordanus".  Make sure you are repaired/resupplied.
03) Go to the path SW in Sun Rock Retreat entrance 45.62 and continue following it SW into The Charred Vale around 37.67 and do "Harpies Threaten" along with "Elemental War" and "New Life": kill/loot the fire elementals, click on the Gaea Dirt Mounds on the ground and kill the harpies.  NOTE: All these are evenly done throughout The Charred Vale, but the Bloodfury Harpy & Bloodfury Ambushers are north, while the Bloodfury Slayers & Bloodfury Roguefeathers are south.
04) Once they are all done, make sure you are at least 4 bars away from level 25, so you may have to grind a little, then go to the path that leads back to Sun Rock Retreat 38.68...
05) Go to the water elemental and turn in "Elemental War" 47.64.
06) Drop down and from the tauren by the Inn, turn in "Harpies Threaten" 47.61, SKIP "Bloodfury Bloodline" (for now).  Accept "Calling in the Reserves".
07) Just north a bit at the female tauren, turn in "New Life" (47.58, #2 on map).
08) Make sure you are repaired/resupplied.
09) Go to the Wind Rider Master 45.60 and fly to Thunder Bluff, Mulgore. BLOOD ELVES:  Blood elves who did Ghostlands will need to fly to Camp Taurajo, then head west into Mulgore, then go NW to get to Thunder Bluff 36.30.
        ]],
        image = "",
    },
    [48] = {
        step = 48,
        title = [[Thunder Bluff]],
        text = [[
01) Go east a bit to the Cooking Trainer (51.53 in TB) and get Apprentice Cook.  NOTE:  Make sure you get this side profession so you can do an easy turn-in XP quest at level 30 Hillsbrad.
02) Just east a bit by the Bonfire, accept "The sacred Flame" 55.51.
03) Turn in (if you haven't yet) "Melor Sends Word" (on The Hunter Rise, 62.81), accept "Steelsnap".
04) GET NEW ABILITIES, 3b) Get new spells/abilities for your class.
05) If you still need to upgrade to Heavy Wool Bandage (requires First Aid skill 115), then go to the top of The Spirit Rise to the First Aid Trainer 30.21 to get that.
06) Go up to the Wind Rider Master in the middle of TB 47.50 and fly to Camp Taurajo, The Barrens.
        ]],
        image = "",
    },
    [49] = {
        step = 49,
        title = [[25 Southern Barrens]],
        text = [[
01) Turn in "Ishamuhale" 45.59, accept "Enraged Thunder Lizards".
02) Go in the Inn and Make CT your home from the Innkeeper 46.59.  Don't forget to upgrade to lvl 25 food/water!
03) North in CT by the Forge, accept "A New Ore Sample" 45.58.  NOTE: you need to be lvl 25 to get this.
04) As you do the following steps start working on "Enraged Thunder Lizards" by kill/looting thunderlizards (stegosaurus dinos) along the way.  They are scattered everywhere in the open fields of southern Barrens:
05) If you haven't killed/looted the mob called Silithid Harvester (around 43.70 or around 48.70 /target), then go give it a try right now.  This drops an item which starts "The Harvester", accept it if you are able to kill this mob.  This has a 2 hour 45 min respawn.  If not there, it can be skipped.
06) At Bael'dun Keep (up at 49.84) do "Revenge of Gann": kill/loot the Bael'dun dwarves there for the items you need.  OPTIONAL GROUP QUEST HERE:  If you can find the help of one other player, then down and SE of the Bael'dun Keep entrance is a quest giver next to a tent 49.86 that gives "The Tear of the Moons".  This is done down in the keep by looting General Twinbraid's Strongbox down 49.84 in front of the fireplace.  There is a lvl 30 mob and numerous other dwarf mobs in the area.  If done, turn it in.
07) Find the tauren Gann Stonespire patrolling along the main path (around 46.81 /target) and turn in "Revenge of Gann", accept the next part.
08) Do "Revenge of Gann": go south to Bael Modan and click on the Bael Modan Flying Machine on top of the small tower 47.86.  NOTE:  You can be about 30 yards away to activate it.
09) Go back to the tauren Gann Stonespire along the main path (around 46.81, #7 on map, /target) and turn in "Revenge of Gann".
10) Make sure "Enraged Thunder Lizards" is finished: kill/loot thunderlizards (stegosaurus dinos) scattered everywhere in the open fields of southern Barrens.
11) Head south of the main path to The Great Lift (at 44.92 in The Barrens) and turn in "Calling in the Reserves".  Next to you there, accept (if it's available) "Message to Freewind Post" 32.22.
12) Go down the Lift to enter Thousand Needles...
        ]],
        image = "imagen_010.jpeg",
