    [50] = {
        step = 50,
        title = [[26 Thousand Needles]],
        text = [[
01) First off, keep an eye out for the Galak Messenger /target and kill/loot this centaur when you see him in 1k Needles.  He has a very large patrol path.  He drops an item which starts "Assassination Plot", accept it (if you can).  But, don't intentionally do this yet, continue on with the next step:
02) Go to the Lift, to go up to Freewind Post (47.48 in Thousand Needles).
03) Once up at Freewind Post, by the Bonfire turn in (f you have it) "Message to Freewind Post" 46.51, accept "Pacify the Centaur".
04) From the Wanted Poster - Arnak Grimtotem next to the Inn, accept "Wanted - Arnak Grimtotem" 46.51.
05) TBC, 4a) Next to you from the female blood elf accept "A Different Approach" 46.50.
06) On the west side of Freewind Post, accept "Alien Egg" 45.50.
07) NW at Freewind Post, accept "Wind Rider" 45.49.  Next to you there, get the FP from the Wind Rider Master.  Make sure you are repaired/resupplied.
08) Go back down the Lift (47.48, #2 on map).
09) Go just north to Splithoof Crag and do "Pacify the Centaur": kill the required amount of Galak Centaur around 46.43.
10) As you work east start working on "A New Ore Sample": kill/loot the Gravelsnout Surveyors or Gravelsnout Diggers /target until an Unrefined Ore Sample drops.  NOTES:  The drop rate is about 20%, but there are only a few of these mob spawns all around 1k Needles at the bottom of the pinnacles.  Don't intentionally try to find this right now, but keep this in mind while in 1k needles (and future trips back to 1k needles). If you can't find the ore sample then this can be skipped for now.  You'll have easier opportunities to try again later:
11) Go up the mountain ramp (entrance is east at 55.44)...
12) Once you get to the top in the cave, accept and do "Test of Faith" 54.41.  Once teleported, simply jump (or walk) off the wooden plank to complete the quest, then turn it in, SKIP "Test of Endurance" (Elite).
13) TBC, 11a) Go east starting around 64.48 and do "A Different Approach": kill/loot Thundering Boulderkin for the 2 Purifying Earths.  There are only 6-8 spawns (see map).  100% drop rate.
14) Do "Alien Egg": loot an Alien Egg.  This egg has several possible spawn points (either: 56.50 52.55 38.56).
15) Make sure you are at least 2 bars away from level 26, then go get on the Lift to go back to Freewind Post ( 47.49, #2 on map).
        ]],
        image = "imagen_011.jpeg",
    },
    [51] = {
        step = 51,
        title = [[Horde - The Barrens]],
        text = [[
01) At Freewind Post, next to the Bonfire turn in "Pacify the Centaur" (46.51, #3 on map), accept "Grimtotem Spying".
02) West in Freewind Post turn in "Alien Egg" 45.50.  Accept "Serpent Wild".
03) Hearth to Camp Taurajo.
04) Turn in (if you did it) "A New Ore Sample" (north in CT at the Forge, 45.58 in The Barrens).
05) Turn in "Enraged Thunder Lizards" (accept "Cry of the Thunderhawk"), (if you have it) "Washte Pawne" and (if you did it) "The Harvester" 45.59.
06) Go just south of CT around 45.64 and do "Cry of the Thunderhawk": kill/loot a Thunderhawk /target.  6 spawns around CT (see map).  Drop rate is 100%.
07) Go back to CT and turn in "Cry of the Thunderhawk" (45.59, #5 on map), SKIP "Mahren Skyseer".
08) Go to the Wind Rider Master at CT 44.59 and fly to   Crossroads, The Barrens.
09) Go north and turn in "Report to Kadrak" (up in the watchtower 48.5), SKIP "The Warsong Reports".
        ]],
        image = "imagen_012.jpeg",
    },
    [52] = {
        step = 52,
        title = [[27 Ashenvale]],
        text = [[
01) Go to Splintertree Post and turn in (if you have the initial quest) "The Ashenvale Hunt" 74.61.  Then accept and turn it in again.
02) Get the Flight Path there from the Wind Rider Master 73.62.
03) You can get repaired/resupplied from Burkrum 74.60 next to the Inn.
04) Next to the Inn, accept "Stonetalon Standstill" 74.60.
05) Go in the Inn and make Splintertree Post your new home from the Innkeeper 74.61.
06) TBC, 6b) At the outskirts of Splintertree Post, turn in (if you have it) "Report to Splintertree Post" 71.68.
07) Accept "Ashenvale Outrunners" 71.68.
08) Just south of Splintertree Post, kill the first of the three mobs related to the Ashenvale hunt: Sharptalon /target.  This lvl 31 blue hippogryph (patrols around and spawns at around 75.70).  This mob drops an item, which starts "Sharptalon's Claw", accept it.  TIP:  An easy way to kill this mob is to bring his health to a 3rd left, then drag him into the guards at Splintertree Post, they will finish em.
09) Just south of Splintertree Post, do "Ashenvale Outrunners": kill 9 Ashenvale Outrunners /target.
10) Go slightly west and do the escort quest "Torek's Assault" (starts at 68.75): escort Torek /target & his raiders west into the Silverwing Outpost.
11) Go west to Mystral Lake and do "Stonetalon Standstill": kill 12 Befouled Water Elementals around the lake and discover the gazebo on the small island in the middle of the lake 49.70.  Also, make sure you find and kill/loot Tideress /target, this water elemental patrols around under the lake, he drops an item which starts "The Befouled Element", accept it.
12) Kill the next mob related to the Ashenvale Hunt: Ursangous /target, this bear patrols clockwise around the mountain and trees around 42.68.  He drops an item, which starts "Ursangous's Paw", accept it.
13) Kill the last mob related to the Ashenvale Hunt: Shadumbra /target, this black panther patrols around around 57.56.  This cat drops an item, which starts "Shadumbra's Head", accept it.
14) Do "The Sacred Flame".  First kill/loot the Laughing Sisters around Raynewood Retreat around 59.55 until you get an Etched Phial (low drop rate), then see next step...
15) Use the quest item Etched Phial at the Moonwell down south 60.73.
        ]],
        image = "imagen_013.jpeg",
    },
    [53] = {
        step = 53,
        title = [[Guía de Leveo - Sección #15]],
        text = [[
01) Hearth (or run back) to Splintertree Post.
02) Right outside the Inn on your left turn in the 3 Ashenvale Hunt quests: "Sharptalon's Claw", "Ursangous's Paw" and "Shadumbra's Head" 74.61.  Then accept and complete "The Hunt Completed".
03) Next to the Inn, turn in "Stonetalon Standstill" and "The Befouled Element" 74.60, accept "Je'neu of the Earthen Ring".  Make sure you are repaired/resupplied.
04) At the orc next to the western watchtower, turn in "Torek's Assault" 73.62.
05) At the outskirts of Splintertree Post, turn in "Ashenvale Outrunners" 71.68.
06) The goal now is to go all the way to the other side of Ashenvale, to Zoram Strand (follow path on map) and then get the Flight Path there from the Wind Rider Master 12.34.  NOTE: Once you get to Astranaar 37.55(alliance town), go south of it to get around it.
07) At Zoram 'gar Outpost, first accept "Vorsha the Lasher" (starts in front of the bigger tent 12.35) (IMPORTANT:  This starts an escort.  If he is not there you can try later in the guide.  Do the next few steps quickly in the village before following Muglash for the escort:
08) turn in "Je'neu of the Earthen Ring" 12.34 (up in hut).   Also turn in "Trouble in the Deeps" 12.34, SKIP "The Essence of Aku'Mai" (Blackfathom Deeps dungeon).
09) From the troll up in the other tent, accept "Troll Charm" 12.35.   From the female troll next to you, accept "Naga at the Zoram Strand" 12.35 (no exclamation mark).
10) From the orc next to the Cauldron accept "Between a Rock and a Thistlefur" 12.35.
11) Do the escort you previously accepted (if you were able to) "Vorsha the Lasher": follow and protect Muglash /target until you can click on the Naga Brazier, then after a few waves of Naga mobs, kill Vorsha the Lasher. (See Video).   Do this along with "Naga at the Zoram Strand" by kill/looting Naga along the coast.
12) Grind your way to the Thistlefur Hold cave (entrance is 39.31) killing mobs for "Between a Rock and a Thistlefur".  Also, before getting to the cave, make sure Rorgish Jowl /target is dead.  He is a rare mob that patrols around (before the cave entrance) making your future escort quest difficult.  He has a 5.5 hour respawn.
13) In the cave do "Troll Charm": loot the Troll Chests on the ground.  Then, in the back of the cave, from the white bear in the cage 42.35, accept and try to do the escort quest "Freedom to Ruul".  You may have to fight 3-5 mobs at once several times, if you fail then it can be skipped.
        ]],
        image = "imagen_015.jpeg",
    },
    [54] = {
        step = 54,
        title = [[Tauren - Mulgore]],
        text = [[
01) Make sure "Between a Rock and a Thistlefur" is finished, then go back to Zoram Strand and then make sure "Naga at the Zoram Strand" is finished by kill/looting naga along the coast, then turn in "Vorsha the Lasher" 12.34.  NOTE:  If you didn't do "Vorsha the Lasher" previously you can try now.
02) (click to show instructions):
03) At the orc next to the Cauldron, turn in "Between a Rock and a Thistlefur" 12.35.
04) Up in the tent, turn in "Troll Charm" 12.35.   From the female troll next to you, turn in "Naga at the Zoram Strand" 12.35.
05) Hearth to Splintertree Post.
06) In the Inn, turn in (if you did it) "Freedom to Ruul" 74.61.  Make sure you are repaired/resupplied.
07) TBC, 5a) If you are level 27 go north in Splintertree Post and accept "Destroy the Legion" 73.60 (if not we will get this in a bit).
08) N/A
09) TBC, 7a) If you have not accepted "Destroy the Legion" 73.60 at Splintertree Post, then go there to accept it (requires level 27).
10) TBC, 7b) Go SE to Felfire Hill around 80.68 and do "Destroy the Legion": kill the required amount of demons.  While doing this quest you may find an item (low drop rate) which starts "Diabolical Plans", accept it (if you can).  If you can't find it then skip it.
11) N/A
12) TBC, 8a) Run back to Splintertree Post (don't hearth) and turn in "Destroy the Legion" (73.60, #5 on map).  If you found an item that started "Diabolical Plans", then turn that in as well.
13) TBC, 8b) OPTIONAL: If you were able to turn in "Diabolical Plans" then you could accept and do "Never Again!" (especially if you want one of the quest rewards) by going SE to Demon Fall Canyon (entrance 84.73) and killing the two named mobs.  Gorgannon patrols around 89.77, and Diathorus the Seeker is in the cave (entrance at 78.82), and he's far back in it at 79.85.  Cave exit is at 77.83.  Then turn the quest in at 73.61.
14) at the Wind Rider Master 73.62, fly to Thunder Bluff, Mulgore.
        ]],
        image = "imagen_016.jpeg",
    },
    [55] = {
        step = 55,
        title = [[28 Stonetalon Mountains]],
        text = [[
01) NOTE: SoM (100% quest rate) will NOT do steps 1-7 in Stonetalon!
02) East at the Bonfire, turn in "The Sacred Flame" (55.51 in TB), accept the next part.
03) GET NEW ABILITIES, 8b) Get your level 28 spells/abilities.
04) Go to TB's Inn and make Thunder Bluff your new home from the Innkeeper 46.65.
05) OPTIONAL, 9b) If you have an open 2nd profession and have not got Herbalism yet then I recommend getting it (its only 10 copper) at 50.40.  This can help you track an item pickup for a later quest.
06) If you still need to upgrade to Heavy Wool Bandage (requires First Aid skill 115), then go to the top of The Spirit Rise to the First Aid Trainer 30.21 to get that.
07) Go to the Wind Rider Master at the top of the tower in the middle of TB 47.50 and fly to Freewind Post, Thousand Needles.
        ]],
        image = "imagen_017.jpeg",
    },
    [56] = {
        step = 56,
        title = [[29 Thousand Needles]],
        text = [[
01) In the Inn, turn in "The Sacred Flame" (46.52 in Thousand Needles), accept the next part.  Make sure you are repaired/resupplied.
02) Take the Lift down from Freewind Post and then go to the cave north (entrance is at 44.38) and do "The Sacred Flame": keep hugging the left side of the cave until you get to the Ancient Brazier 42.31, then loot it (See Video).
03) REMINDER:  Keep an eye out for the Galak Messenger /target and kill/loot this centaur when you see him in 1k Needles.  He has a very large patrol path.  He drops an item which starts "Assassination Plot", accept it (if you can).  But, don't intentionally do this yet, continue on with the next step...
04) Grind west to Whitereach Post 21.32 and turn in "Serpent Wild", accept "Sacred Fire".  And next to you, accept "Hypercapacitor Gizmo".  Also turn in "A Different Approach", accept "A Dip in the Moonwell".  NOTES:  If you have already killed Galak Messenger /target and accepted the quest from the item he dropped, then turn in "Assassination Plot", then accept, do & turn in the follow up escort quest.  You can also get resupplied here from Laer Stepperunner /target.
05) Go east to the Boiling Pool around 35.35 and do "Sacred Fire": loot 10 Incendia Agave from the ground and under the water. TIP: Use Find Herbs in Spellbook (if you have it) to help you locate these easier.
06) Go west and do "Steelsnap": kill/loot Steelsnap /target.  This hyena patrols counter-clockwise around a somewhat large circle (starting at 18.27) and has two bodyguards.  Original spawn is in Camp E-thok 17.19. (See Video)
07) If you are still working on "A New Ore Sample", then see if you can find the Ore Sample: kill/loot the Gravelsnout Surveyors /target (there are two spawns nearby to check) for the Unrefined Ore Sample (see map for locations).
08) TBC, 7a) Go west and enter the bottom mountain ramp entrance 12.19, then do "A Dip in the Moonwell": use your quest item Robotron Control Unit at the Concealed Control Panel 9.19 at the bottom of the mesa.  Then control your robot to the Alliance moonwell 90.46 close by and use its collect water ability in it.  NOTE:  Classes that use pets must dismiss them first in order for this to work right.
09) Go to the Highperch (ramp entrance 14.33) and do "Wind Rider": loot 10 Highperch Wyvern Eggs from the ground.
10) In Highperch, go up the mountain ramp 13.40.  Once up there watch out for Heartrazor /target (a patrolling rare elite with a 12 hour respawn) and then accept and do the escort quest there "Homeward Bound" 18.41.  You can have the escort try to help you kill the rare elite.  It's also possible to time it so you can start and complete the escort so the rare is out of the way (just as he passes from the escortee).  If you fail, then this escort can be skipped.
11) Once again, if you are still working on "A New Ore Sample": kill/loot the Gravelsnout Surveyors /target (there are two spawns nearby to check) for the Unrefined Ore Sample (see map for locations, #7 on map).
        ]],
        image = "imagen_018.jpeg",
    },
    [57] = {
        step = 57,
        title = [[Thunder Bluff]],
        text = [[
01) Hearth to Thunder Bluff.
02) Go to The Hunter Rise and turn in "Steelsnap" 62.81.  Accept "Frostmaw".
03) Go to The Elder Rise and turn in "Sacred Fire" 70.31.  Accept "Arikara".
04) Go to the Wind Rider Master at the top of the tower in the middle of TB 47.50 and fly to Freewind Post, Thousand Needles.
05) Right when you land back at Freewind Post, turn in "Wind Rider" (45.49 in Thousand Needles).
06) Go in the Inn 46.52 and make Freewind Post your new home.
07) Next to you in the Inn, turn in "The Sacred Flame" 46.52.  Make sure you are repaired/resupplied.
        ]],
        image = "imagen_019.jpeg",
    },
    [58] = {
        step = 58,
        title = [[Guía de Leveo - Sección #20]],
        text = [[
01) Go up the mountain ramp (starting at 32.37) that allows you to enter Darkcloud Pinnacle at the top...
02) Once you get to the top do "Grimtotem Spying": loot the three Document Chests for the secret notes.  For Secret Note #1, cross the bridges up in Darkcloud Pinnacle until you get to the Document Chest 32.33 and loot it.  For the other two, see next steps...
03) Secret Note #2 is in the hut 34.40.
04) Secret Note #3 is in the hut 39.42.
05) Go over to the other pinnacle (up at 38.35) and do "Arikara": click on the Sacred Fire of Life in the middle of the pinnacle, then kill/loot Arikara (lvl 28).
06) Stay up and go north (to 38.27) then do "Wanted - Arnak Grimtotem": kill/loot Arnak Grimtotem /target.
07) Do the escort "Free at Last" (same area 38.26, #6 on map): escort Lakota Windsong /target all the way out of Darkcloud Pinnacle.
08) Go to Whitereach Post 21.32 and turn in "Homeward Bound" and "Arikara".
09) TBC, 8a) Next to you turn in "A Dip in the Moonwell" 21.33, accept "Testing the Tonic".  You can also get resupplied here from Laer Stepperunner /target.
10) You should be level 29 by now, if not grind to level 29, I grind away at centaurs around Camp E'Thok 19.25 or wyverns at Highperch (entrance is 13.34).
11) Do "Hypercapacitor Gizmo" (Elite): clear the mobs around the Panther Cage 23.25, open the cage and kill/loot the lvl 30 elite panther.
12) This is your last chance to kill/loot the centaur Galak Messenger /target.  He has a very large patrol path (see map).  He drops an item which starts "Assassination Plot", accept it.  If you can't find him in time, then skip it along with the follow up quest.
13) Go to Whitereach Post (21.33, #8 on map) and turn in "Hypercapacitor Gizmo".  Also turn in (if you did it) "Assassination Plot", then accept and do the short escort "Protect Kanati Greycloud", then turn it in.
        ]],
        image = "imagen_020.jpeg",
    },
    [59] = {
        step = 59,
        title = [[Orc/Troll - Durotar]],
        text = [[
01) Hearth to Freewind Post.
02) In the Inn, turn in (if you did it) "Free at Last" 46.52.
03) TBC, 2a) Just outside the Inn on your right turn in "Testing the Tonic"46.50.
04) By the Bonfire turn in "Grimtotem Spying" and "Wanted - Arnak Grimtotem" 46.51.
05) 03b) At this point make sure you are level 30 (or 2000 away from 30 if you can turn in "A New Ore Sample" at the next step).  Just grind on any mobs in 1kNeedles until you are there.
06) Go to the Wind Rider Master (north in Freewind Post 45.49) and if you have "A New Ore Sample" finished fly to Camp Taurajo, The Barrens to turn it in 45.58.  Then, (or otherwise) fly to Orgrimmar, Durotar.
07) Once at Orgrimmar, go get new spells/abilities.
08) Go in the Inn and make Orgrimmar your new home from the Innkeeper 54.68.
09) Go to the Bank 50.70 and put the following item into it:  Kodo Skin Scroll.  And get out (if you have it) Swim Speed Potions, you can get these from the AH as well.
10) The goal now is to go all the way to Hillsbrad Foothills.  To get there, first leave Orgrimmar at the south entrance, then get on The Undercity Zeppelin (51.14 in Durotar).  Make sure you get on the Undercity Zeppelin (south landing) and not the STV zeppelin (north landing)!  You can save some time by jumping off the zeppelin at a certain timing so you won't die and continue south onto the path!
        ]],
        image = "imagen_021.jpeg",
    },
    [60] = {
        step = 60,
        title = [[30 Hillsbrad Foothills]],
        text = [[
01) Run all the way to Tarren Mill in Hillsbrad Foothills and get the FP there from the Bat Handler (60.19 in Hillsbrad).  ALSO:  You can just bypass the UC for now (no need to get UC's FP yet) and just follow the path shown on the map to get to Hillsbrad.  NOTES:  If you can, use a Swim Speed Potion to cross the lake.  Once you reach Alterac Mountains you can start grinding on some mobs along the way to Tarren Mill.  TIP:  Focus on killing some Snapjaw turtles along the shore and save the Turtle Meat for a later quest, I recommend obtaining at least 4 Turtle Meat before moving on (you can get more later on), and remember to not sell them to a vendor!
02) Remember to get the FP at Tarren Mill from the Bat Handler (60.19 in Hillsbrad)!
03) In the church building, accept "Regthar Deathgate" 63.21.
04) Go east into Arathi Highlands... entrance 63.21
        ]],
        image = "imagen_023.jpeg",
    },
    [61] = {
        step = 61,
        title = [[30 Arathi Highlands - First Pick the Class you are playing top left of screen!!! - Along with the Game Version you are playing on (Era, SoM, TBC or WotLK)]],
        text = [[
01) Follow the path all the way to Hammerfall and accept "Hammerfall" (down by the Forge, 73.34 in Arathi Highlands).  Then get repaired/resupplied next to you 73.33.
02) SE at Hammerfall, turn in "Hammerfall" 75.36, accept "Raising Spirits".
03) Go up the steps and get the FP from the Wind Rider Master 73.33.
04) Just to the west of Hammerfall around 70.35, do "Raising Spirits": kill/loot Highland Striders (raptors).  23% drop rate.
05) Go back to Hammerfall (at Tor'gan, #2 on map) and turn in "Raising Spirits" 75.36, accept the next part.
06) Down in Hammerfall, turn in "Raising Spirits" (73.34, #1 on map), accept the next part.
07) Go back to Tor'gan and turn in "Raising Spirits" (75.36, #2 on map), SKIP "Guile of the Raptor" (for now).
08) Hearth to Orgrimmar.
09) At Orgrimmar, get your level 30 spells/abilities if you haven't yet.
10) Leave Orgrimmar at the south entrance, then get on the Zeppelin (51.13 in Durotar) to go to Grom'Gol (in STV).
11) Get the FP SE at Grom'Gol from the Wind Rider Master 33.29 .  NOTE:  For SoM/WotLK 100% quest rate, we come here only to get the FP, and we will be skipping all Nesingwary hunting quests.
        ]],
        image = "imagen_024.jpeg",
    },
    [62] = {
        step = 62,
        title = [[Horde - The Barrens]],
        text = [[
01) Hearth to Orgrimmar.  If hearthstone is still on a cooldown, then get back on the zeppelin to take you to Orgrimmar.
02) Go up to the Wind Rider Master 45.64 and fly to Crossroads, The Barrens.
03) Go west in the XRs and accept "The Swarm Grows" 51.30.
04) Go west from the XRs to the orc up in the burrow and turn in "Regthar Deathgate" 45.28, accept "The Kolkar of Desolace".
05) Run back to the Wind Rider Master at XRs 52.30 and fly to Freewind Post, Thousand Needles.
06) At Freewind Post, IF you are level 32, accept "Family Tree" by the Bonfire 46.51.
        ]],
        image = "",
    },
    [63] = {
        step = 63,
        title = [[Guía de Leveo - Sección #03]],
        text = [[
01) 32 Thousand Needles (Shimmering Flats)
02) Go SE to the Mirage Raceway in the middle of The Shimmering Flats and from the dwarf, accept "Rocket Car Parts" 78.77.  Next to you at the two gnomes 78.77, accept "Salt Flat Venom" and "Hardened Shells".  NOTE:  SKIP "Wharfmaster Dizzywig" and "Hemet Nesingwary Jr." (for now).
03) East at the Goblin's side of Mirage Raceway accept "Load Lightening" 80.76.
04) SE in Mirage Raceway by the starting line accept "A Bump in the Road" 82.78.
05) Do The Shimmering Flats grind.  Do the following 5 steps below (in any order) all together around The Shimmering Flats:
06) "Rocket Car Parts": pick up 30 Rocket Car Rubble from the ground.
07) "Hardened Shells": kill/loot turtles all over The Shimmering Flats.  ALSO:  If you have not completed the Turtle Meat turn in quest at Tarren Mill in Hillsbrad yet, then make sure you save 10 Turtle Meat for later (do not sell to vender).  You can get the Turtle Meat from any turtle at The Shimmering Flats and there is a large amount up north around 83.55.
08) "Load Lightening": kill/loot vultures (Salt Flats Scavengers & Salt Flats Vultures).  Large amount around 88.66.
09) "Salt Flat Venom": kill/loot scorpids (Scorpid Reavers & Scorpid Terrors).  Large amount around 72.73.
10) "A Bump in the Road": kill basilisks.  Saltstone Basilisks are NW, Saltstone Crystalhides are everywhere but NW, and the Saltstone Gazers are south at Tahonda Ruins around 77.86.
11) Once all done, go back to Mirage Raceway (at the gnomes section) and from the dwarf (78.77, #1 on map) turn in "Rocket Car Parts".  Accept "Wharfmaster Dizzywig" and "Hemet Nesingwary Jr.".  Then next to you 78.77, turn in "Salt Flat Venom" and "Hardened Shells".  Accept "Encrusted Tail Fins".
12) East at the goblin section of the Mirage Raceway turn in "Load Lightening" (80.76, #2 on map), accept "Goblin Sponsorship".
13) SE in Mirage Raceway by the starting line turn in "A Bump in the Road" (82.78, #3 on map).
14) Make sure you are level 32 (grind on any mobs until you are).
15) Go south to the path that leads into Tanaris (starting at 74.94)...
16) Follow the path south to Gadgetzan and get the FP there from the Wind Rider Master (52.25 in Tanaris).
17) If you have not accepted "Family Tree" from Freewind Post yet (requires lvl 32), then fly to Freewind Post, Thousand Needles and accept this by the Bonfire.
18) Hearth to Orgrimmar.  Make sure you are repaired/resupplied.
        ]],
        image = "",
    },
    [64] = {
        step = 64,
        title = [[Orgrimmar]],
        text = [[
01) Go to the Bank 50.69 and put the following items into it:  Kravel's Parts Order, Kravel's Crate and (if you are still on the turtle meat quest) your stack of Turtle Meat.  Also get the following items out: (if you have any) water breathing potions and Swim Speed Potions (for the Desolace section), try to get a stack of each if you can (you can try the AH too).  Also, make sure you save all your extra Cloths in either your bank or mailbox 51.70, you will need them later for Cloth Donation turn-ins.  If you happen to have 60 (or 120) Wool Cloth (get that out now).
02) Go NE to Magar's Cloth Goods and (if you have the 60 Wool Cloth) accept and turn in the wool cloth donation quest from Rashona Straglash 64.51.  NOTE:  We will save the Silk Cloth to build up First Aid first before the silk donations.
03) Go to the Valley of Honor and turn in "The Swarm Grows" 75.34, accept the next part.
04) Get your level 32 spells/abilities.
05) Go down to the Cleft of Shadow (entrance at 55.41) and accept "Alliance Relations".  The NPC patrols around in the Cleft of Shadow.
06) If you have 60 more Wool Cloth you can turn this in for more Wool Cloth Donations from the Troll Faction at 38.88.
07) If you haven't got Silk Bandage for First Aid yet, do that now at the First Aid Trainer 34.85 at the Valley of Spirits.
08) West in Orgrimmar, turn in "Alliance Relations" (in the hut 23.53), accept the next part.
09) Stay up and go over to the Wind Rider Master 45.64 and fly to Sun Rock Retreat, Stonetalon Mountains.
10) Go to the path SW in Sun Rock Retreat 45.62 to go to the Charred Vale, then run south into Desolace (entrance 30.78)...
        ]],
        image = "",
    },
    [65] = {
        step = 65,
        title = [[34 Desolace]],
        text = [[
01) N/A
02) N/A
03) Go to Ghost Walker Post (entrance at 57.57)...
04) Make a left at the main entrance, then turn in "The Kolkar of Desolace" 56.60.  Accept "Khan Dez'hepah".
05) Just north a bit at the hut get repaired/resupplied and turn in "Family Tree" 55.56.  Then go across the bridge in Ghost Walker Post and turn in "Alliance Relations" 53.54.  Accept the next part.  Also accept (from the same NPC) "Befouled by Satyr".
06) Next to you, turn in "Alliance Relations" 52.53, accept "The Burning of Spirits".
07) Go east to the Kolkar Village and do "Khan Dez'hepah": kill/loot Khan Dez'hepah /target.  This big bearded centaur is usually in the bigger tent 73.42, but can sometimes be found in other areas around the Kolkar Village as well, so you may need to grind around the village to find him.
        ]],
        image = "",
    },
    [66] = {
        step = 66,
        title = [[Contested - Stranglethorn Vale]],
        text = [[
01) N/A
02) N/A
03) Go to Ghost Walker Post, make a left at the entrance (56.57, #3 on map) and then turn in "Khan Dez'hepah" 56.60.  SKIP "Centaur Bounty".
04) N/A
05) Continue following the main path west to Shadowprey Village and accept "Hunting in Stranglethorn" 25.72.
06) Go up in the village and accept "Hand of Iruxos" (on top of the mound next to the gong 26.68).
07) Go in the Inn 24.68 and make Shadowprey Village your new home from the Innkeeper.  Make sure you are repaired/resupplied.  If you still have "A New Ore Sample" in your log, abandon it.
        ]],
        image = "",
    },
    [67] = {
        step = 67,
        title = [[Guía de Leveo - Sección #07]],
        text = [[
01) Go down to the docks and accept "Other Fish to Fry" 23.73.
02) Next to you in the hut, accept "Clam Bait" 23.72.
03) N/A
04) Make sure you are resupplied from Lah'Mawhani 23.72 up in the hut.  Then swim north up the water (use Swim Speed Potions if you have them) and work your way to the wrecked boat at the shore and from Rackmore's Log 36.30 sitting on the barrel, accept "Claim Rackmore's Treasure!".
05) Go up to The Argent Dawn dude and accept "Sceptre of Light" 39.27.
06) Go east to the Thunder Axe Fortress (entrance at 56.29) and do "The Burning of Spirits": use the Burning Gem quest item on the mobs at the fortress right before they die to collect the Infused Burning Gems.  While working on this, do the following 2 steps below as well:
07) Do "Sceptre of Light": as you enter Thunder Axe Fortress, make a left, go up the watchtower (ramp entrance at 55.30) and kill/loot the Burning Blade Seer.
08) GROUP 2+ Players: Go in the fortress entrance 55.27 and do "Hand of Iruxos": click on the Hand of Iruxos Crystal 55.27 in the middle and then kill/loot the Demon Spirit that spawns.  Be prepared to kill the lvl 37 demon! (See Video).
        ]],
        image = "",
    },
    [68] = {
        step = 68,
        title = [[Guía de Leveo - Sección #08]],
        text = [[
01) Before leaving the Thunder Axe Fortress, make sure you have found an item called Flayed Demon Skin (2% drop rate), which starts "The Corrupter".
02) Go to Ghost Walker Post (shortcut at 56.54)...
03) N/A
04) Then go across the bridge in Ghost Walker Post 52.53 and turn in "The Burning of Spirits" and "The Corrupter", accept the next part.
05) Go NE to Sargeron around 74.22 and do "Befouled by Satyr" along with "The Corrupter": kill the required amount of Hatefury Satyrs: Rogue Felsworn Betrayer Hellcaller .  And kill/loot the Hatefury Shadowstalkers /target until a Shadowstalker Scalp drops.
06) Go SW to Kormek's Hut and accept "Bone Collector" 62.39.  Requires lvl 33.  If you are not 33, ignore this step and you will be able to accept this later in the guide.  NOTE:  You can get resupplied from Vendor-Tron 1000 /target if he is there.
07) Go to Ghost Walker Post (shortcut at 56.54, #2 on map), then go across the bridge and turn in "Befouled by Satyr" (53.54, #4 on map), accept "Alliance Relations".
08) Next to you, turn in "The Corrupter" 52.53, accept the next part.  Make sure you are resupplied 51.53.
        ]],
        image = "",
    },
    [69] = {
        step = 69,
        title = [[Guía de Leveo - Sección #09]],
        text = [[
01) Go NW up to The Argent Dawn dude and turn in "Sceptre of Light" 39.27, accept "Book of the Ancients".
02) Go to where the boat is under the water around 34.32 and do the first part of "Claim Rackmore's Treasure!": kill/loot the Drysnap mobs for the Silver Key (15% drop rate).  Also start working on "Clam Bait" by kill/looting crabs and looting Giant Softshell Clams.  Use a water breathing potion if you have one.  As you do the following steps, you should find the Golden Key from any Slitherblade mob...
03) Do "Book of the Ancients": grind your way to the NW end of the bigger island and click on the Serpent Statue 28.7, then kill/loot Lord Kragaru when he spawns. (See Video)
04) Do the last part of "Claim Rackmore's Treasure!": Once you find the Golden Key from any Slitherblade mob, click on Rackmore's Chest 30.9 on the bigger island to turn this in.
05) Do "The Corrupter": kill/loot the Slitherblade Oracles /target in the water and on the 2 bigger islands until you get the Oracle Crystal (low drop rate).  Use a water breathing potion if you have one.
06) Finish up "Other Fish to Fry": kill the needed Slitherblade mobs.  The Myrmidon are scattered between the two biggest islands, the Naga are more towards the shore around 36.24 and there are only a few Sorceresses scattered everywhere.
07) Make sure "Clam Bait" is finished: collect Soft-shelled Clam Meat from Enraged Reef Crawlers (crabs) or from the Giant Softshell Clams under the water (around #2 on map around 36.24 and slightly north of it as well).
08) Go up to The Argent Dawn dude and turn in "Book of the Ancients" (39.27, #1 on map).
09) If you have not accepted "Bone Collector" yet, do so now at Kormek's Hut 62.39.
10) Go to Ghost Walker Post (shortcut at 56.54)....
11) Make sure you are repaired/resupplied 56.56, then go across the bridge and turn in "The Corrupter" 52.53.  Wait a few seconds, then accept the next part.
12) Next to you, turn in "The Corrupter" 53.54, SKIP the next part (for now).
        ]],
        image = "",
    },
    [70] = {
        step = 70,
        title = [[Horde - The Barrens]],
        text = [[
01) At the Kodo Graveyard next to you around 53.57, do "Bone Collector": loot the Kodo Bones on the ground.  NOTE:  Looting some of these bones spawns a high lvl Kodo Apparition.
02) N/A
03) Go to Ghost Walker Post, entrance 57.57...
04) N/A
05) Stop at the hut just north to get repaired/resupplied from Muuran 56.57.
06) Grind your way NE to Kormek's Hut and turn in "Bone Collector" 62.39.
07) Hearth to Shadowprey Village.
08) Just outside of the Inn, and up on the mound, turn in (if you have it) "Hand of Iruxos" 26.68, SKIP "Portals of the Legion" (for now).
09) N/A
10) Go back west to Shadowprey Village and down at the docks turn in "Other Fish to Fry" 23.73 and next to you at the hut "Clam Bait" 23.72.
11) Go to the Wind Rider Master 22.74 at the end of the docks at Shadowprey Village and fly to Camp Taurajo, The Barrens.
        ]],
        image = "imagen_010.jpeg",
    },
    [71] = {
        step = 71,
        title = [[Horde - The Barrens]],
        text = [[
01) Once at CT, run SE into Dustwallow Marsh ( 51.79 in The Barrens) and collect the 3 quest-objects at the Shady Rest Inn (See Video):  "Suspicious Hoofprints" (on the ground in front of the old Inn 51.79), "Lieutenant Paval Reethe" (a small white dot on a plank 30.48) and "The Black Shield" (on the fireplace 30.49).
02) Go NE to Brackenwall Village 36.32 and turn in "The Black Shield" (accept the next part), "Suspicious Hoofprints" and "Lieutenant Paval Reethe".
03) Next to you from Do'gol, turn in "The Black Shield" 37.31, SKIP the next part (for now).
04) Go to the Wind Rider Master 36.32 and fly to Ratchet, The Barrens.
05) Go to Gazlowe in the engineering building and turn in "Goblin Sponsorship" (63.36 in The Barrens), accept the next part.
06) Go to the Bank 63.37 and get the following items out:  Kravel's Parts Order, Kravel's Crate and Silk Cloth (to build up First Aid).  Put in the bank:  Belgrom's Sealed Note.
07) Go to the goblin on the docks and turn in "Wharfmaster Dizzywig" 63.38, accept "Parts for Kravel".
08) Get on the boat to go to BB (Booty Bay) 64.39.  While waiting for the boat, build up First Aid.
        ]],
        image = "imagen_011.jpeg",
    },
    [72] = {
        step = 72,
        title = [[36 Stranglethorn Vale]],
        text = [[
01) As soon as you get off the boat, turn in "Goblin Sponsorship" 26.74, accept the next part.
02) Go in the Inn (The Salty Sailor Tavern) and make BB your home from the Innkeeper 27.77.  Next to you in the Inn, accept "Singing Blue Shards".
03) Go upstairs in the Inn and accept "Bloodscalp Ears", "Hostile Takeover" and "Investigate the Camp".
04) Stay up on the top of the docks and go over past the Alliance FP to Tan-Your-Hide Leatherworks and accept "Supply and Demand" 28.78.
05) Go back over to the top of the Inn and then go up the steps to Baron Revilgaz 27.77 on the boat-deck and turn in "Goblin Sponsorship", accept the next part.
06) Next to you on the roof, go to the Wind Rider Master 27.77 and fly to Grom'gol, Stranglethorn.
07) In Grom'gol accept the following: "The Defense of Grom'gol" 32.29, "Mok'thardin's Enchantment" 32.29, "Bloodscalp Insight" (next to Bonfire 32.29), "Hunt for Yenniku" 32.28,"Bloody Bone Necklaces"and "The Vile Reef".  Make sure you are repaired/resupplied.
08) REMINDER:  The "The Green Hills of Stranglethorn" quest requires that you save any Green Hills of Stranglethorn pages you find.  These pages can drop from any humanoid mob in STV.  You will need one of each of the following pages: 1, 4, 6, 8, 10, 11, 14, 16, 18, 20, 21, 24, 25, 26, and 27.  I recommend mailing them to your alt for storage.  Once your alt collects all the pages, mail them back to your main.  You can also find these pages in the AH or from other players.  You don't need to accept the quest to get the page drops, so accept and turn this in at Nesingwary's Expedition 36.11 if you get all the pages.  You will return to STV numerous times in the future for more chances to find the pages.
