    [74] = {
        step = 74,
        title = [[Contested - Stranglethorn Vale]],
        text = [[
01) Go up north to the troll Ruins around 20.14 and do "Headhunting" along with finishing up "Bloody Bone Necklaces": kill/loot the trolls around the Ruins for the necklaces (low drop rate).  And kill/loot the Bloodscalp Headhunters for the Shrunken Heads.  You can kill lower level trolls for the necklaces down south at the two ruins (between step #3 on map).
02) Go to Nesingwary's Expedition 36.11 and turn in "Hemet Nesingwary Jr.", "Hunting in Stranglethorn"  Get repaired/resupplied from Jaquilina Dramet.
03) N/A
04) At the river east around 34.9 of you do "Supply and Demand": kill/loot River Crocolisk.  And continue working on (if you still need to) "Singing Blue Shards" by kill/looting Stone Maw Basilisk around the north end of the river.  Work your way to the next step:
05) Go SE across the river to the Venture Co. Operations Center and do "Hostile Takeover": kill/loot the Venture Co. Geologist /target scattered around the Operations for the 8 crystals.  Also do the first part of "Goblin Sponsorship": work your way to the top of the Operations Center entrance 42.18 and then kill/loot Foreman Cozzle (in the control room, 43.18).  See next step for where to use Cozzle's Key at...
06) Do the last part of "Goblin Sponsorship": loot Cozzle's Footlocker (in the small house 43.20).  NOTE:  Your key will disappear as soon as you click the chest, so make sure you have room in your bags for the Blueprints.
07) Go east and do "Mok'thardin's Enchantment": kill/loot Shadowmaw Panthers /target around 49.23.  Also kill/loot Stranglethorn Tigress around the same area for the fang.
08) Finish (if you still need to) "Singing Blue Shards": kill/loot Crystal Spine Basilisks just NE around the mountain ledges around 48.8.
09) Go west across the river to Mizjah Ruins around 37.31 and do "The Defense of Grom'gol": kill the required amount of Mosh'Ogg ogres.
10) Hearth to BB.
        ]],
        image = "imagen_014.jpeg",
