    [75] = {
        step = 75,
        title = [[Contested - Stranglethorn Vale]],
        text = [[
01) In the Inn, turn in "Singing Blue Shards" 27.77, SKIP "Venture Company Mining" (for now).
02) Go upstairs in the Inn and turn in "Bloodscalp Ears", "Hostile Takeover" and "Investigate the Camp".
03) Stay up on the top of the docks and go over past the Alliance FP to Tan-Your-Hide Leatherworks and turn in "Supply and Demand" 28.78.  Accept "Some Assembly Required".
04) Go back over to the top of the Inn and then go up the steps to Baron Revilgaz 27.77 on the boat-deck and turn in "Goblin Sponsorship", accept the next part.
05) Next to you on the roof, go to the Wind Rider Master 27.77 and fly to Grom'gol, Stranglethorn.
06) Turn in ALL quests in Grom'gol: "The Defense of Grom'gol", "Mok'thardin's Enchantment" (SKIP the next part for now), "An Unusual Patron", "Headhunting", "Bloody Bone Necklaces" and "The Vile Reef".  Accept "Trollbane".
07) You should be level 36 now, if not grind to it.
08) Get on the zeppelin to go to the The Undercity (up in the Inn, 32.29).  Build up First Aid while waiting.
09) Go to the Bank in the middle of UC 66.44 and get out the following items:  (if you have any) Elixir of Water Breathing potions.  If you were able to get an Elixir of Water Breathing, also get out (if you have any) a stack of Swim Speed Potions, and (if you are still on the turtle meat quest) your stack of Turtle Meat . Also put in the bank:  10 stack of Encrusted Tail Fin, Fuel Regulator Blueprints and Kravel's Parts.
10) Go up and accept "To Steal From Thieves" 64.49.
11) Next to you at the Bat Handler 63.49, fly to Tarren Mill, Hillsbrad.
12) Once at Tarren Mill, accept "The Hammer May Fall" (from Tallow 62.20).
13) If you have not finished the Turtle Meat turn-in yet, do so now... Go in the Inn (bigger house 62.19).  From Christoph Jeffcoat, accept "Soothing Turtle Bisque" (requires the cooking profession to accept).  From this NPC, buy a Soothing Spices.  Then wWith your Turtle Meat you farmed earlier, simply turn in the quest right there.
14) Go to the Bat Handler 60.19 and fly to Hammerfall, Arathi.
        ]],
        image = "imagen_015.jpeg",
