    [76] = {
        step = 76,
        title = [[37 Arathi Highlands]],
        text = [[
01) Go in the Inn and make Hammerfall your new home from the Innkeeper 74.32.  Make sure you are repaired/resupplied.
02) On the balcony next to you, turn in "Trollbane" 74.34, accept "Sigil of Strom".
03) Go down to Tor'gan 75.36 and accept "Foul Magics" and "Guile of the Raptor".
04) Go west and click on the Shards of Myzrael 62.34 to accept "The Princess Trapped".
05) Go east of Hammerfall and do "The Princess Trapped": kill/loot the Drywhisker kobolds, in and outside of the cave (entrance at 83.36).  TIPS:  Look for the tree and rock 81.40, it shows you where the hidden path is to the cave.  If you have mining, then mine as many Lesser Bloodstone Deposits as you can.  These are used for an Alliance quest only at STV and sell good in the neutral AH.
06) Once done, go to the Iridescent Shards (at the end of the cave 84.31) and turn in "The Princess Trapped", accept "Stones of Binding".
07) If you have 225 First Aid now, then go to Hammerfall and in the building accept and do "Triage" 73.37: use the Triage Bandage quest item right there in the room on the wounded soldiers (See Video).  Once done, turn it in.  You can also destroy the Triage Bandage in your inventory as it is no longer needed.  If you were not able to do this quest yet, you will be farming more cloth in Arathi to try again later. NOTE: In WotLK, this doctor no longer advances your First Aid, you now just do that at any First Aid trainer.
08) Go up the steps in Hammerfall and make sure you are repaired/resupplied.  Then take the north exit 73.30 and go west to the Circle of East Binding and do part of "Stones of Binding": loot the Stone of East Binding 67.30 for the Cresting Key.
09) Go west to Dabyrie's Farmstead and do "To Steal From Thieves": kill/loot the 3 named mobs.  Kill/loot Kenata Dabyrie /target (up in the small house 56.36).  See next steps for the other 2...
10) Kill/loot Fardel Dabyrie /target (standing outside next to the barn 57.39, or in front of the stables 54.38)...
11) Kill/loot Marcel Dabyrie /target (in the stables 54.38).
        ]],
        image = "imagen_016.jpeg",
    },
    [77] = {
        step = 77,
        title = [[Guía de Leveo - Sección #17]],
        text = [[
01) Go south a bit and do part of "Stones of Binding": loot the Stone of Outer Binding 52.51 for the Thundering Key.
02) Go south and do "Guile of the Raptor": kill/loot Highland Fleshstalkers around 50.64.
03) Go NW to Boulder'gor and do "The Hammer May Fall": kill the Boulderfist Ogres (outside of the mine) and the Boulderfist Enforcers (inside of the mine 35.44).
04) Go north to Northfold Manor around 32.28 and do "Foul Magics": kill/loot the Syndicate mobs.  Any of them can drop the amulets.
05) Go west and do the last part of "Stones of Binding": loot the Stone of West Binding 25.30 for the Burning Key.
06) Do "Sigil of Strom": at the east side in Stromgarde Keep around 28.61 kill/loot the Syndicate Prowlers, Conjurors and Magus for the Sigil of Strom.
07) Go slightly east and click on the Stone of Inner Binding to turn in "Stones of Binding" 36.57, accept "Breaking the Keystone".
        ]],
        image = "imagen_017.jpeg",
    },
    [78] = {
        step = 78,
        title = [[Guía de Leveo - Sección #18]],
        text = [[
01) Hearth to Hammerfall.
02) On the balcony just outside the Inn, turn in "Sigil of Strom" 74.34, SKIP "The Broken Sigil" (for now).
03) Next to you on the balcony turn in "The Hammer May Fall" 74.34, accept "Call to Arms".
04) Go SE in Hammerfall at Tor'gan 75.36 and turn in "Foul Magics" and "Guile of the Raptor" (accept the next part).
05) Go down in Hammerfall and turn in "Guile of the Raptor" 73.34.  Wait a few seconds then accept the next part.  Make sure you are repaired/resupplied by the Forge.
06) Go back up to Tor'gan (75.36, #4 on map) and turn in "Guile of the Raptor", SKIP "Foul Magics".
07) Grind south to Witherbark Village around 67.63 and do "Call to Arms": kill the required amount of Witherbark trolls around the village.
08) Grind back north to Hammerfall and up the steps turn in "Call to Arms" 74.34, accept the next part.  Make sure you are repaired/resupplied.
09) While doing the rest of Arathi quests, if you happen to run across the lvl 42 Giant named Fozruk /target, you can kill/loot him for "Breaking the Keystone".  This giant has a large patrol path (see map).  Don't intentionally try to find him.  If you did kill/loot him, then turn this in (at 36.58) and accept the next part.  NOTE:  The follow up quests are worth doing as they are easy to solo, but are not covered in the guide.
10) Grind SW to Boulderfist Hall around 54.73 and do "Call to Arms": kill the required amount of Boulderfist ogres.  If you still need to do "Triage", then make sure you get your First Aid skill to 225 before proceeding.
11) Hearth (or grind back 74.34 if its still on a cooldown) to Hammerfall.  Make sure you are repaired/resupplied.
12) On the deck turn in "Call to Arms" 74.34.
13) NOTE: due to the faster leveling changes, we will be skipping the Stromguard quests ("Call to Arms", "The Broken Sigil", "The Real Threat" and "Foul Magics").
14) If you have not done the First Aid quest "Triage" yet, do so now:
15) (click to show instructions):
16) Go up to the Wind Rider Master 73.33 and fly to Tarren Mill, Hillsbrad.  If "Breaking the Keystone" is still in your quest book, abandon it.
        ]],
        image = "imagen_018.jpeg",
    },
    [79] = {
        step = 79,
        title = [[37 Alterac Mountains]],
        text = [[
01) Once at TM, go in the small house 62.21 and accept "Prison Break In" & "Stone Tokens".
02) TBC, 1a) At the church entrance accept "The Crown of Will" 63.21.
03) Go north to the small cave (38.66 in Alterac Mountains) and on the way kill/loot a cat for a Fresh Carcass.
04) At the small cave do "Frostmaw": use the Fresh Carcass quest item at the Flame of Uzel (38.66, #2 on map), then kill/loot Frostmaw /target when he spawns.  This yeti spawns just outside of the cave. (See Video)
05) TBC, 3a) Go up north (take hill entrance at 39.62) to Ruins of Alterac and do "The Crown of Will": kill 10 Crushridge Maulers /target around 41.49.
06) Go west (take hill exit at 38.61) to Lordamere Internment Camp and do "Stone Tokens" along with "Prison Break In": kill/loot the Dalaran humans for the tokens and kill/loot the 4 named mobs.  First one is Ricter 20.84 outside in front of the outhouses.  See next steps for the others...
07) Kill/loot Alina and Dermot inside the building 20.86 next to the outhouses.
08) Kill/loot Kegan Darkmar upstairs in the other building 18.83.  NOTE:  There are more Dalaran mobs to kill for the tokens at Dalaran (just outside of the big purple globe).
09) N/A
10) Run back to Tarren Mill and in the small house 62.21, turn in "Prison Break In" and "Stone Tokens", accept "Dalaran Patrols" and "Bracers of Binding".  Make sure you are repaired/resupplied.
11) TBC, 8a) At the church entrance turn in "The Crown of Will" 63.21 , SKIP the next part.
12) Go north into Alterac Mountains (follow path on map) and do "Bracers of Binding" along with "Dalaran Patrols": kill 4 Dalaran Summoners and kill/loot the Elemental Slaves.  Done around the purple Dalaran globe (around 19.76 in Alterac Mountains).
13) Once done, go back to Tarren Mill.  Make sure you are repaired/resupplied.
14) In the small house, turn in "Dalaran Patrols" and "Bracers of Binding" (62.21, #8 on map).
15) Go to the Bat Handler 60.19 and fly to Undercity, Tirisfal.
        ]],
        image = "imagen_020.jpeg",
