    [80] = {
        step = 80,
        title = [[Undead - Tirisfal Glades]],
        text = [[
01) Right where you land at the UC, turn in "To Steal From Thieves" 64.49.
02) Go to the Bank (in the middle of UC, 66.44) and get the following items out:  10 stack of Encrusted Tail Fin, Belgrom's Sealed Note, Fuel Regulator Blueprints and Kravel's Parts.  Also get out (if you have it) 60 Wool Cloth and then 60 Silk Cloth for cloth donations in Orgrimmar.  Put in the bank:  any Swim Speed Potions.
03) Leave the UC and get on a zeppelin to go to Orgrimmar (61.59 in Tirisfal Glades).
04) Go west in Orgrimmar (take the ramp at 42.62)...
05) Go SW to Valley of Spirits in Darkbriar Lodge and (if you have them) turn in 60 Wool Cloth and then 60 Silk Cloth for cloth donations from Vehena 38.88 for the Troll faction.
06) WOTLK, 5b) You can stop at the First Aid Trainer 34.85 to upgrade First Aid.
07) Continue west to Keldran in the hut and turn in "Alliance Relations" 23.53.
08) Stay up and go over to the Wind Rider Master 45.64 and fly to Crossroads, The Barrens.
09) Go in XR's Inn 52.30 and make it your new home.
10) Go to the Wind Rider Master 52.30 and fly to Freewind Post, Thousand Needles.
        ]],
        image = "imagen_021.jpeg",
    },
    [81] = {
        step = 81,
        title = [[38 Thousand Needles (Shimmering Flats)]],
        text = [[
01) Make sure you are repaired/resupplied.
02) Run east towards Ironstone Camp (right next to Shimmering Flats) and turn in "The Swarm Grows" 68.64, accept the next part.
03) Go to the west side of Mirage Raceway and at the dwarf 78.77, turn in "Parts for Kravel".  Wait a few seconds, then accept "Delivery to the Gnomes".
04) Next to you, turn in "Delivery to the Gnomes" 78.77.  Accept "Martek the Exiled".  Also turn in "Encrusted Tail Fins".
05) Back at the dwarf next to you accept "The Rumormonger" (78.77, #3 on map).
06) Go east to the Goblin's side and turn in "Goblin Sponsorship" 80.76, accept "The Eighteenth Pilot".
07) Next to you, turn in "The Eighteenth Pilot" 80.76, accept "Razzeric's Tweaking".
08) Go SW to The Rustmaul Dig Site and do "The Swarm Grows": kill the required amount of Silithid bugs.  There is only a few Invaders in the cave entrance 66.86 so go for these guys first.  The Searchers are up and around the Dig Site.  Within the first few mobs you kill, you should receive an item which starts "Parts of the Swarm", accept it and start doing it in the same area by kill/looting the Silithid mobs, and the items you need can drop from any of them.
09) Make sure you are at least 2 bars away from level 38.  Grind on the bugs until you are.
10) Go north to Ironstone Camp and turn in "The Swarm Grows" (68.64, #2 on map).
        ]],
        image = "imagen_022.jpeg",
    },
    [82] = {
        step = 82,
        title = [[Tauren - Mulgore]],
        text = [[
01) Hearth to XRs.
02) Go west in the XRs and turn in "Parts of the Swarm" 51.30, accept the next part.  NOTE:  If the Cracked Silithid Carapace remains in your bags, destroy it.
03) Go to the Wind Rider Master 52.30 and fly to Thunder Bluff, Mulgore.
04) N/A
05) Go to The Hunter Rise and turn in "Frostmaw" 62.81.  Accept "Deadmire".
06) GET NEW ABILITIES, 5b) You should be level 38 now.  Get new spells/abilities for your class.
07) Go to the Bank 47.59 and put the following item into it:  Fizzle Brassbolts' Letter.
08) Go up to the Wind Rider Master in the middle of TB 47.50 and fly to Brackenwall Village, Dustwallow Marsh.
