        image = "imagen_023.jpeg",
    },
    [83] = {
        step = 83,
        title = [[38 Dustwallow Marsh]],
        text = [[
01) West at Brackenwall Village, from Nazeer Bloodpike 35.31, accept "Theramore Spies" and "Check Up on Tabetha".
02) From the male blood elf accept "Twilight of the Dawn Runner" 36.32.
03) From Do'gol (ogre), accept "The Black Shield" 37.31.  Make sure you are repaired/resupplied.
04) Go to the Innkeeper (blue ogre at small cave entrance 37.32) to make Brackenwall Village your new home.
05) In the small cave accept "The Hermit of Witch Hill" 37.33.
06) Go slightly south of Brackenwall Village and accept "Hungry!" (from the ogre at 35.38).
07) Start working on "Theramore Spies" along with "The Black Shield": kill Theramore Infiltrators /target and kill/loot any type of spiders.  Grind your way to the next step...
08) Stinky, 7b) See if you can do the escort "Stinky's Escape" 47.18 (#16 on map): escort "Stinky" Ignatz.  NOTE: If he is not there, then skip this for now.  You will have more opportunities to try again later.
09) Go east to North Point Tower (entrance at 47.24) and do "Twilight of the Dawn Runner": at the bottom of the tower talk to Ithania /target to free her, then go to the top of the tower to loot the Warped Crates.
10) Go east to Jarl's cabin 55.26 and turn in "The Hermit of Witch Hill", accept "Marsh Frog Legs".  Next to you at the cabin accept "What's Haunting Witch Hill?" (this NPC is either in the cabin or on the dock).
11) Right next to Jarl's cabin, click on the Loose Dirt 55.26 to accept "The Lost Report".
12) All around Jarl's Cabin do "Marsh Frog Legs" along with "What's Haunting Witch Hill?": kill/loot Giant Marsh Frogs (frog critters /target).  And kill the undead mobs (Risen Spirits and Risen Husks).
13) Back at Jarl's cabin 55.26 (#9 on map) turn in "Marsh Frog Legs", accept "Jarl Needs Eyes".  Next to you at the cabin turn in "What's Haunting Witch Hill?", accept "The Witch's Bane".
14) All around Jarl's cabin start working on "The Witch's Bane" by looting witchbane (plants, mostly around #11 on map), that you see along the way:
15) Go NE to the shore around 57.17 and do "Hungry!": kill/loot the Mirefin (murlocs).
16) Exit at 58.19.
17) If you have not done the escort "Stinky's Escape" 47.18: escort "Stinky" Ignatz and grind mobs during the escort.  NOTE: If he is not there, then skip this for now.  You will have one more opportunity to try this again later.
18) All around Jarl's cabin finish "The Witch's Bane": loot 9 witchbane (plants, mostly around #11 on map).
19) Back at Jarl's cabin turn in "The Witch's Bane" 56.26 (#9 on map), accept "Cleansing Witch Hill".
20) Do "Cleansing Witch Hill": at the end of the dock there at Jarl's cabin 55.27 use the Witchbane Torch quest item then kill Zelfrax (gargoyle) when he spawns.
21) Back at Jarl's cabin turn in "Cleansing Witch Hill" 56.26 (#9 on map).
22) Finish up "Theramore Spies": kill 9 Theramore Infiltrators /target just NE of Brackenwall Villagearound 42.26 (#7 on map).
23) Go west to Darkmist Cavern around 35.22 and do "Jarl Needs Eyes": kill/loot the Darkmist spiders for 20 eyes.  Also make sure "The Black Shield" is finished by kill/looting any spiders.
24) Go to the west side in Brackenwall Village 35.31 (#1 on map) and turn in "Theramore Spies", accept "The Theramore Docks".  And turn in "The Lost Report".
25) From the male blood elf turn in "Twilight of the Dawn Runner" 36.32 .
26) Turn in "The Black Shield" 37.31, accept the next part.
27) At Krog, turn in "The Black Shield" 36.32.  Make sure you are repaired/resupplied.
28) Go just south of Brackenwall Village at the ogre and turn in "Hungry!" 35.38 (#6 on map).
29) Go SE to the ogre (41.37 /target) on the path and accept and do the escort "Questioning Reethe": follow Ogron, then kill the mobs that spawn in next to Paval Reethe.
        ]],
        image = "imagen_024.jpeg",
    },
    [84] = {
        step = 84,
        title = [[Guía de Leveo - Sección #27]],
        text = [[
01) Head SE to Tabetha's Farm and inside the cabin turn in "Check Up on Tabetha" 46.57.  Accept "Help for Mudsprocket".  And next to you accept "The Grimtotem Weapon" and "The Reagent Thief".
02) Just outside at the side of the cabin 46.57 accept "Direhorn Raiders" and "The Zeppelin Crash".
03) Go east to Beezil's Wreck 54.57 and turn in "The Zeppelin Crash".  Accept "Corrosion Prevention" and "Secure the Cargo!".
04) At Beezil's Wreck do "Razzeric's Tweaking": loot the Gizmorium Shipping Crate (box at 54.56).
05) Around the immediate area do "Corrosion Prevention" along with "Secure the Cargo!": stand near a Power Core Fragment to obtain a buff, then use the Ooze Buster quest item on oozes.  NOTE:  You don't actually need to attack the oozes.  And loot 8 Zeppelin Cargo (boxes laying around).
06) Back at Beezil's Wreck 54.57 (#4 on map) turn in "Corrosion Prevention" along with "Secure the Cargo!", accept "Delivery for Drazzit".
07) Go NW to Direhorn Post and in the NE tent kill/loot Apothecary Cylla 47.47, she drops an item which starts "Signs of Treachery", accept it.
08) In the immediate area around Direhorn Post do "Direhorn Raiders": kill 12 Grimtotems (taurens of any type).
09) Around The Quagmire around 43.49 do the next 3 quests together:
10) "The Reagent Thief": kill/loot Noxious Shredders (green serpents) or Darkfang Creepers (orange spiders).  These are around #1 on map.
11) "The Grimtotem Weapon": use the Captured Totem quest item at the Mottled Drywallow Crocolisk or a Drywallow Daggermaw, then kill them.  NOTE: The crocs must be pulsed by the totem on death to get credit.
12) "Deadmire": kill/loot Deadmire /target.  This white crocolisk patrols around, mostly around the eastern part of #11 on map around 48.56.
13) Back at Tabetha's Farm and inside the cabin 46.57 (#2 on map) turn in "The Grimtotem Weapon" and "The Reagent Thief".
14) Just outside at the side of the cabin 46.57 turn in "Direhorn Raiders".
