    [85] = {
        step = 85,
        title = [[Tauren - Mulgore]],
        text = [[
01) Go SW to Mudsprocket (neutral goblin town specific to TBC) and in the hut 42.73 turn in "Delivery for Drazzit" and "Help for Mudsprocket".
02) At the NE outskirts of town, go to the Flight Master 43.72 and fly to Brackenwall Village, Dustwallow Marsh.  NOTE: We will do the Mudsprocket quests when we return back to Dustwallow Marsh at level 43.
03) At Krog, turn in "Questioning Reethe" 36.32.  Accept "The Black Shield".
04) If you have not done the escort "Stinky's Escape" 47.18: escort "Stinky" Ignatz.  NOTE: If he is not there, then this will have to be skipped.
05) Go east to Jarl's cabin 55.26 and turn in "Jarl Needs Eyes", accept "Jarl Needs a Blade".
06) Right next to Jarl's cabin, click on the Loose Dirt to accept "The Severed Head" 55.26.
07) Just NE at Witch Hill do "Jarl Needs a Blade": kill/loot Razorspine patrols around 58.19.  Spawns at 58.18.
08) Back at Jarl's cabin turn in "Jarl Needs a Blade" 55.26 (#5 on map).
09) Go all the way behind the Alliance town (Theramore Isle) and do "The Theramore Docks": loot Captain's Footlocker (under the water 72.51).  NOTE:  Do not go through the town, just go around the side of the town and into the water.  (See Video)
10) Hearth to Brackenwall Village.
11) West in Brackenwall Village 35.31, turn in "The Theramore Docks", "The Severed Head" (accept "The Troll Witchdoctor") and "Signs of Treachery".
12) Go to the Wind Rider Master 36.32 /target and fly to Thunder Bluff, Mulgore.
