    [86] = {
        step = 86,
        title = [[Horde - The Barrens]],
        text = [[
01) CLOTH DONATIONS?  If you happen to have 60 Wool Cloth, then 60 Silk Cloth and then 60 Mageweave Cloth, get those out (for cloth donations in a bit).  Bank 47.59.
02) Go to the NW hut on The Hunter Rise and turn in "The Black Shield" 54.81, accept "Return to Krog".
03) Also on the Hunter Rise, turn in "Deadmire" 62.81.
04) If you have either 60 Wool Cloth, 60 Silk Cloth or 60 Mageweave Cloth go turn them in up in the hut from Rumstag Proudstrider 43.43 (Tauren faction cloth donations).
05) Go to the top of the tower to the Wind Rider Master 47.50 and fly to Ratchet, The Barrens.
06) At Ratchet next to the bank, turn in "Stinky's Escape" 62.38.
07) At the Bank 63.37, get the following items out:  (if you have any) Swim Speed Potions and any Elixer of Water Breathing potions.  Put into the Bank: Seaforium Booster.
08) Get on the boat 64.39 to go to BB...
        ]],
        image = "imagen_029.jpeg",
