    [87] = {
        step = 87,
        title = [[40 Stranglethorn Vale]],
        text = [[
01) Once at BB, follow the lower docks and then accept "The Bloodsail Buccaneers" 28.76.
02) Go in the small cabin (next to the hanging shark) and accept "Scaring Shaky" 28.77.
03) Go in the Inn and make BB your new home 27.77.
04) Go up the stairs in the Inn and turn in "The Rumormonger", accept "Dream Dust in the Swamp".
05) Next to you on the roof, go to the Wind Rider Master 27.77 and fly to Grom'gol, Stranglethorn.
06) At Grom'gol, accept "Mok'thardin's Enchantment" 32.29.
07) By the Cauldron, turn in "The Troll Witchdoctor" 32.28.
08) Make sure you are repaired/resupplied.
09) Go south around 31.42 and do "Mok'thardin's Enchantment": kill/loot Jungle Stalkers.
10) Make sure you are at least a half a bar away from level 39 (keep grinding on Jungle Stalkers & Cold Eye Basilisks until you are).
11) Then go back to Grom'gol and turn in "Mok'thardin's Enchantment" (32.29, #7 on map), accept the next part.  Make sure you are repaired/resupplied.
12) N/A
13) Go east to the river around 39.29 and do "Some Assembly Required": kill/loot Snapjaw Crocolisks /target along the river.
14) N/A
15) N/A
16) Hearth to BB.  Make sure you are repaired/resupplied.
