    [88] = {
        step = 88,
        title = [[Contested - Stranglethorn Vale]],
        text = [[
01) Go just slightly NW of BB and clear the Bloodsail (humans) from the area, then click on the Bloodsail Correspondence scroll (on the barrel 27.70) to turn in "The Bloodsail Buccaneers", accept the next part.  (See Video)
02) Go NE to Mistvale Valley around 32.67 and do "Scaring Shaky" along with "Mok'thardin's Enchantment": kill/loot the Elder Mistvale Gorillas.  Very low drop rate for the Aged Gorilla Sinew (but keep grinding until you get it).
03) Run back SW to BB and near the boat pickup turn in "Scaring Shaky" 27.74, accept "Return to MacKinley".
04) On the lower docks, turn in "The Bloodsail Buccaneers" 28.76, accept the next part.
05) Go in the cabin (next to the hanging shark) and turn in "Return to MacKinley" 28.77, SKIP "Voodoo Dues" (for now).
06) Go all the way upstairs in the Inn then go over past the Alliance FP to Tan-Your-Hide Leatherworks and turn in "Some Assembly Required" 28.78, accept "Excelsior".
07) Go back to the top of the Inn (on the boat-deck) and turn in "The Bloodsail Buccaneers" 27.77, SKIP the next part (for now).
08) Next to you on the roof, go to the Wind Rider Master 27.77 and fly to Grom'gol, Stranglethorn.
09) At Grom'gol, turn in "Mok'thardin's Enchantment" 32.29, accept the next part.
10) By the Bubbling Cauldron, accept "Split Bone Necklace" 32.28.
11) Go in the Inn and make Grom'gol your new home 31.30.  Make sure you are repaired/resupplied.
12) You should be a little over half way to level 40.  Now I grind the rest of the way to 40 on Jungle Thunderers around 42.27 or the Venture Co. Geologists around 45.21.  These mobs have less armor and die faster.  Instead of the grinding, you could get a 5 man group to do the Scarlet Monastery dungeon.
13) Once you are level 40, hearth to Grom'gol.
        ]],
        image = "imagen_031.jpeg",
