    [89] = {
        step = 89,
        title = [[Guía de Leveo - Sección #32]],
        text = [[
01) At the top of Grom'gol's Inn, get on the zeppelin to go to the UC 32.29.
02) At UC's Bank 66.44, Mailbox 68.38 or AH get the following items out:  Fizzle Brassbolts' Letter, (if you can) stack of 9 Blue Pearls, (if you have them) Frost Oil, Gyrochronatom, stack of Elixir of Water Breathing + Swim Speed Potions.  And if you have Healing Potion, Lesser Invisibility Potion and a Patterned Bronze Bracers get those out as well.  These items are used for easy turn-in quests in the Badlands.  And remember to not sell these items to a vendor.  Put in the bank:  any Split Bone Necklaces you may have.
03) EPIC MOUNT:  At level 40 epic ground mounts become available, and only cost about 12 gold.  For more info go here.
04) Go to the Bat Handler (63.49 in the UC) and fly to Hammerfall, Arathi.
