    [94] = {
        step = 94,
        title = [[42 Swamp of Sorrows]],
        text = [[
01) As you enter Swamp of Sorrows (SoS) start working on "Dream Dust in the Swamp": kill/loot the dragon whelps around the lake (SW around 13.60 in SoS) for the dream dust.  Just clear the whelps in this area once.  When you run out of whelps to kill, move on to the next steps:
02) N/A
03) Go east and then find and kill/loot Noboru the Cudgel /target.  See patrol path on map (spawns at 47.39).  He drops an item which starts "Noboru the Cudgel", accept it.
04) Go NW to The Harborage and turn in "Noboru the Cudgel" 26.31.  Accept "Draenethyst Crystals" (no exclamation mark).
05) Go SE to Stonard and in the Inn make it your new home from the Innkeeper 45.57.  Make sure you are repaired/resupplied.  NOTE: You can purchase potions from the vendor upstairs in the Inn.
06) Next to you in the Inn, accept "Lack of Surplus" 45.57.
07) Go in the building and accept "Little Morsels" 48.55.  Go upstairs and turn in "Report to Helgrum".  Next to you, accept "Pool of Tears".
08) Potions, 8a) NOTE:  There is another potion vendor 46.53 here you can check for Healing/Mana potions.
09) Do "Pool of Tears": loot the Atal'ai Artifacts under the lake around the Temple of Atal Hakkar around 65.54.  Use water breathing potions (if you're not undead) and any Swim Speed Potions if you have any.  ALSO:  Continue working on (if you still need to) "Dream Dust in the Swamp" by kill/looting any dragons you see around the lake.
10) Do "Lack of Surplus": kill/loot crocolisks.  There are Sawtooth Crocolisks (around the middle of SoS around 57.53) and Sawtooth Snappers (around the NE of SoS around 80.28).
11) Go SE to Misty Reed Post and turn in "Lack of Surplus" 81.81, SKIP the next part.
        ]],
        image = "",
