    [95] = {
        step = 95,
        title = [[Contested - Stranglethorn Vale]],
        text = [[
01) Go north to the Fallow Sanctuary and from the human /target in the cage 65.18, accept and try to do the escort "Galen's Escape" (it's wise to clear the mobs around the cage first).  While doing the escort also do "Draenethyst Crystals": loot the Draenethyst Crystals around the village.  And do "Little Morsels": use the Fel-Tainted Morsels quest item on the 3 captured animals to feed them, listed below:
02) Feed Captured Jaguar 65.23.
03) Feed Captured Tarantula 63.24.
04) Feed Captured crocolisk 60.22.
05) Make sure "Dream Dust in the Swamp" is finished now by kill/looting the dragons around the Pools of Tears lake around 63.39.
06) Above Stonard, at Galen's Strongbox (next to a tent 48.40), turn in (if you were able to do it) "Galen's Escape".
07) Go west to The Harborage and turn in "Draenethyst Crystals" 26.31.
08) Hearth (or go SE) to Stonard and in the building turn in "Little Morsels" 48.55.  Then go up in the building and turn in "Pool of Tears", accept "The Atal'ai Exile".  Make sure you are repaired/resupplied.
09) Go to the Wind Rider Master 46.55 and fly to Booty Bay, Stranglethorn...
        ]],
        image = "",
