    [96] = {
        step = 96,
        title = [[43 Stranglethorn Vale]],
        text = [[
01) Once you land, next to you from Fleet Master Seahorn, accept "The Bloodsail Buccaneers" 27.77.
02) Next to you at the top of the Inn, accept "Skullsplitter Tusks" 27.77.
03) Next to you, turn in "Dream Dust in the Swamp" 27.77, SKIP "Rumors for Kravel" (for now).
04) Next to you from the dwarf 27.77, accept "Up to Snuff".
05) Drop down in the Inn and make BB your new home 27.77.  Make sure you are repaired/resupplied.  You will not come back to town for awhile, so make sure you are well stocked.
06) Next to you 27.77, accept "Venture Company Mining" and "Zanzil's Secret".
07) Go next to the bank and accept "Akiris by the Bundle" 27.76.
08) At the Bank 27.77 next to you put the following item into it:  Bundle of Atal'ai Artifacts.  Get out of the bank:  any Split Bone Necklaces you may have.
09) In the cabin (next to the hanging shark), accept "Voodoo Dues" 28.77.
10) Go north up the docks and from Dizzy One-Eye, accept "Keep An Eye Out" 29.76.
11) Just east of BB along the shore, do "The Bloodsail Buccaneers" along with "Up to Snuff" and "Keep An Eye Out": kill/loot the Bloodsail mobs for the Snuff along with Dizzy's Eye.  They can drop from any Bloodsail mob (low drop rates).  Also, kill 10 Bloodsail Swashbucklers.  And loot the Bloodsail Orders on the small boat 28.83 or it could be on the table 27.83 at the camp at the end of the beach (or other spots around the camps).  And next to you, loot the Bloodsail Charts 27.83 on top of the box next to the eastern most tent (See Image for Possible Locations).  It could also be at other spots at the various camps along the beach.
12) Go west (follow path on map) and do "Mok'thardin's Enchantment" along with "Akiris by the Bundle": kill/loot the Naga Explorers and then work your way up to the top and loot The Holy Spring water fountain over the bridge 29.62.
        ]],
        image = "",
    },
    [97] = {
        step = 97,
        title = [[Contested - Stranglethorn Vale]],
        text = [[
01) N/A
02) Go east across the path to the Ruins of Jubuwal and do "Zanzil's Secret" along with "Voodoo Dues": kill/loot the Zanzil mobs for Zanzil's Mixture and kill/loot the 3 named mobs.  Kill/loot  Maury "Club Foot" Wilkins /target 35.51.  Mobs are tightly packed so be careful.  See next step for the other 2 mobs to kill/loot...
03) Kill/loot Jon-Jon the Crow /target 35.52 by the Bonfire.
04) Kill/loot Chucky "Ten Thumbs" /target at the Ruins of Aboraz east path entrance 34.54 (mob is at 40.58, see map on how to get there).  Watch out there is numerous stealthed panthers on the pathway there.
05) Go back west to the main path, then north a bit to the ledges around 41.44 and do "Venture Company Mining": kill/loot the Venture Co. goblins.
06) Go north to the troll Ruins around 42.36 and do "Skullsplitter Tusks" along with "Split Bone Necklace": kill/loot the Skullsplitter trolls.  There is more mobs just SE at the other Ruins around 47.40 and NE around 46.33.
07) N/A
08) N/A
09) Go to Grom'gol (by the Cauldron) and turn in "Split Bone Necklace" 32.28.  And click the Bubbling Cauldron to accept "Marg Speaks".
10) Turn in "Mok'thardin's Enchantment" 32.29.  Make sure you are repaired/resupplied.
11) Now could be a good time to see if you have all the pages for "The Green Hills of Stranglethorn".  This quest requires that you have the following pages: 1, 4, 6, 8, 10, 11, 14, 16, 18, 20, 21, 24, 25, 26, and 27.  You can also find these pages in the AH or from other players.  If you have all of them, get them out now (we will turn it in a few steps later).  If not, you will return to STV one more time in the future for one last chance to find the pages.
12) West at the shore do "Excelsior": kill/loot an Elder Saltwater Crocolisks /target (lvl 38).  There are 4 possible spawn locations try this one first 33.33, see map.  You should only need to kill/loot one of them.  Also these spawn by killing the regular Saltwater Crocolisks, so you may need to kill some of them first to get these to spawn in.
