    [98] = {
        step = 98,
        title = [[Horde - The Barrens]],
        text = [[
01) N/A
02) At Nesingwary's Expedition, turn in (if you have all the Green Hills pages) "The Green Hills of Stranglethorn" 36.11.
03) Hearth to BB.
04) Next to you in the Inn 27.77, turn in "Venture Company Mining" and "Zanzil's Secret".
05) Go up in the Inn and turn in "Skullsplitter Tusks" and "Up to Snuff".  Also accept "Rumors for Kravel" and "Tran'rek".
06) Next to you up the steps on the boat-deck, turn in "The Bloodsail Buccaneers" 27.77, SKIP the next part (for now).
