    [99] = {
        step = 99,
        title = [[44 Dustwallow Marsh]],
        text = [[
01) You can get repaired/resupplied from Zulrg (ogre) 36.32.
02) By the Bonfire accept "Overlord Mok'Morokk's Concern" 36.31.
03) At Krog, turn in "Return to Krog" 36.32, accept "More than Coincidence" and "The Grimtotem Plot".
04) At the Innkeeper, make Brackenwall Village your new home.
