07) Go north to Blackhoof Village around 42.13 and do "The Grimtotem Plot" along with "More than Coincidence": kill/loot Grimtotem (taurens) to obtain 4 Grimtotem Notes, then click on them in your backpack.  Also loot 7 Blackhoof Armaments (spear racks) around the village.
08) Hearth (or go back), and at Krog 36.32, turn in "More than Coincidence" and "The Grimtotem Plot".  Accept "Seek Out Tabetha".
09) At the Wind Rider Master /target 36.32 fly to Mudsprocket, Dustwallow Marsh.
10) At Mudsprocket, by the green containers accept "Catch a Dragon by the Tail" 42.73.
11) Next to you from the Wanted Poster accept "WANTED: Goreclaw the Ravenous" 42.73.
12) In the Inn accept "Bloodfen Feathers" 42.74.
13) In the Inn, talk to the Innkeeper (goblin) to make Mudsprocket your new home.  He is most likely up the steps 42.74.
14) Go NW to Bloodfen Burrow around 34.65 and do "Bloodfen Feathers" along with "WANTED: Goreclaw the Ravenous": kill/loot the Bloodfen raptors.  And kill Goreclaw the Ravenous (bigger raptor /target).
15) Hearth (or go back) to Mudsprocket and in the small hut turn in "WANTED: Goreclaw the Ravenous" 42.73.
16) In the Inn turn in "Bloodfen Feathers" 42.74.  Accept "Banner of the Stonemaul" and "The Essence of Enmity".
        ]],
        image = "",
    },
    [100] = {
        step = 100,
        title = [[Guía de Leveo - Sección #11]],
        text = [[
01) As you do this section start working on the following:  "Army of the Black Dragon" (kill required amount of Firemane dragons), "The Essence of Enmity" (use the Brogg's Totem quest item on Firemane dragon corpses), "Catch a Dragon by the Tail" (loot Wyrmtail plants) and "Identifying the Brood" (kill/loot any dragon whelps):
02) Work your way NE to Tabetha's Farm and in the hut turn in "Seek Out Tabetha" 46.57, accept "Raze Direhorn Post!".
03) Go NW to Direhorn Post and do "Raze Direhorn Post!": use Tabetha's Torch quest item on the following 3 tents:
04) Burn the East Tent 48.48.
05) Burn the Northeast Tent 47.47.  Also at this tent kill/loot Apothecary Cylla , she drops an item which starts "The Apothecary's Letter", accept it.
06) Burn the North Tent 47.46.
07) Back inside the cabin 46.57 (#2 on map) turn in "Raze Direhorn Post!", accept "Justice Dispensed".
08) Go east to the shore/water around 56.61 and do "Marg Speaks": kill/loot the Muckshell mobs until the Jeweled Pendant drops (very low drop rate).
09) Exit the shore (at 53.64).
10) Go west to Stonemaul Ruins and do "Overlord Mok'Morokk's Concern": pick up the 3 quest objects.  First one is Mok'Morokk's Snuff (middle of the fenced area 45.66).  See next steps for other two:
11) Go west and loot Mok'Morokk's Grog (before the cave entrance 39.66).  Then kill the dragon that spawns.
12) Go in the cave next to you and at the end of it loot Mok'Morokk's Strongbox 37.70.
13) Also in the same cave do "Banner of the Stonemaul": loot the Stonemaul Clan Banner 38.69.
14) Before leaving the cave (exit at 39.66) make sure you finish killing the 5 Firemane Scalebanes /target needed for "Army of the Black Dragon" (as they are generally only found here).
15) Finish "The Essence of Enmity": use the Brogg's Totem quest item on Firemane dragon corpses.
        ]],
        image = "imagen_011.jpeg",
    },
    [101] = {
        step = 101,
        title = [[Guía de Leveo - Sección #12]],
        text = [[
01) Go back SE to Mudsprocket and in the Inn 42.74 turn in "Banner of the Stonemaul" and "The Essence of Enmity".  Accept "Spirits of Stonemaul Hold".
02) NE at Stonemaul Ruins around 45.66 do "Spirits of Stonemaul Hold": click on the Ogre Remains (skeletons on the ground), then kill the ogre spirits that spawn.
03) Around Stonemaul Ruins finish "Army of the Black Dragon": kill required amount of Firemane dragons.
04) Back in the Inn at Mudsprocket turn in "Spirits of Stonemaul Hold" 42.74  (#1 on map), accept "Challenge to the Black Flight".
05) Continue working on "Catch a Dragon by the Tail" by looting any Wyrmtail (plants) you see along the way:
06) Go SE to the entrance of Onyxia's Lair 53.77 and do "Challenge to the Black Flight": use the Stonemaul Banner quest item at the entrance.
07) Work your way back NW to Mudsprocket while finishing "Catch a Dragon by the Tail" and "Identifying the Brood": loot 8 Wyrmtail (plants).  And kill/loot any dragon whelps.  These are found all around Wyrmbog (#5 on map).
08) Back at Mudsprocket by the green containers turn in "Catch a Dragon by the Tail" 42.73 (#1 on map).
09) In the Inn turn in "Challenge to the Black Flight" 42.74.
10) At the NE outskirts of town, go to the Flight Master 43.72 and fly to Brackenwall Village, Dustwallow Marsh.
11) At the west side of Brackenwall Village, turn in "Marg Speaks" 35.31, accept "Report to Zor".
12) By the Bonfire, turn in "Overlord Mok'Morokk's Concern" 36.31.
13) At the east entrance of Brackenwall Village turn in "Army of the Black Dragon" 37.31.
14) In the small cave, turn in "Identifying the Brood" 37.33.  Wait a few seconds then accept "The Brood of Onyxia".
15) At Krog, turn in "Justice Dispensed" 36.32.
16) Next to the Bonfire, turn in "The Brood of Onyxia" 36.31, accept the next part.
17) Back in the small cave turn in "The Brood of Onyxia" 37.33, SKIP the next part (for now).
18) Make sure you are repaired/resupplied.  If for some reason you turned level 45, remember to get the lvl 45 food/drink 37.32.
19) Go to the Wind Rider Master /target 36.32 and fly to Gadgetzan, Tanaris.
        ]],
        image = "imagen_012.jpeg",
    },
    [102] = {
        step = 102,
        title = [[PLEASE READ With all the faster leveling changes, by the time you get to this section you will most likely be well into level 44. Because of this when following my guide, you should skip this entire section and go right into 44-45 Tanaris section below.  I will leave this section for reference purposes only.  However if for some reason you are in level 43 you can consider doing this section.]],
        text = [[
01) 44 Desolace
02) At Shadowprey Village, on top of the mound next to the gong 26.68, accept (if it's available) "Portals of the Legion" (no exclamation mark).  Make sure you are repaired/resupplied.
03) N/A
04) N/A
05) Go NE to the Kodo Graveyard and accept "Ghost-o-Plasm Round Up" (48.62).
06) Go east to Ghost Walker Post (entrance is 56.57)...
07) Make a left at the entrance, then go across the bridge and accept "The Corrupter" 53.54.
08) N/A
09) Go SW to the Valley of Bones around 64.91 and do "Ghost-o-Plasm Round Up": at the big skeleton bones sticking out of the ground, first clear out the skeletons, then use the Crate of Ghost Magnets quest item there, then kill/loot the Magrami Spectre that spawn in for the plasms.
10) Go NW to the Mannoroc Coven and do "The Corrupter" (Elite): kill Lord Azrethoc /target (lvl 40 elite doomguard that patrols around) and also kill Jugkar Grim'rod /target (lvl 40 orc warlock, at 56.78).
11) At the Mannoroc Coven do (if you have it) "Portals of the Legion": click on the Demon Portals, then kill the Demon Portal Guardians that spawn to banish the portals.  Portal locations are:  55.79 54.79 53.80 53.82 53.84 51.81 50.77 50.74 51.71 55.72
12) Go to Ghost Walker Post (entrance is 56.58, #5 on map)...
13) Make a left at the entrance, then go across the bridge and turn in "The Corrupter" (53.54, #6 on map).
14) Go to the Kodo Graveyard and turn in "Ghost-o-Plasm Round Up" (48.62, #4 on map).
15) Go back to Shadowprey Village and on top of the mound next to the gong (26.68, #1 on map), turn in (if you have it) "Portals of the Legion". Make sure you are repaired/resupplied.
16) Hearth to Thunder Bluff.
17) Go to the Wind Rider Master at the top of the tower in the middle of TB 47.50 and fly to Gadgetzan, Tanaris.
        ]],
        image = "imagen_013.jpeg",
    },
    [103] = {
        step = 103,
        title = [[45 Tanaris]],
        text = [[
01) As you enter Gadgetzan (next to the crane 52.27) turn in "Tran'Rek", SKIP "Scarab Shells" (Dungeon).
02) From the Wanted Poster next to the cage entrance 52.27, accept "WANTED: Caliph Scorpidsting" and "WANTED: Andre Firebeard".
03) Go in the Inn on the east side and make Gadgetzan your new home from the Innkeeper 53.28.
04) Next to the Inn at the windmill (just south 52.28), accept "Water Pouch Bounty" and "Wastewander Justice".
05) At the Bank next to you 52.29, get the following items out:  Goblin Rumors and Seaforium Booster.  Put in the bank:  Jeweled Pendant.
06) At the western side of Gadgetzan on top of the hill, accept "Gadgetzan Water Survey" 50.27.
07) Go north to the Shimmering Flats at the Mirage Raceway and from the dwarf turn in "Rumors for Kravel" (78.77 in Thousand Needles).  Wait a few seconds, then accept "Back to Booty Bay".
08) Next to you from the gnome, turn in "News for Fizzle" 78.77.
09) Go over to the goblin's side of the Mirage Raceway and turn in "Razzeric's Tweaking" 80.76, accept "Safety First".  Next to you, accept "Keeping Pace".
10) At the goblin Zamek 80.77 /target next to the Goblin Racer, click on Complete Quest to setup a distraction, then go in the gnome's hut and click on Rizzle's Unguarded Plans 77.77 to turn in "Keeping Pace", accept "Rizzle's Schematics".
11) Go to the goblin Pozzik and turn in "Rizzle's Schematics" 80.76.
12) Hearth (or go back) to Gadgetzan.  NOTE:  You can now destroy the Sample of Indurium Ore as it is no longer used for anything.
13) From Shreev at the western side of Gadgetzan, turn in "Safety First" 51.27, SKIP the next part.
        ]],
        image = "imagen_015.jpeg",
    },
    [104] = {
        step = 104,
        title = [[Guía de Leveo - Sección #16]],
        text = [[
01) Grind your way east to the Noonshade Ruins around 60.24 and start working on "Wastewander Justice" along with "Water Pouch Bounty": kill/loot the Wastewander humans.  NOTES:  Do not sell the Wastewander Water Pouches to a vendor!  Just clear the area once and continue on...
02) Go east to Steamwheedle Port and from the female goblin under the red tent, accept "Pirate Hats Ahoy!" 67.22.
03) From the male troll under the green tent, accept "Screecher Spirits" 67.22.
04) At the other side of the Port, in the hut 67.24, turn in "Stoley's Debt", accept "Stoley's Shipment".  And next to you, accept "Southsea Shakedown".
05) Go SW to the Waterspring Field around 64.30 and finish "Wastewander Justice" along with "Water Pouch Bounty": kill/loot the needed Wastewander mobs.  Also, keep an eye out for Caliph Scorpidsting /target, he patrols around the area and has 2 rogues following him.  This is for "WANTED: Caliph Scorpidsting", and you will have another opportunity later to do this if you cannot find him now.
06) Go to Lost Rigger Cove (entrance at 69.42)...
07) Start working on "Southsea Shakedown" along with "Pirate Hats Ahoy!": kill/loot the Southsea pirates (the Southsea Dock Workers are up at wood platforms 75.47).  Any of these mobs has a chance to drop a Pirate's footlocker, which could contain an item which starts "Ship Schedules", accept it if you are able to find it, otherwise it can be skipped.  While doing this, also go do the following 2 steps below in this same area:
08) "Stoley's Shipment": loot the Stolen Cargo up in the building 72.47.
09) "WANTED: Andre Firebeard": kill/loot Andre Firebeard /target in the middle of the cove 73.47.  Watch out this fight usually involves 3 adds.  (See Video).
10) Once all these are done (including "Southsea Shakedown" along with "Pirate Hats Ahoy!"), then hearth to Gadgetzan.  Make sure you are repaired/resupplied.
        ]],
        image = "imagen_016.jpeg",
    },
    [105] = {
        step = 105,
        title = [[Guía de Leveo - Sección #17]],
        text = [[
01) Next to the Inn at the windmill 52.28, turn in "Water Pouch Bounty" and "Wastewander Justice", accept "More Wastewander Justice".
02) Go west to Sandsorrow Watch and do "Gadgetzan Water Survey": use the Untapped Dowsing Widget quest item in the pool 39.29.  Watch out, as soon as you fill the widget, a few high level bugs will spawn.  Either run away or try to kill them.
03) Hearth (or go back east) to Gadgetzan and on top of the hill, turn in "Gadgetzan Water Survey" 50.27, SKIP "Noxious Lair Investigation" (for now).
04) Grind east to Steamwheedle Port and from the female goblin under the red tent, turn in "Pirate Hats Ahoy!" 67.22.  Then you can get resupplied in the hut next to you.
05) At the other side of the Port, in the hut 67.24, turn in "Stoley's Shipment", accept "Deliver to MacKinley".  Next to you, turn in "WANTED: Andre Firebeard", "Southsea Shakedown" and (if you have it) "Ship Schedules".
06) Go SW to the Waterspring Field around 60.37 and do "More Wastewander Justice" along with (if you still need to) "WANTED: Caliph Scorpidsting": kill the needed Wastewander humans and kill/loot Caliph Scorpidsting /target, he patrols around the area and has 2 rogues following him.  He usually spawns at 59.40.
07) Hearth (or run back) to Gadgetzan and at the windmill next to the Inn (52.29, #1 on map), turn in "More Wastewander Justice" and "WANTED: Caliph Scorpidsting".
08) Go into the Bank next to you 52.29 and put into it:  Kravel's Scheme, Stoley's Bottle, any Wastewander Water Pouches and if you have found the item called OOX-17/TN Distress Beacon, put that in your bank as well (and don't accept the quest from it yet).
09) Go to the Wind Rider Master (north of Gadgetzan, 52.25) and fly to Freewind Post, Thousand Needles.
10) Go west into Feralas entrance 7.10...
        ]],
        image = "imagen_017.jpeg",
    },
    [106] = {
        step = 106,
        title = [[46 Feralas]],
        text = [[
01) Run into Camp Mojache, make a right, then accept "A New Cloak's Sheen" 76.43.
02) Continue into the town and from Rok Orhan /target (she patrols back and forth in the town), accept "The Ogres of Feralas".
03) WOTLK, 2b) In the hut 76.44, accept "Dark Heart" and "Vengeance on the Northspring".
04) From the goblin on the small mound, accept "Gordunni Cobalt" 76.44.
05) Flight Path, 3b) Get the FP next to you 75.44.
06) Between the tents, accept "War on the Woodpaw" 75.42.
07) In the big tent accept "The Mark of Quality" 74.43.
08) Just outside of the big tent on your right (from Witch Doctor Uzer'i) accept "A Strange Request" 74.43 and "The Sunken Temple".
09) Go in the Inn and make Camp Mojache your new home 75.45.  Make sure you are repaired/resupplied.  If you turned level 45, remember to get the lvl 45 food/drink.
10) Go just north of Camp Mojache around 73.39 and do "War on the Woodpaw": kill/loot the Woodpaw gnolls.
11) WOTLK, 8b) Go just across the river over to Lariss Pavilion and turn in "A Strange Request" 77.38, accept "Retrun to Witch Doctor Uzer'i".
12) Go NE to the Gordunni Outpost entrance 75.35 and do "The Ogres of Feralas" along with "Gordunni Cobalt": kill the needed Gordunni ogres and use Orwin's Shovel quest item on the bluish haze from the ground, then click on the Gordunni Dirt Mounds for the Gordunni Cobalt.  And loot one of the Gordunni Scrolls laying on the ground around the Outpost (there could be one next to the tree log 75.30), then accept "The Gordunni Scroll" from it.
13) WOTLK, 9b) Hearth (or go back) to Camp Mojache and next to the big tent from Witch Doctor Uzer'i 74.43, turn in "Retrun to Witch Doctor Uzer'i".  Wait a few seconds then accept "Testing the Vessel" and "Natural Materials".  NOTE:  We will turn the rest of the quests in a few steps later.
14) Just north around Camp Mojache around 72.43, do "Testing the Vessel": use the Beast Muisek Vessel quest item on the corpses of Ironfur Bears or Longtooth Runners (wolves).
        ]],
        image = "imagen_018.jpeg",
    },
    [107] = {
        step = 107,
        title = [[WOTLK, 00) Hearth (or go back) to Camp Mojache and next to the big tent from Witch Doctor Uzer'i 74.43, turn in "Testing the Vessel", accept "Hippogryph Muisek".]],
        text = [[
01) Between the two tents, turn in "War on the Woodpaw" 75.42, accept "Alpha Strike".
02) From the goblin on the small mound, turn in "Gordunni Cobalt" 76.44.
03) From Rok Orhan /target (she patrols back and forth in the town), turn in "The Ogres of Feralas" (accept the next part) and "The Gordunni Scroll", accept "Dark Ceremony".
04) NOTE: You can check the Alchemy Supplies vendor for potions and sell junk 76.43.
05) Go south to Woodpaw Hills and do "Alpha Strike": kill 5 Woodpaw Alphas /target.  There is generally one Alpha at each of the bigger camps in the area, which include: 75.56 71.56 72.57 73.56 69.56 69.54 77.57.
06) Hearth (or go back) to Camp Mojache and between the two tents, turn in "Alpha Strike" (75.42, #1 on map), accept "Woodpaw Investigation".
07) Go back to Woodpaw Hills and from the Woodpaw Battle Map scroll on the crate 72.56 turn in "Woodpaw Investigation", accept "The Battle Plans".
08) Hearth (or go back) Camp Mojache.
09) Between the two tents, turn in "The Battle Plans" (75.42, #1 on map).  Accept "Zukk'ash Infestation" and "Stinglasher".
        ]],
        image = "imagen_019.jpeg",
    },
    [108] = {
        step = 108,
        title = [[Orc/Troll - Durotar]],
        text = [[
01) Go south to The Writhing Deep and do "Stinglasher" along with "Zukk'ash Infestation": kill/loot the Zukk'ash bugs and also kill/loot Stinglasher /target.  He is at the cave entrance of either 77.61 or 74.64.
02) Go NW and do "Screecher Spirits": kill the Screecher mobs, then use the Yeh'kinya's Bramble quest item on the corpse, then talk to the Screecher Spirit that spawns.  There are some Screechers around 59.51 and see map for more locations.  NOTES:  The Screechers have a spell silence attack.  Do the next step in that same area while doing this:
03) Go north to the entrance of Dire Maul at 43.70 only to get it Discovered.  Simply discovering Dire Maul in this area will allow you to accept a future quest.  You need to actually discover the zone, you will know when you achieved that when your general chat switches over to Dire Maul.
04) Go to the Ruins of Isildien (starting at 61.56 and work your way south) and do "The Ogres of Feralas": kill the required amount of Gordunni ogres.  The Maulers are north and the Shamans are south.  Keep the next step in mind:
05) Do "Dark Ceremony": kill/loot the Gordunni Mage-Lords until you get the Gordunni Orb.  These mobs are south in the Ruins of Isildien 61.95.
06) WOTLK, 5a) Go just west to The High Wilderness around 55.66 and do "Hippogryph Muisek": use the Hippogryph Muisek Vessel quest item on any Frayfeather hippogryph corpses.  Also do part of "Natural Materials": kill/loot the Frayfeather mobs (hippogryphs) for the 20 Resilient Sinew and 40 Metallic Fragments.  Keep next step in mind:
07) WOTLK, 5b) South of the Hippogryphs along the cliffs around 58.76, loot a Hippogryph Egg in one of the nests.  This will be turned in at Tanaris for a later quest.  And remember to not sell this!
08) Go NW to the Feral Scar Vale around 55.56 and do "The Mark of Quality": kill/loot the Feral Scar yetis.  NOTE:  While questing in Feralas, you may come across an item called OOX-22/FE Distress Beacon, from it accept "Find OOX-22/FE!" and turn this in through the small cave at Feral Scar 53.56, but do NOT do the follow-up escort quest.  Also the yetis can be quite dangerous inside the cave so try to avoid that if you can.
09) WOTLK, 6b) Hearth (or go back) to Camp Mojache, then next to the big tent from Witch Doctor Uzer'i 74.43, turn in "Hippogryph Muisek", accept "Faerie Dragon Muisek".  REMINDER:  Do not sell your Hippogryph Egg.
10) In the big tent turn in "The Mark of Quality" 74.43.
11) Between the two tents, turn in "Zukk'ash Infestation" and "Stinglasher" 75.42.  Accept "Zukk'ash Report".
12) From Rok Orhan /target (she patrols back and forth in the town), turn in "Dark Ceremony" and "The Ogres of Feralas", accept "The Gordunni Orb".  Make sure you are repaired/resupplied.
13) WOTLK, 9a) Go SW around 69.48 and do "A New Cloak's Sheen" (kill/loot the Sprite Darters), and do "Faerie Dragon Muisek" (use the Faerie Dragon Muisek Vessel quest item on Sprite Darter corpses).  Also do part of "Natural Materials": kill/loot the Sprite Darters for the 6 Encrusted Minerals.
14) WOTLK, 9b) Hearth (or go back) to Camp Mojache, and at Witch Doctor Uzer'i 74.43 turn in "Faerie Dragon Muisek", accept "Treant Muisek".  Also turn in (if it's complete) "Natural Materials".
15) WOTLK, 9c) On the eastern side of Camp Mojache, turn in "A New Cloak's Sheen" 76.43, accept "A Grim Discovery".
16) WOTLK, 9d) Do "Treant Muisek" and finish (if you still need to) "Natural Materials": kill/loot  Wandering Forest Walkers /target for the 2 Splintered Logs and use the Treant Muisek Vessel quest item on Wandering Forest Walker /target corpses.  There is several around 72.43.
17) WOTLK, 9e) Go north and do "A Grim Discovery": kill/loot the Grimtotem taurens for the horns around 67.46.  There's another camp of mobs just north around 69.40.
18) WOTLK, 9f) Hearth (or go back) to Camp Mojache, and at Witch Doctor Uzer'i 74.43 turn in "Treant Muisek", accept "Mountain Giant Muisek".  And turn in (if you haven't yet) "Natural Materials".
19) WOTLK, 9g) On the eastern side of Camp Mojache, turn in "A Grim Discovery" 76.43, accept the next part.  Make sure you are repaired/resupplied.
20) WOTLK, 9h) Head west on the main path all the way to the goblin 45.43 and accept "Zapped Giants".
21) WOTLK, 9i) Go north (exit at 47.38) to Ruins of Ravenwind around 40.13 and do "Vengeance on the Northspring": kill the needed Northspring harpies.  Also, keep grinding on harpies until the Horn of Hatetalon drops, then use this item for the next quest:
22) WOTLK, 9j) Up north in Ruins of Ravenwind do "Dark Heart": use the Horn of Hatetalon quest item at the two big stones 41.9 to summon Edana Hatetalon (lvl 50), then kill/loot her..
23) WOTLK, 9k) Go just SW to The Twin Colossals around 39.24 and do "Mountain Giant Muisek" along with "Zapped Giants": use Zorbin's Ultra-Shrinker quest item on any giant (this removes the elite status), then use the Mountain Giant Muisek Vessel quest item on the corpses.
24) WOTLK, 9l) Go south to the goblin next to the dock and turn in "Zapped Giants" 45.43 (#9h on map).
25) WOTLK, 9m) Hearth (or go back) to Camp Mojache.
26) WOTLK, 9n) From Witch Doctor Uzer'i 74.43, turn in "Mountain Giant Muisek".  Accept "Weapons of Spirit".  Then instead of waiting for the doc, just do the next step:
27) WOTLK, 9o) At the other side of Camp Mojache under the hut 76.44, turn in "Dark Heart" and "Vengeance on the Northspring".
28) WOTLK, 9p) Go back to Witch Doctor Uzer'i 74.43 and turn in "Weapons of Spirit".
29) Go to the Wind Rider Master 75.44 and fly to Orgrimmar, Durotar.
        ]],
        image = "imagen_020.jpeg",
    },
    [109] = {
        step = 109,
        title = [[Orgrimmar]],
        text = [[
01) Go to the Bank 50.69 and put in the bank:  Hippogryph Egg, Yeh'kinya's Bramble.  And get the following items out of the bank:  Jeweled Pendant.  Also (depending on what cloth donations you already turned in at Orgrimmar) get your Silk Cloth and Mageweave Cloth out of your bank or mailbox 51.70.  You would need 60 or 120 Silk Cloth and 60 or 120 Mageweave Cloth.  This is for Cloth Donation quests you are about to turn in.
02) Go to The Drag and up in the hut, turn in "Zukk'ash Report" 56.47.
03) Drop down to Magar's Cloth Goods and turn in the cloth donations to the Orc's Horde Cloth Quartermaster 64.51.  Also, if you only have 60 Silk Cloth, save that for the other Silk Cloth turn in later instead!
04) Go in Droffers And Sons Salvage and accept "Ripple Recovery" 60.37.  Next to you, turn that in and accept the next part.
05) Go east to the Valley of Honor at Belgrom Rockmaul 75.34 and turn in "Parts of the Swarm" and "A Grim Discovery".  Accept "Betrayed".
06) GET NEW ABILITIES, 5b) If you need to, get new spells/abilities.
07) Go to Grommash Hold in The Valley of Wisdom and turn in "Report to Zor" 39.38.  Accept/Complete "Service to the Horde"
08) Go to Darkbriar Lodge in the Valley of Spirits and turn in "The Gordunni Orb" 39.86.
09) Next to you, turn in as much cloth as you can to the Horde Cloth Quartermaster 38.88 (for the troll faction).
10) Get on the zeppelin (51.14 in Durotar) to go to The Undercity.
        ]],
        image = "imagen_021.jpeg",
    },
    [110] = {
        step = 110,
        title = [[The Undercity]],
        text = [[
01) Go to the Bank in the middle of The Undercity 66.44 and put the following items into the bank:  Sealed Letter to Ag'tor.  Get out (if you can) 60 Wool Cloth, then 60 Silk Cloth, and then 60 Mageweave Cloth (for cloth donation quests).
02) N/A
03) Next to you, turn in any cloth you have to the Undead's Horde Cloth Quartermaster 72.29.
04) Go west to The War Quarter to the Weapon Master 57.33 and if you have extra gold to spare, feel free to learn all the weapons from him.
05) Go SW to The Apothecarium entrance 52.80 and accept "Seeping Corruption" 49.71.
06) Next to you in the same room, accept "Errand for Apothecary Zinge" 50.68.
07) Out in the other room, turn in "Errand for Apothecary Zinge" 59.55, accept the next part.
08) Go back down in the Apothecarium Quarter entrance 52.80 and turn in "Errand for Apothecary Zinge" (50.68, #5 on map), accept "Into the Field".
09) 08b) Check the AH 71.47 for a Mithril Casing and if you are able to get it, store it in your bank for now for a later quest at Un'goro Crater.  If you can't get it now, you will be reminded twice more later to see if you can get this.
10) Go to the Bank in the middle of The Undercity (66.44, #1 on map) and put the following items into it:  Kravel's Scheme, Stoley's Bottle, Field Testing Kit and Box of Empty Vials.  Get the following items out:  (if you have one) Swim Speed Potion.
11) Leave the UC and get on the zeppelin to go to Grom'gol, STV (62.59 in Tirisfal Glades).
        ]],
        image = "imagen_022.jpeg",
    },
    [111] = {
        step = 111,
        title = [[PLEASE READ With all the faster leveling changes, by the time you get to this section you should already be either well into level 47 or level 48. Because of this when following my guide, you should skip this entire section and go right into 47-47 Stranglethorn Vale section below.  I will leave this section for reference purposes only.  However if you are in your 46s you should consider doing this section.  If you are NOT doing this section then abandon "Testing the Vessel", "Lines of Communication".]],
        text = [[
01) 47 Hinterlands
02) Here are the prerequisites to this section:
03) -Accept: "Lines of Communication" in the UC (magic quarter)
04) -Accept: "Grim Message" at Grom'gol (in STV)
05) Go into the Hinterlands (entrance at 87.29 in Hillsbrad Foothills).  NOTE:  Grind on any Trained Razorbeaks or Wild Gryphons you see along the way as they drop Long Elegant Feathers, you need 10 of these for a later quest, and remember to not sell these to a vendor.
06) Go up to Shindigger's Camp and turn in "Ripple Recovery" 27.49, accept "A Sticky Situation".
07) Go all the way to Revantusk Village and from the Blacksmithing Supplies vendor, accept "Vilebranch Hooligans" 78.80.
08) Up in the hut (next to the wagon), from Mystic Yayo'jin, accept "Cannibalistic Cousins" 79.78.
09) At the other hut next to you, from Otho Moji'ko, accept "Message to the Wildhammer" 79.79.
10) Next to you from the Stable Master 79.80, accept "Stalking the Stalkers", "Hunt the Savages" and "Avenging the Fallen".
11) Make sure you are repaired/resupplied.  Before you go out and start questing make sure you stock up heavily on food/water/supplies because you won't be back to town for while.
12) Time to do the good ol' Hinterlands grind!  Do the following 12 steps below.  They don't need to be done in that specific order, but start doing the ones on top first.  Have fun!
        ]],
        image = "imagen_025.jpeg",
    },
    [112] = {
        step = 112,
        title = [[Guía de Leveo - Sección #26]],
        text = [[
01) At any time you find an item called OOX-09/HL Distress Beacon, from it accept "Find OOX-09/HL!".  If so, go turn this in in the middle of the lake on top of the hill 49.38, but do NOT do the escort yet!
02) "Stalking the Stalkers": kill Silvermane Stalkers (eastern side of Hinterlands ramp entrance 76.62) and Silvermane Howlers (middle of Hinterlands).
03) "Cannibalistic Cousins": kill Vilebranch Scalpers and Vilebranch Soothsayers (trolls).  There are several camps of these mobs (starting at 71.48), another one around 66.45, 53.39, and 48.67.
04) "Testing the Vessel": use the Wildkin Muisek Vessel quest item on the corpse of any Owlbeast scattered around The Hinterlands.  These include the following Owlbeasts:  Marauding, Primitive, Savage, and Vicious.  Focusing on the Savages /targetthe most (#4 on map), because of the next step:
05) "Hunt the Savages": kill Savage Owlbeasts.  There are only 11 mob spawns around the middle-eastern part of Hinterlands.  (this is also #4 on map)
06) "Vilebranch Hooligans": loot Slagtree's Lost Tools.  There are 5 possible spawn locations (73.53, 71.49, 66.45, 57.43, or 53.39).
07) "A Sticky Situation": loot the Horde Supply Crates in the cave at Skull Rock (entrance at 58.40).  Once this is completed, keep the first 2 steps in mind from the next section.
08) "Avenging the Fallen": kill/loot the Razorbeak Skylord /targetfor the Skylord Plume.  There are only two spawn locations.  One patrols around 54.50, and another one patrols around 68.53.
09) "Lines of Communication": at Quel'Danil Lodge, click on the following 3 scrolls on the ground:  The Highvale Records 32.47 in the building.  The Highvale Notes 30.49 outside by the well, barrel and lamppost.  The Highvale Report 29.46 under the gazebo.  While you are here, keep the next step in mind:
10) "Message to the Wildhammer": kill the required amount of Highvale elves around Quel'Danil Lodge.
11) "Rin'ji is Trapped!": in the building and from Rin'Ji in the cage (31.47, #10 on map), accept the escort from him and then escort him out of  Quel'Danil Lodge.  TIP:  Clear out the path in front of the lodge first.
12) "Grim Message": kill/loot the Witherbark trolls to obtain 20 Witherbark Skulls.  There is one village 32.58 and another one 23.58.  Then use Nimboya's Pike quest item at the Hiri'watha village (32.58, #12 on map).  Use it twice:  first to combine the skulls, then to plant the pike in the ground.  Also while doing this quest, accept "Venom Bottles" from one of those little Venom Bottles on the table (at either village).
        ]],
        image = "imagen_026.jpeg",
    },
    [113] = {
        step = 113,
        title = [[Guía de Leveo - Sección #27]],
        text = [[
01) Go to the path (starting at 21.48)...
02) Go up the path to Shindigger's Camp and turn in "A Sticky Situation" 27.49.  Accept "Ripple Delivery".
03) Go east to the little island at the sea (use a Swim Speed Potion if you have one) and click on Rin'ji's Secret tablet 86.59 to turn in "Rin'ji is Trapped!", accept "Rin'ji's Secret".
04) Go to Revantusk Village and from the Blacksmithing Supplies vendor, turn in "Vilebranch Hooligans" 78.80.  NOTE:  Save 10 Long Elegant Feathers you have, as it is used for a later quest, and do not sell them to a vendor.
05) Up in the hut (next to the wagon), from Mystic Yayo'jin, turn in "Cannibalistic Cousins" 79.78.
06) At the other hut next to you, from Otho Moji'ko, turn in "Message to the Wildhammer" 79.79.  Only accept and turn in "Another Message to the Wildhammer" if you have 10 Long Elegant Feathers with you then SKIP "The Final Message to the Wildhammer" (for now).  If not, you will have another opportunity to turn this in later.
07) Next to you from the Stable Master 79.80, turn in "Stalking the Stalkers", "Hunt the Savages" and "Avenging the Fallen".
08) Go to the end of the docks and from the Wind Rider Master 82.82, fly to Hammerfall, Arathi.
09) Go to the Wind Rider Master 82.82 and fly to Tarren Mill, Hillsbrad.
10) Go in the small house 61.19 and turn in "Venom Bottles", accept "Undamaged Venom Sac".
        ]],
        image = "imagen_027.jpeg",
    },
    [114] = {
        step = 114,
        title = [[Undead - Tirisfal Glades]],
        text = [[
01) Go back into the Hinterlands (don't fly) (entrance at 87.29 in Hillsbrad)...
02) Go to Shadra'Alor entrance 36.64, go to the top of the temple (grind mobs along the way), then drop down and turn in "The Atal'ai Exile" 34.75 (See Video on where to find this dude at), accept "Return to Fel'Zerul"
03) In the immediate area, do "Undamaged Venom Sac": kill/loot Witherbark Broodguards (spiders) for the Undamaged Venom Sac (low drop rate).
04) REMINDER:  While questing, you may have found an item called OOX-09/HL Distress Beacon, from it accept "Find OOX-09/HL!".  If so, go turn this in in the middle of the lake on top of the hill 49.38, but do NOT do the escort yet!
05) Hearth to Tarren Mill.
06) In the small house next to the Inn, turn in "Undamaged Venom Sac" (61.19 in Hillsbrad).  NOTE:  Only accept "Consult Master Gadrin" if you still need to get a mount as a troll, as you turn it in in the same spot, otherwise skip it.
07) Go to the Bat Handler 60.19 and fly to Undercity, Tirisfal.
08) Go to the Bank 66.44 in the middle of the UC and get the following items out:  Kravel's Scheme and Stoley's Bottle.  And put in the Bank:  Dran's Ripple Delivery, 10 Wildkin Muisek, Wildkin Muisek Vessel and your stack of Long Elegant Feathers (if you still need to turn in the quest for them).
09) If you still need to, go to The Magic Quarter 72.29 and turn in "A Donation of Mageweave" (you need 60 Mageweave Cloth for this).
10) Next to you at the Magic Quarter 73.33, turn in "Rin'ji's Secret" and "Lines of Communication".  Then complete "Oran's Gratitude".
11) Check the AH 71.47 for a Mithril Casing and if you are able to get it, store it in your bank for now for a later quest at Un'goro Crater.  If you can't get it now, you will be reminded once more later to see if you can get this.
12) Leave the UC and get on the zeppelin to go to Grom'gol (62.59 in Tirisfal Glades).
        ]],
        image = "imagen_028.jpeg",
    },
    [115] = {
        step = 115,
        title = [[47 Stranglethorn Vale]],
        text = [[
01) N/A
02) N/A
03) Go to the Wind Rider Master 33.29 and fly to Booty Bay, Stranglethorn.
04) When you land, next to you from Fleet Master Seahorn accept "The Bloodsail Buccaneers" 27.77.
05) Drop down in the Inn and make BB your new home 27.77.
06) Next to you in the Inn, turn in "Back to Booty Bay" 27.77.
07) Go in the cabin (next to the hanging shark) and turn in "Deliver to MacKinley" 28.77.
08) N/A
09) Go near the end of the docks and accept "The Captain's Chest" 27.74.
10) Go east to the shore and attempt to do "The Captain's Chest" (Elite): kill/loot Gorlash /target.  This lvl 42 elite giant patrols up and down the shore around 37.70.   You may need to group up with someone, if you cannot do it, it can be skipped.
11) Search the shores east of BB for Half-Buried Bottles until a Carefully Folded Note shows up, from it accept "Message in a Bottle".
12) Go to the island east of BB (use Swim Speed if you can), plus watch out for the lvl 41 stealthed panthers there, then turn in "Message in a Bottle" 39.81, accept the next part.  NOTE:  If the Carefully Folded Note item remains in your inventory, you can destroy it.
13) East on the island do "Message in a Bottle": kill/loot King Mukla /target (lvl 42 big gorilla, at 41.84).
14) Back NW on the island turn in "Message in a Bottle" (#12 on map, 39.81).
        ]],
        image = "imagen_029.jpeg",
    },
    [116] = {
        step = 116,
        title = [[Contested - Stranglethorn Vale]],
        text = [[
01) Do "The Bloodsail Buccaneers": kill the 3 pirates in each of the 3 ships.  Also find a scroll laying on the ground (can be in any of the 3 ships) called Cortello's Riddle, and from it accept "Cortello's Riddle".  Sometimes this scroll can be in the basement of the ships, so search there too.  The first pirate to kill is Captain Stillwater down the first flight of stairs in the ship 33.88.  See next steps for the other 2:
02) Kill Fleet Master Firallon down the first flight of stairs in the middle ship 31.91.  Watch out for Ironpatch in the room before Firallon, take him on alone first.
03) Kill Captain Keelhaul down the first flight of stairs in the last ship 29.88.  Make sure you find the scroll that starts "Cortello's Riddle" before leaving this area.  NOTE:  After accepting "Cortello's Riddle" you can then destroy the scroll that started the quest as it will no longer be used for anything.
04) Hearth to BB, if Hearthstone is still on a cooldown, die on purpose and res at spirit.  Make sure you are repaired/resupplied.
05) Turn in (if you did it) "The Captain's Chest" (at the end of the docks 27.74).
06) Go to the Bank 27.77 and get out 15 Silk Cloth from the bank, mailbox or AH, for a later quest.
07) Up in the Inn, from Fleet Master Seahorn turn in "The Bloodsail Buccaneers" 27.77.
08) This is the last time my guide will tell you to turn in "The Green Hills of Stranglethorn" if it is complete.  This quest requires that you have the following pages: 1, 4, 6, 8, 10, 11, 14, 16, 18, 20, 21, 24, 25, 26, and 27.  You can also find these pages in the AH or from other players.  If you have all of them, get them out now and go to Nesingwary's Expedition 36.11 and turn this quest in.  If you do go turn it in, afterwards go to Grom'gol's Wind Rider Master 33.29 and fly to Kargath, Badlands.  Otherwise, skip to next step:
09) Next to you on the roof, go to the Wind Rider Master 27.77 and fly to Kargath, Badlands.
10) Go SW into Searing Gorge (entrance at 1.63 in Badlands).
        ]],
        image = "imagen_030.jpeg",
    },
    [117] = {
        step = 117,
        title = [[48 Searing Gorge]],
        text = [[
01) Go SE in Searing Gorge and from the Wooden Outhouse 66.62, accept "Caught!".
02) At the Grimesilt Dig Site next to you around 63.62, do "Caught!": kill 8 Dark Iron Geologists /target.  Also make sure you have 15 Silk Cloth (it can drop from the dwarves at the Dig Site).  The Geologists are limited, so you will most likely need to grind on mobs until they respawn (or go north for a few more).
03) Go back to the Wooden Outhouse (66.62, #1 on map), and turn in "Caught!", accept "Ledger from Tanaris".  Then pick up the Goodsteel Ledger (it drops on the ground next to the outhouse).
04) Do part of "Ledger from Tanaris": kill/loot Glassweb Spiders /target for the Leg Shafts.  These are scattered on the eastern side of Searing Gorge starting around 61.70.
05) Go up NW and from Kalaran Windblade 39.39 accept "Divine Retribution", then do it by simply talking to him.  Then turn it in.  From him, accept "The Flawless Flame".
06) Go up to Thorium Point (entrance at 33.30)...
07) Accept ALL quests at Thorium Point:  From the WANTED/Missing/Lost & Found sign 38.26 accept "WANTED: Overseer Maltorius", "STOLEN: Smithing Tuyere and Lookout's Spyglass" and "JOB OPPORTUNITY: Culling the Competition".
08) WOTLK, 7b) Next to you accept "Kill 'Em With Sleep Deprivation" 38.28.
09) Next to you 39.28 accept "Curse These Fat Fingers", "Fiery Menace!" and "Incendosaurs? Whateverosaur is More Like It"
10) Next to you by the Forge accept "What the Flux?" 39.29.  Make sure you are repaired/resupplied by this NPC as well.
11) Get the FP from the Wind Rider Master 35.31 at Thorium Point.
        ]],
        image = "imagen_031.jpeg",
    },
    [118] = {
        step = 118,
        title = [[NOTE  Do the Searing Gorge grind!  Do this section all at once (in any order)]],
        text = [[
01) "The Flawless Flame": kill/loot Magma Elementals, Tempered War Golems, and Heavy War Golems for the Golem Oil.  See next step for the Heart of Flame:
02) Kill/loot the fire elementals for the Heart of Flame, these include:  Inferno Elementals, Blazing Elementals and Magma Elementals.
03) "Fiery Menace!": kill Greater Lava Spiders around the western side of Searing Gorge.
04) "Curse These Fat Fingers": kill Heavy War Golems around the middle of Searing Gorge.
05) "STOLEN: Smithing Tuyere and Lookout's Spyglass": kill/loot Dark Iron Steamsmith for the Smithing Tuyere around 40.50.  See next step for where to find the Lookout's Spyglass:
06) Kill/loot Dark Iron Lookouts for the Lookout's Spyglass, these mobs are scattered around the watchtowers at Searing Gorge, there is a large amount around 53.59, see map for other locations.
07) Once "The Flawless Flame" is done, turn it in at Kalaran Windblade 39.39 and accept "Forging the Shaft".
        ]],
        image = "imagen_032.jpeg",
    },
    [119] = {
        step = 119,
        title = [[Guía de Leveo - Sección #33]],
        text = [[
01) "JOB OPPORTUNITY: Culling the Competition": enter one of the caves down in The Cauldron (middle of Searing Gorge), I recommend going into the eastern most cave entrance 49.45 and then kill the required amount of Dark Iron dwarves in the cave.
02) "What the Flux?" and "WANTED: Overseer Maltorius": loot the Secret Plans: Fiery Flux 40.36 behind Overseer Maltorius (41.36 in the cave). And kill/loot Overseer Maltorius (lvl 50).
03) WOTLK, 2b) In the hallways across the room around 45.31 do "Kill 'Em With Sleep Deprivation": loot the pillows along side the walls where the beds are at.  Watch out groups of sleepy dwarves patrol this hall and an elite mob can spawn in the middle of that hall, so be careful!  You can skip this if you don't want to wait for the pillows to respawn or deal with the mobs that are in the way.
04) "Forging the Shaft": kill/loot Dark Iron dwarves for the Thorium Plated Daggers.  NOTES:  This quest requires "The Flawless Flame" to be finished and turned in first.  Save any Dark Iron Scraps you find, you will need 30 of them for a later quest, but you will also have another good chance to find a lot more later on in the lvl 53-54 Burning Steppes section as well.
05) "Incendosaurs? Whateverosaur is More Like It": enter the cave (at 47.46) and kill 20 Incendosaurs.
        ]],
        image = "imagen_033.jpeg",
    },
    [120] = {
        step = 120,
        title = [[Guía de Leveo - Sección #34]],
        text = [[
01) Go to Kalaran Windblade 39.39 and turn in "Forging the Shaft", accept "The Flame's Casing".
02) Go up to Thorium Point (entrance at 33.30)...
03) Turn in "WANTED: Overseer Maltorius" 38.27.
04) WOTLK, 3b) Next to you, turn in (if you did it) "Kill 'Em With Sleep Deprivation" 38.28.
05) Next to you, turn in "Curse These Fat Fingers", "Fiery Menace!" and "Incendosaurs? Whateverosaur is More Like It" 39.28.
06) Next to you, turn in "STOLEN: Smithing Tuyere and Lookout's Spyglass" and "JOB OPPORTUNITY: Culling the Competition" 39.28.
07) At the Forge next to you turn in "What the Flux?" 39.29.  Make sure you are repaired/resupplied from this NPC.
08) Go west around 25.35 and do "The Flame's Casing": kill/loot the Twilight mobs until the Symbol of Ragnaros drops (low drop rate).
09) Go east to Kalaran Windblade (39.39, #1 on map) and turn in "The Flame's Casing", accept "The Torch of Retribution".
10) Wait a few seconds, then turn in "The Torch of Retribution", accept the next part.  Then click on the Torch of Retribution in the air next to you to turn in the next part of "The Torch of Retribution".  Accept "Squire Maltrake".  Next to you, turn in "Squire Maltrake", accept "Set Them Ablaze!".
        ]],
        image = "imagen_034.jpeg",
    },
    [121] = {
        step = 121,
        title = [[Guía de Leveo - Sección #35]],
        text = [[
01) Do "Set Them Ablaze!": equip the Torch of Retribution quest item and at the top of the 4 watchtowers, click on the Sentry Braziers.  The Northern Tower is at 33.54.  See next steps for the others:
02) The Western Tower is at 36.61.
03) The Southern Tower is at 44.61.
04) The Eastern Tower is at 50.55.  NOTE:  You must cross a bridge to get to it.
05) While doing the quests associated with killing the Dark Iron dwarves, you should have obtained an item called Grimsite Outhouse Key, from it accept "The Key to Freedom".  Then go SE and turn this in at the Wooden Outhouse 66.62.
06) N/A
07) Go NW to Kalaran Windblade 39.39 and turn in "Set Them Ablaze!".
08) Wait a minute (build up First Aid while waiting), then click on the Hoard of the Black Dragonflight 39.39 chest on the ground next to Kalaran Windblade and accept "Trinkets...".  Then click on the chest again to turn this in.  Loot the chest received.
09) NOTES:  Make sure you keep the Black Dragonflight Molt in your inventory as you will need it for a later quest.  Also make sure you have all 20 Solid Crystal Leg Shafts for the quest "Ledger from Tanaris".
10) Head south into Burning Steppes (entrance at 35.87 in Searing Gorge).  NOTE:  You have to go through Black Rock Mountains.
11) Once at Burning Steppes, first head to 25.53 just to discover Draco'dar for XP.
12) N/A
13) Go up the ramp into Flame Crest.  You can get repaired/resupplied in the small cave from the female goblin 66.22.
14) At the Wind Rider Master 66.24 fly to Stonard, Swamp of Sorrows.  NOTE:  If you still have "What the Flux?" or "WANTED: Overseer Maltorius" they can be abandoned.
        ]],
        image = "imagen_035.jpeg",
    },
    [122] = {
        step = 122,
        title = [[49 Swamp of Sorrows]],
        text = [[
01) Go in the Inn and make Stonard your new home from the Innkeeper 45.57.
02) Go SW on the main path and from Fallen Hero of the Horde 34.66 accept "Fall From Grace".  Then do it by simply talking to the NPC.  Turn it in and accept "The Disgraced One".
03) Go NW and click on A Soggy Scrolll under the bridge 23.48 to turn in "Cortello's Riddle", accept the next part.
04) Go back to Stonard.
05) N/A
06) Up in the building 48.55, turn in "The Disgraced One", accept "The Missing Orders".  And turn in (if you have it) "Return to Fel'Zerul", SKIP "The Temple of Atal'Hakkar" (Dungeon).
07) In the Inn turn in "The Missing Orders" (45.57, #1 on map), accept "The Swamp Talker".
08) N/A
09) Go west to Stagalbog Cave entrance 66.78 and do "The Swamp Talker": back in the cave kill/loot Swamp Talker 63.88 or at 64.80 /target for the Warchief's Orders.  To get to the Swamp Talker take the middle path in the cave and keep left.
        ]],
        image = "imagen_036.jpeg",
    },
    [123] = {
        step = 123,
        title = [[Contested - Stranglethorn Vale]],
        text = [[
01) At the middle of the shore of SoS, do part of "Ledger from Tanaris": kill/loot Jarquia (around 95.52, /target), he drops the Goodsteel's Balanced Flameberge.
02) Hearth to Stonard.  Make sure you are repaired/resupplied.
03) Go SW on the main path and from Fallen Hero of the Horde 34.66 turn in "The Swamp Talker", accept and do "A Tale of Sorrow" by simply talking to the NPC.  Then turn it in, SKIP "The Stones That Bind Us" (for now).
04) Back at Stonard, go to the Wind Rider Master 46.55 and fly to Booty Bay, Stranglethorn...
05) Drop down in the Inn at BB and accept "Whiskey Slim's Lost Grog" 27.77.
06) Get on the boat at the end of docks 26.73 to go to Ratchet.  NOTE:  If the boat is not there yet you can do the next step at BB's Bank!
07) Once at Ratchet, go to the Bank 63.37 and put the following items into it:  Torch of Retribution (can be used as a future light source), Black Dragonflight Molt, and any of Dark Iron Scraps or Core of Elements you may have.  Get out of the bank: Yeh'kinya's Bramble, Wastewander Water Pouches and Hippogryph Egg.
08) Go to the Flight Master at Ratchet 63.37 and fly to Brackenwall Village, Dustwallow Marsh.
        ]],
        image = "imagen_037.jpeg",
    },
    [124] = {
        step = 124,
        title = [[49 Dustwallow Marsh]],
        text = [[
01) Once at Brackenwall Village, go in the small cave and accept "The Brood of Onyxia" 37.33.
02) Go SE to the crashed zeppelin and do the last part of "Ledger from Tanaris": loot the Damaged Crate 54.56 for the Overdue Package.
03) Go south and do "The Brood of Onyxia": look for the red steam nests holding the Eggs of Onyxia and click on them to destroy them.  There is one at 54.73, and another one at 48.74.
04) Go west to Bloodfen Burrow (small cave) and click on the Musty Scroll 31.66 to turn in "Cortello's Riddle", accept the next part.
05) TBC, 4a) Go to the Flight Master 43.72 at Mudsprocket and fly to Brackenwall Village, Dustwallow Marsh.
06) Go in the small cave and turn in "The Brood of Onyxia" (37.33, #1 on map).
07) GROUP 2+ Players:  From Overlord Mok'morokk by the Bonfire 36.31, accept and do "Challenge Overlord Mok'Morokk" by beating him to a duel.  You only need to get his health down to 1/3 left.
08) Turn in (if you did it) "Challenge Overlord Mok'Morokk" (in the small cave 37.33, #1 on map).
09) Go to the Wind Rider Master 36.32 and fly to Gadgetzan, Tanaris.
        ]],
        image = "imagen_038.jpeg",
    },
    [125] = {
        step = 125,
        title = [[50 Tanaris]],
        text = [[
01) As you enter Gadgetzan (next to the crane 52.27), accept "Thistleshrub Valley".
02) 01a) Go to the Egg-O-Matic machine 52.27 in Gadgetzan (next to the teleporter), and turn in your Hippogryph Egg for "The Super Egg-O-Matic" quest (additional eggs do not yield XP).  NOTE:  You can turn in different types of eggs at the NPC next to the machine for a non-XP reward.
03) Behind the Inn, next to the Bonfire, accept "The Dunemaul Compound" 53.27.
04) Go in the Inn and make Gadgetzan your new home 53.28.
05) Next to the Inn/Bank at the windmill 52.29, turn in "Into the Field", accept and complete "Slake That Thirst".  Do not accept the quest from the item received yet, this will be done later.
06) Next to the AH, accept "The Thirsty Goblin" 52.29.
07) Next to the Forge, turn in "Ledger from Tanaris" 51.29.
08) On the western side of Gadgetzan, up on the hill, accept "Noxious Lair Investigation" 50.27.
09) Go south to the Broken Pillar and turn in "The Sunken Temple" 53.46, accept "The Stone Circle".  Also accept "Gahz'ridian".
10) Go SW and do part of "The Dunemaul Compound": kill Gor'marok the Ravager (in the small cave 41.58).
11) Go south to Southmoon Ruins around 40.72 and do "The Dunemaul Compound" along with "Gahz'ridian": kill 10 Dunemaul Brutes and 10 Dunemaul Enforcers.  Also loot the Gahz'ridian from the ground.  TIP:  You can equip the Gahz'ridian Detector helm to help you see the Gahz'ridian on the minimap.  Also, there is another area of mobs, but with less Gahz'ridian, around 47.65.
        ]],
        image = "imagen_039.jpeg",
    },
    [126] = {
        step = 126,
        title = [[Guía de Leveo - Sección #43]],
        text = [[
01) Go west to The Noxious Lair around 35.48 and do "Noxious Lair Investigation": kill/loot the Centipaar bugs, and any of them can drop the insect parts.
02) Go south to Thistleshrub Valley around 30.65 and do "Thistleshrub Valley" along with "The Thirsty Goblin": kill 8 Gnarled Thistleshrubs and 8 Thistleshrub Rootshapers.  Also kill/loot the Thistleshrub Dew Collectors /target for the Laden Dew Gland (low drop rate).
03) At the Thistleshrub Valley (32.74 or 29.63) accept and do the escort quest "Tooga's Quest": escort Tooga /target (turtle) NE to Torta (At next step):
04) Once at Torta 67.26, turn in "Tooga's Quest".
05) Just north of you at Steamwheedle port, go in the southern hut and accept "Yuka Screwspigot" 67.24.
06) North at Steamwheedle Port turn in "Screecher Spirits" 67.22, SKIP "The Prophecy of Mosh'aru" (Zul'Farrak Dungeon).
07) Hearth to Gadgetzan.  Make sure you are repaired/resupplied.
08) Next to the AH, turn in "The Thirsty Goblin" 52.29, accept "In Good Taste".
09) At Sprinkle 51.27 (NW hut), turn in "In Good Taste", accept "Sprinkle's Secret Ingredient".
10) In the hut next to you, turn in "Noxious Lair Investigation" 51.27.
11) Next to the crane near the Gadgetzan entrance, turn in "Thistleshrub Valley" 52.27.
12) Behind the Inn, next to the Bonfire, turn in "The Dunemaul Compound" 53.27.
13) Go to the Gadgetzan Bank 52.29 (SE hut) and get the following items out:  Field Testing Kit and (if you have it) OOX-17/TN Distress Beacon.
14) On the western side of Gadgetzan, up on the hill, accept "The Scrimshank Redemption" 50.27.
        ]],
        image = "imagen_043.jpeg",
    },
    [127] = {
        step = 127,
        title = [[50 Azshara]],
        text = [[
01) From the item Model 4711-FTZ Power Source in your inventory, accept and do "Tanaris Field Sampling": start killing beasts just south of Gadgetzan.  You need to kill/loot any Basilisks, Hyenas, and Scorpids.  You will find these beasts all around the open fields of Tanaris.  You only have 2 hours to do this and the next few steps, so work quickly.  While doing this, do the following 3 steps as well:
02) Grind your way down south to the Broken Pillar and turn in "Gahz'ridian" 53.46.
03) N/A
04) If you have the item OOX-17/TN Distress Beacon, from it accept "Find OOX-17/TN!".  Then turn this in at 60.65. NOTE: The chicken escorts are skipped for TBC/SOM.
05) Make sure "Tanaris Field Sampling" is complete.  Then go SE to The Gaping Chasm and do "The Scrimshank Redemption": go in the specific cave entrance 56.69 and keep making right turns in the cave, which will lead you to the item you need to loot.
06) Hearth (if you can), or Die on purpose, then head north to get back to Gadgetzan.
07) Next to the Inn at the windmill 52.29, turn in "Tanaris Field Sampling", accept "Return to Apothecary Zinge".  You can then destroy the Model 4711-FTZ Power Source item if it remains in your inventory.
08) On the western side of Gadgetzan, up on the hill, turn in "The Scrimshank Redemption" 50.27, accept "Insect Part Analysis".
09) In the hut NW in Gadgetzan, turn in "Insect Part Analysis" 51.27, accept the next part.
10) Go back to the western side of Gadgetzan, up on the hill (50.27, #8 on map) and turn in "Insect Part Analysis".  Accept "Rise of the Silithid".
11) Make sure you are level 50, grind on any mob until you are.
12) Go to the Wind Rider Master (north of Gadgetzan 52.25) and fly to Orgrimmar, Durotar.
13) Go in Orgrimmar's Inn and make it your new home 54.68.  And from the Innkeeper, accept "Assisting Arch Druid Runetotem".  Make sure you are resupplied.
14) Go to the Bank 50.69 and get the following items out:  Sealed Letter to Ag'tor, Box of Empty Vials.
15) GET NEW ABILITIES, 14b) Get your level 50 spells/abilities.
16) Go up to the Wind Rider Master 45.64 and fly to Splintertree Post, Ashenvale.
17) Follow the main path east into Azshara entrance 95.48.
18) First Pick the Class you are playing top left of screen!!!
19) Along with the Game Version you are playing on (Era, SoM, TBC or WotLK)
20) Head NE to Valormok, Azshara, and turn in "Betrayed" 22.51, SKIP the next part.
21) TBC, 1b) From Jediga accept "Stealing Knowledge" 23.51.
22) Go east to the Ruins of Eldarath around 37.53 and do "Stealing Knowledge": loot the 4 tablets, they are scattered around the ruins (see map for possible spawn locations).
23) Go east to Southridge Beach and do "Seeping Corruption": open your Box of Empty Vials to get your 4 Vials out, then go to the 4 tide pools and use your vials at each of them.  Fill Vial #1 at Tide Pool #1 48.61.  See next steps for the other three:
24) Go north to Tide Pool #2 to fill Vial #2 48.51.
25) Go north to Tide Pool #3 to fill Vial #3 49.48.
26) Go north to Tide Pool #4 to fill Vial #4 47.46.
27) Go back to Valormok at Jediga (23.51, #1 on map) and turn in "Stealing Knowledge".  Accept ALL 4 Delivery quests from her.
28) You can get resupplied at Valormok from Kurll 22.52.  Or repaired from Gruul Darkblade /target 22.51.
29) N/A
30) Go east to Sanath Lim-yo (28.50, #2 on map) and turn in "A Meeting with the Master".  Then click on him again to teleport you to see his master.  Once teleported, go up the path and go up in the tower to Archmage Xylem /target to turn in "Delivery to Archmage Xylem", accept "Xylem's Payment to Jediga".
31) Drop down in the tower to leave it and go back down the path to Nyrill 26.46 and have him teleport you back down.
32) Go west to Valormok and from Jediga turn in "Xylem's Payment to Jediga"(23.51, #1 on map).
33) Go north in Valormok to the Wind Rider Master 22.50 and fly to Thunder Bluff, Mulgore.
        ]],
        image = "imagen_044.jpeg",
    },
    [128] = {
        step = 128,
        title = [[Guía de Leveo - Sección #01]],
        text = [[
01) Go to The Elder Rise and turn in "Delivery to Magatha" 70.31, accept "Magatha's Payment to Jediga".
02) Go just east in the big tent and turn in "Assisting Arch Druid Runetotem" 79.29, SKIP "Un'Goro Soil" (for now).
03) Hearth to Orgrimmar.
04) 03b) Check the AH 54.64 for a Mithril Casing and if you are able to get it, store it in your bank for now for a later quest at Un'goro Crater.
05) Go to the Bank 50.69 and get the following items out:  Bundle of Atal'ai Artifacts.  Also get out (if you need to) 60 Silk Cloth and 60 Mageweave Cloth (for cloth donations to the Orc faction).
06) Go to The Drag and up in the hut turn in "Rise of the Silithid" 56.47.  Accept "March of the Silithid".
07) Drop down to Magar's Cloth Goods and turn in the cloth donations you have to the Orc's Horde Cloth Quartermaster 64.51.
08) North in The Drag (up in Yelmak's Alchemy and Potions), turn in "Delivery to Jes'rimon" up 56.34, accept "Jes'rimon's Payment to Jediga".  Also accept "Bone-Bladed Weapons".
09) IF YOU HAVE IT: In Droffers And Sons Salvage, turn in "Ripple Delivery" 59.37 , SKIP "Necklace Recovery".
10) If you need to, get new spells/abilities.
        ]],
        image = "",
    },
    [129] = {
        step = 129,
        title = [[Orc/Troll - Durotar]],
        text = [[
01) Leave Orgrimmar south and get on the zeppelin (51.14 in Durotar) to go to The Undercity.
02) Once at the UC, head to The Apothecarium and turn in "Delivery to Andron Gant" 55.76, accept "Andron's Payment to Jediga".
03) Go down in The Apothecarium entrance 52.81 and turn in "Seeping Corruption" 49.71.  Wait a few seconds, and accept the next part.  Then right next to you (at the female tauren), turn in "Seeping Corruption".  Then next to you at Chemist Cuely, turn it in again.
04) In the same room, turn in "Return to Apothecary Zinge" 50.68.  Accept "Vivian Lagrave".  NOTE:  After turning this in, if the Field Testing Kit remains in your inventory you can destroy it.
05) Across the same room from Chemist Fuely 47.73, accept "A Sample of Slime..." and "... and a Batch of Ooze".
06) Go to the Bat Handler 63.49 and fly to Tarren Mill, Hillsbrad.
        ]],
        image = "",
    },
    [130] = {
        step = 130,
        title = [[51 Hinterlands]],
        text = [[
01) Go into the Hinterlands (entrance at 89.27 in Hillsbrad Foothills).
02) Go up to Shindigger's Camp and turn in "Ripple Recovery" 27.49, SKIP "A Sticky Situation".
03) Go south to Shadra'Alor, to the top of the temple entrance 36.65, then drop down and turn in "The Atal'ai Exile" 34.75 (See Video on where to find this dude at), SKIP "Return to Fel'Zerul".
04) Go north to Valorwind Lake 41.59 and do "Sprinkle's Secret Ingredient": under the water loot a Violet Tragan (mushroom).
05) N/A
06) Go east to Revantusk Village and on the docks accept "Snapjaws, Mon!" and "Gammerita, Mon!" 80.82.
07) In the Inn accept "Lard Lost His Lunch" 78.81.  Make sure you are repaired/resupplied.  NOTE:  Maintain hearthstone with Orgrimmar!
08) Just north of Revantusk Village along the shore, do "Snapjaws, Mon!" along with "Whiskey Slim's Lost Grog": kill Saltwater Snapjaws (turtles) and loot the Pupellyverbos Port (blue bottles on the ground).  Do the next step as well at the same time as these:
09) Do "Gammerita, Mon!": kill/loot Gammerita /target.  This lvl 48 turtle patrols up and down the shore line.  He spawns just south of the waterfall/shore (underneath #6 on map).
10) Go north and right underneath the waterfall 81.47, loot Cortello's Treasure chest to turn in "Cortello's Riddle" (14 slot bag along with 6100 XP)!
11) Go to the little island NE and do "Lard Lost His Lunch": loot Lard's Picnic Basket 84.41 and then kill/loot the two lvl 49 trolls that spawn, you will get Lard's Lunch from the first one you loot.
        ]],
        image = "",
    },
    [131] = {
        step = 131,
        title = [[Horde - The Barrens]],
        text = [[
01) Go in the Inn and turn in "Lard Lost His Lunch" 78.81.
02) On the docks, turn in "Snapjaws, Mon!" and "Gammerita, Mon!" 80.82.
03) Hearth to Orgrimmar.  Make sure you are repaired/resupplied.
04) Go up to the Wind Rider Master 45.64 and fly to Valormok, Azshara.
05) Once at Valormok, Azshara, from Jediga 23.51 turn in the 3 Delivery quests:  "Magatha's Payment to Jediga", "Jes'rimon's Payment to Jediga" and "Andron's Payment to Jediga".
06) Go north in Valormok to the Wind Rider Master 22.50 and fly to Ratchet, The Barrens.
07) At Ratchet do "The Stone Circle": just right outside of Liv Rizzlefix's hut (at the entrance 62.39), loot Marvon's Chest.  Also, go in Liv Rizzlefix's hut and accept "Volcanic Activity".
        ]],
        image = "",
    },
    [132] = {
        step = 132,
        title = [[Guía de Leveo - Sección #07]],
        text = [[
01) Go in the Inn and make Ratchet your new home 62.39.
02) Stop at Ratchet's Bank 63.37 and put the following items into it:  stack of Pupellyverbos Port.
        ]],
        image = "",
    },
    [133] = {
        step = 133,
        title = [[Guía de Leveo - Sección #08]],
        text = [[
01) 51 Blasted Lands
02) PLEASE READ: With all the faster leveling changes, by the time you get to this section you will most likely be well into level 51+. Because of this when following my guide, you should skip this entire section and go right into the section right before 51-53 Un'Goro Crator below.  I will leave this section for reference purposes only.  However if for some reason you are still level 50 you can consider doing this section.  If you are NOT doing this section then abandon (if you have any of them): "The Stones That Bind Us".
03) Go up in the Inn on the roof and from the Wind Rider Master 27.77 fly to Stonard, Swamp of Sorrows.
04) Follow the main path SW and from the Fallen Hero of the Horde 34.66 accept "The Stones That Bind Us".
05) Head south into Blasted Lands...
06) As you enter Blasted Lands go to the small quest hub at 51.14.  Accept all 5 quests there.  These 5 quests requires the following total number of items to complete them.  The items needed can drop without needing to accept the quests.  The color codes below show where the mobs are at on the images and stars represent rare mobs that may not be there. Work on the rest of this section all at once):
07) Mob - Total Items Needed - After "The Decisive Striker" - And then "Vulture's Vigor"
08) Vulture Gizzards     =14 - 12 - 2
09) Basilisk Brain         =11 - 11 - 11
10) Blasted Boar Lungs =6 - 5 - 5
11) Scorpok Pincers      =6 - 3 - 3
12) Snickerfang Jowls   =5 - 5 - 3
13) 2+ PLAYERS (or could be soloable): While grinding for these items, do "The Stones That Bind Us": drag the different servants close to their Stone of Binding crystal next to each of them, then kill them along with attacking the crystal as well.  This allows you to actually kill the mob and get quest credit.  Each of these different servants are located at different parts of the Blasted Lands.  See map for locations.  If for some reason you cannot solo this quest, it can be skipped.
14) While grinding make sure you get everything discovered for XP (including The Tainted Scar at 44.57).
15) As you get these items, you can turn the quests in for a 60 min stat reward that will help you grind faster in Blasted Lands or even for the next section Un'Goro Crater (although they don't stack).  I recommend only showing the quests on screen that you want the rewards first.  Go to the quest hub (at 51.14, #1 on map) and turn in all 5 of these quests:  "Snickerfang Jowls" (+25 Strength), "A Boar's Vitality" (+25 Stamina), "The Decisive Striker" (+25 Agility), "The Basilisk's Bite" (+25 Intellect) and "Vulture's Vigor" (+25 Spirit).  NOTE:  The follow up quests do NOT yield XP: "Rage of Ages", "Spirit of the Boar", "Salt of the Scorpok", "Infallible Mind", and "Spiritual Domination".
16) While questing in Blasted Lands, you may have came across an item called Imperfect Draenethyst Fragment, turn these in at 52.36 for the quest "Everything Counts In Large Amounts".  NOTE:  I have NEVER found a Flawless Draenethyst Sphere for the quest "To Serve Kum'isha" ..good luck on that.  Also, the follow up quest "One Draenei's Junk" is repeatable but yields no XP.
17) Go to the border of Blasted Lands and SoS, to the Fallen Hero of the Horde (34.66 in SoS) and turn in (if you did it) "The Stones That Bind Us", SKIP "Kirith".  Accept "Heroes of Old".
18) Next to you on the other side of the path, turn in (if you have it) "Heroes of Old" (33.66 in SoS), accept the next part.  Then click on the Spectral Lockbox on the ground next to you to turn it in.
19) Hearth to Ratchet.  NOTE:  If you did not do "The Stones That Bind Us", then abandon the quest.
20) At Ratchet's Bank 63.37, get the following items out:  Violet Tragan and (if you have it) Stone Circle.
21) Go into Ironzar's Imported Weaponry to get repaired/resupplied from Ironzar 62.37.  You can destroy any remaining unsellable Blasted Lands beast items you have (or bank them if you want).
        ]],
        image = "",
    },
    [134] = {
        step = 134,
        title = [[Guía de Leveo - Sección #09]],
        text = [[
01) 53 Un'Goro Crater
02) Go to the Flight Master 63.37 and fly to Gadgetzan, Tanaris.
03) As you enter Gadgetzan (next to the crane 52.27), accept "Super Sticky".
04) At Sprinkle (by the NW hut 51.27), turn in "Sprinkle's Secret Ingredient".  Wait a few seconds (do next step while waiting) then accept "Delivery for Marin".
05) In the hut next to you, turn in "March of the Silithid" 51.27, accept "Bungle in the Jungle".
06) Next to the AH, from Marin Noggenfogger 52.29, turn in "Delivery for Marin".  NOTE:  "Noggenfogger Elixir" can take up to a minute for the NPC to make the item for you, it does not yeild any XP, so you can do this when you are not in a hurry (such as after level 60).  The Noggenfogger Elixir item is used for fun and can be stored in the bank when you want to use it.
07) At the Bank 52.29, get out: (if you have it) Mithril Casing (this item may be in your mailbox 52.28), this is used for a quest in Un'Goro Crater, and remember to not sell this to a vendor.  You can also check the neutral AH in Gadgetzan for it as well.
08) Head south to the Broken Pillar and turn in "The Stone Circle" 53.46.
09) Go SW into Un'Goro Crater (entrance at 27.54 in Tanaris)...
        ]],
        image = "",
    },
    [135] = {
        step = 135,
        title = [[Guía de Leveo - Sección #10]],
        text = [[
01) At the bottom of the path into Un'Goro Crater, go up the hill next to the waterfall 72.76 and accept "The Apes of Un'Goro" and "The Fare of Lar'korwi".
02) WOTLK, 1b) Just down the hill a bit, accept "Toxic Tolerance" 71.74.
03) Go north a bit and do "The Fare of Lar'korwi": loot the big Fresh Threshadon Carcass lying on the ground 69.57.
04) Grind north to the entrance of Marshal's Refuge and accept "Chasing A-Me 01" 46.13.  While on your way, also start collecting crystals (the red, blue, green and yellow) scattered everywhere.  Kill/loot oozes too!
05) Go up into Marshal's Refuge and accept ALL quests there:  From the goblin on top of the hill, accept "Shizzle's Flyer" 44.12.
06) Move into Marshal's Refuge 44.8 and accept "Lost!", (from the Wanted Sign Beware of Pterrordax) "Beware of Pterrordax".
07) Make sure you are repaired/resupplied 43.8.
08) Next to you accept "Roll the Bones" 43.7.
09) Next to you 44.7 accept "Alien Ecology" and "Expedition Salvation".  NOTE:  If you have already found A Mangled Journal, accept and turn in "Williden's Journal".
10) On the east side of Marshal's Refuge behind the hill, accept "Larion and Muigin" 46.9.
11) Time to do the Un'Goro Grind! NOTES For the Grind:
12) - Don't worry about looting the Un'Goro Dirt Piles, you will find enough Un'Goro Soil from mob drops.  Also do not sell the Un'Goro Soil to vendors, you will need these for quest turn-ins!
13) - Don't worry about looting the Bloodpetal Sprouts, as they are not turned in for any XP.
14) - The Dinosaur Bones you need for the quest "Roll the Bones" will drop from many different mobs as you do the other quests.
15) - As your questing, kill/loot Oozes (slimes) you see, and collect15 Ooze samples (15 is the max you can hold for WOTLK), this is for "... and a Batch of Ooze".  These Oozes are scattered all around Un'Goro Crater.
16) - Also while questing, loot 7 crystals of each color (red, blue, green, and yellow) for a later quest.  These crystals are scattered all around Un'Goro Crater.
17) - The Bloodpetel mobs (plants) drop Savage Fronds, you could collect 30 of these for a later quest at lvl 59.  As you are doing the Un'Goro quests associated with these mobs you should get about half, so grind on these that you see along the way and see what you can get before leaving Un'Goro Crater, and you could always check the AH for more of these, or just skip this entirely.
18) - Watch out for the Elite Devilsaurs patrolling around this zone.  I highlighted them through out the images so you can be alerted if you are in a danger zone for them.
        ]],
        image = "imagen_010.jpeg",
    },
    [136] = {
        step = 136,
        title = [[LET THE GRIND BEGIN]],
        text = [[
01) Just south of Marshal's Refuge around 46.16 do "Super Sticky": kill/loot the Tar mobs around the tar pits.
02) Go NE to Fungal Rock and start working on "The Apes of Un'Goro": kill/loot the apes (in and outside of the cave).  Also go in the cave entrance 64.16 and then make a right and turn in "Chasing A-Me 01" 68.17, then if you have a Mithril Casing with you, accept and turn in "Chasing A-Me 01".  Then accept and do the escort "Chasing A-Me 01": escort A-Me 01 to Marshal's Refuge, and then turn it in once you get there.
03) Start working on "Larion and Muigin": kill Bloodpetal Flayers around the north-middle of Un'goro Crater.  NOTE:  These mobs are also found south-middle as well, so you don't need to finish all of this now, work your way to the next step..
04) Go up on the mountain ledge (ramp entrance at 55.12) and start working on "Shizzle's Flyer": kill/loot the Pterrordax /target.  There are only 6 mob spawns here, so clear the area once and move on to the next step..
05) Make sure "The Apes of Un'Goro" is finished: kill/loot the apes (in and outside of the cave around 64.16, #2 on map).
06) Do the next part of "Larion and Muigin": kill Bloodpetal Lashers and Threshers around the NE side of Un'goro Crater.  Also, kill/loot any Dinosaurs you see for part of "Shizzle's Flyer" (don't need to finish it now though).  Keep the next step in mind:
07) Go SE and do part of "Expedition Salvation": under the tent, loot the Crate of Foodstuffs 69.37.
08) Finish up killing the Bloodpetal Flayers for "Larion and Muigin" by starting below the river around 61.48 and work you way south.  Kill/loot any Diemetradon you see as well for "Shizzle's Flyer".  NOTE:  Try to avoid the Raptors as you will be grinding them soon with more quests associated with them.
09) Grind your way SE to Torwa Pathfinder on top of the hill by the waterfall and turn in "The Apes of Un'Goro" 72.76.  Accept "The Mighty U'cha".  And turn in "The Fare of Lar'korwi", accept "The Scent of Lar'korwi".
        ]],
        image = "imagen_011.jpeg",
    },
    [137] = {
        step = 137,
        title = [[Guía de Leveo - Sección #12]],
        text = [[
01) Just to the west of you at The Marshlands do "Bone-Bladed Weapons" along with "The Scent of Lar'korwi": kill/loot raptors and to get the Ravasaur Pheromone Glands you need, run across the egg nests (there is 5 total: 67.73 63.77 67.67 61.72 62.66) and then kill/loot the Lar'korwi Mates that spawn in.  Keep the next step in mind:
02) WOTLK, 1b) Also more north in the raptor area around 69.53 do "Toxic Tolerance" by letting the Venomhide Ravasaurs /target (darker colored ones) spit poison on you 20 times.
03) At The Marshlands, at the western most pond, north on it's shore, click on A Wrecked Raft 63.69 to accept "It's a Secret to Everybody".  Then right next to the wrecked raft, under the water, click on A Small Pack to turn in "It's a Secret to Everybody", accept the next part.  NOTE:  To free up bag space, do NOT loot A Small Pack yet!
04) WOTLK, 2b) Just down the hill a bit, turn in "Toxic Tolerance" 71.74, accept "Venomhide Eggs".
05) Go east to Torwa Pathfinder on top of the hill by the waterfall and turn in "The Scent of Lar'korwi" 72.76, accept "The Bait for Lar'korwi".  NOTE:  To free up bag space, do NOT loot A Small Pack yet!
06) WOTLK, 3b) Around the raptor area around 67.73 do "Venomhide Eggs": loot 4 Venomhide Eggs (around the little nests as with previous quest), see Questie locations on map.
07) WOTLK, 3c) Turn in "Venomhide Eggs".  NOTE: "They Grow Up So Fast" can be done if you like, but requires items you would need to search around for, also costs 80 gold.  But this can reward you with a new epic Whistle of the Venomhide Ravasaur mount.
08) Go west to The Slithering Scar and do "Alien Ecology" along with "Bungle in the Jungle": enter the cave entrance 50.81.  Make a left in the cave and then use your Unused Scraping Vial quest item on the mound in the center of the room.  And keep kill/looting the Gorishi bugs until you get the Gorishi Scent Gland (can drop from any of them, but has a low drop rate).  These bugs can be found in and outside of the cave.
09) Go south up at the ledges around 56.90 to continue obtaining the Webbed Pterrordax Scales (you will be able to get more of these later) for "Shizzle's Flyer".  There is another spot of these mobs around 45.90.
10) Grind NW a bit to the old camp site 38.66 and do the last part of "Expedition Salvation": loot the Research Equipment (looks like a stack of brown boxes next to a tent).
11) All around the western side of Un'Goro Crater, finish up "Larion and Muigin" (kill Bloodpetal Trappers) along with finishing up "Beware of Pterrordax", "Shizzle's Flyer" and "Roll the Bones" (kill/loot Frenzied Pterrordax).  The Dinosaur Bones can also drop from Elder Diemetradon and regular Diemetradon mobs (found south-middle).  Keep the next step in mind:
12) At the Golakka Hot Springs (below the hotspring mountain), accept "Finding the Source" 31.50.
        ]],
        image = "imagen_012.jpeg",
    },
    [138] = {
        step = 138,
        title = [[Guía de Leveo - Sección #13]],
        text = [[
01) Do "Volcanic Activity" along with "Finding the Source".  First go to the north entrance at Fire Plume Ridge (spiky bridge entrance at 53.43).  Follow the path upwards to the top and use Krakle's Thermometer quest item at the Fire Plume Ridge Hot Spot (the one at 50.46).  Watch out for the lvl 56 Elite mob in the cave at the top of the Ridge.  Also kill/loot the fire elementals around Fire Plume Ridge for the 9 Un'Goro Ash and to start collecting Core of Elements for a future quest (I recommend at least getting about 10 for now).
02) Make sure all the quests above are done, including obtaining 7 crystals of each color (red, blue, green, and yellow), then go to the small cave at the eastern side of Fire Plume Ridge and turn in "Lost!" 52.50.
03) Accept and do the escort "A Little Help From My Friends": escort Ringo /target back to Marshal's Refuge 44.9.  You will need to use the quest item Spraggle's Canteen on Ringo to wake him up if he faints.
04) Turn in ALL quests at Marshal's Refuge and accept new ones:  Turn in "Shizzle's Flyer" (on top of hill 44.12).
05) turn in "A Little Help From My Friends" and "Beware of Pterrordax" 44.9.
06) Make sure you are repaired/resupplied 43.8.
07) Next to you turn in "Roll the Bones"43.7.
08) Next to you 44.7 turn in "Alien Ecology", "Expedition Salvation" and (if you haven't yet) accept and turn in "Williden's Journal" from the item A Mangled Journal (this item/quest is obtained while killing any mob in Un'Goro Crater that should be in your inventory by now).
09) Enter the cave at Marshal's Refuge entrance 43.6 and at the very end of the cave accept and turn in "Crystals of Power" 42.3.  Then accept the 3 Pylon quests:  "The Northern Pylon", "The Eastern Pylon" and "The Western Pylon".  You can destroy any remaining crystals in your inventory (to free bag space).
10) Open and loot A Small Pack in your inventory and then go to Linken (in the middle of Marshal's Refuge behind some trees 45.8) and turn in "It's a Secret to Everybody", accept the next part.  NOTE:  The Faded Photograph is not needed and will remain in your inventory forever unless you destroy or bank it.
11) At the eastern side of Marshal's Refuge behind the hill, turn in "Larion and Muigin" 46.9, accept "Marvon's Workshop".
        ]],
        image = "imagen_013.jpeg",
    },
    [139] = {
        step = 139,
        title = [[Guía de Leveo - Sección #14]],
        text = [[
01) Go east up on the ledges and do "The Northern Pylon": click on the Northern Crystal Pylon 57.13.
02) Go east to Fungal Rock and do "The Mighty U'cha": enter the cave entrance 65.16, then keep left in the cave until you get to U'cha (lvl 55 red colored ape) and kill/loot him.
03) On the eastern side of Un'Goro Crater, go up on the ledges and do "The Eastern Pylon": click on the Eastern Crystal Pylon 77.50.
04) Just to the east of you on the mountain ledges there, do "The Bait for Lar'korwi": at the old dinosaur bones, there is a gray flat rock on the ground at 80.50.  At this spot open your Torwa's Pouch quest item and first use the Preserved Threshadon Meat quest item, then use the Preserved Pheromone Mixture at this spot, then kill/loot Lar'korwi that spawns in (See Video).
05) Go south to Torwa Pathfinder on top of the hill by the waterfall 72.76 and turn in "The Bait for Lar'korwi" and "The Mighty U'cha".
06) Go west (kill/looting oozes along the way if you still need to get the 15 Slime samples) and up on the mountain ledges do "The Western Pylon": click on the Western Crystal Pylon 24.59.
07) Go NE to Golakka Hot Springs (below the hotspring mountain) and turn in "Finding the Source" 31.50, accept "The New Springs".
08) Grind your way back north to Marshal's Refuge entrance 46.13.  Make sure you get all 15 Un'goro Slime Samples along the way by kill/looting oozes (slimes).  Also at this time see if you can obtain 30 Savage Fronds from the Bloodpetel mobs (plants all around Un'Goro), 30 of these can be used for a later quest at lvl 59.  If you are still far behind on that then don't worry about it, you may find more in the AH (or just skip it).
09) Enter the cave at Marshal's Refuge entrance 43.6 and work your way to the end of the cave and turn in "The Northern Pylon", "The Eastern Pylon" and "The Western Pylon".  Then accept and turn in "Making Sense of It".  NOTE:  The Crystal Pylon User's Manual can be destroyed or saved in your bank for later reference and you can always get a new one from this NPC in the cave.
10) Leave the cave, make sure you are repaired/resupplied 43.8.
11) Go up on the eastern side of Marshal's Refuge, to the Flight Master 45.6 and fly to Gadgetzan, Tanaris.
        ]],
        image = "imagen_014.jpeg",
    },
    [140] = {
        step = 140,
        title = [[Tauren - Mulgore]],
        text = [[
01) As you enter Gadgetzan (next to the crane) turn in "Super Sticky" 52.27.
02) In the NW hut, turn in "Bungle in the Jungle" 51.27.
03) Go to the Wind Rider Master 52.25 (north of Gadgetzan) and fly to Thunder Bluff, Mulgore.
04) Go to Elder Rise and from Arch Druid Hamuul Runetotem, accept "Un'goro Soil" 79.29.
05) On the north side of Elder Rise, turn in "Un'goro Soil" 77.22.
06) Go back to Arch Druid Hamuul Runetotem and accept "Morrowgrain Research" (79.29, #4 on map).
07) Go to Bashana Runetotem at Elder Rise in the hut by the bridge and turn in "Morrowgrain Research" 71.34, SKIP the next part.
08) WOTLK, 8b) If you need to, you can upgrade First Aid from the First Aid Trainer 30.21 on The Spirit Rise.  NOTE: Heavy Mageweave Bandage requires skill 240, Runecloth Bandage skill 260 and Heavy Runecloth Bandage skill 290.
09) Hearth to Ratchet.
10) In Liv Rizzlefix's hut 62.39, turn in "Marvon's Workshop", SKIP "Zapper Fuel" (Dungeon quest).  Also turn in "Volcanic Activity".
11) NOTE:  IF the boat is already at the docks then do this step at BB's Bank instead:  At the Ratchet Bank 63.37 get the following items out:  stack of Pupellyverbos Port, Black Dragonflight Molt and your stack of Dark Iron Scraps.  And put the following items in the bank:  stack of Un'Goro soil, Un'goro Slime Samples, stack of Savage Fronds, Linken's Training Sword, 8 White Ravasaur Claws and any Core of Elements in there (to free up bag space).
12) Go to the end of the docks at Ratchet 64.39 to get on the boat to go to BB.
13) Once at BB, go in the Inn and turn in (if you haven't yet) "Whiskey Slim's Lost Grog" 27.77.
14) 13a) Go up in the Inn to the roof at the Wind Rider Master 27.77 and fly to Kargath, Badlands.
15) At Kargath, just outside of the Inn by the Bonfire, turn in "Vivian Lagrave" 3.48, SKIP "Lost Thunderbrew Recipe" (Dungeon).
16) Next to you, accept "The Rise of the Machines".
17) Find Thal'trak Proudtusk /target, he patrols south and east of Kargath (or could be chillin by the Bonfire).  From him accept "Dreadmaul Rock".  NOTE: Sometimes you must wait until he stops patrolling and then stands by the Bonfire 3.48 in order to accept this.
18) Go to the Wind Rider Master 4.45 and fly to Flame Crest, Burning Steppes.
        ]],
        image = "imagen_015.jpeg",
    },
    [141] = {
        step = 141,
        title = [[53 Burning Steppes]],
        text = [[
01) Once at Flame Crest, under the red tent 65.24, accept: "Broodling Essence" and "Tablet of the Seven".
02) Go in the small cave and turn in "Yuka Screwspigot" 66.22, SKIP "Ribbly Screwspigot" (Dungeon).
03) Go east around 80.29 and do "Broodling Essence": use the Draco-Incarcinatrix 900 quest item on Broodlings (dragon whelps), then kill them and loot the Broodling Essence crystal that drops.  Also throughout questing in Burning Steppes, kill any dragon whelps you see, they are squishy mobs that die real fast.  Keep the next step in mind:
04) With the Black Dragonflight Molt with you, work your way east to the small cave 95.32 then accept and turn in "A Taste of Flame" (you will need to talk to him first after getting the quest), SKIP the next part (Dungeon quest).
05) Go up to the top of Dreadmaul Rock (bridge entrance at 76.38).  Once at the top do "Dreadmaul Rock": click on Sha'ni Proudtusk's Remains 80.46 (laying on the table between four pillars).  Then from the ghost of Sha'ni Proudtusk that spawns, turn in "Dreadmaul Rock", accept "Krom'Grul".
06) Do "Krom'Grul": find Krom'Grul /target inside one of the three caves at Dreadmaul Rock and kill/loot him.  First check the small cave next to you at the top of Dreadmaul Rock 82.44.  If he is not there, then check the other 2 caves SW entrance 77.47.  For the cave on the eastern side NE entrance 82.39, keep making right turns until you get to him.  ALSO:  Make sure you collect a total of 30 Dark Iron Scraps, this will be used for a later quest.  All the Ogres in Burning Steppes can drop them.
07) Go west to Ruins of Thaurissan around 67.38 and do "The Rise of the Machines": kill/loot War Reavers.  Keep the next step in mind:
08) Do "Tablet of the Seven": loot the Tablet of the Seven 54.41 next to the dwarf statue.
09) Go to Flame Crest and under the red tent 65.24, turn in "Broodling Essence", accept "Felnok Steelspring".  Also turn in "Tablet of the Seven".
10) Go to the Wind Rider Master at Flame Crest 66.24 and fly to Kargath, Badlands.
        ]],
        image = "imagen_016.jpeg",
    },
    [142] = {
        step = 142,
        title = [[Orc/Troll - Durotar]],
        text = [[
01) At Kargath, just outside of the Inn, turn in "The Rise of the Machines" 3.48, accept the next part.  Find Thal'trak Proudtusk /target, he patrols south and east of Kargath (or could be chillin by the Bonfire).  From him, turn in "Krom'Grul".  Make sure you are repaired/resupplied.
02) Go east to The Dustbowl at the gnome and turn in "The Rise of the Machines" 26.45, SKIP the next part (Dungeon quest).
03) Hearth to Ratchet.
04) Go to the Ratchet Bank 63.37 and put the following items into it:  30+ Dark Iron Scraps, and any Core of Elements.  And get the following items out:  8 White Ravasaur Claws, Tinkee's Letter and Linken's Training Sword.  Also get out (if you have it) 60 Runecloth for cloth donation to the Orc faction coming up at Orgrimmar.
05) Go to the Flight Master 63.37 at Ratchet and fly to Orgrimmar, Durotar.
06) Go in the Inn at Orgrimmar and make it your new home 54.68.
        ]],
        image = "imagen_017.jpeg",
    },
    [143] = {
        step = 143,
        title = [[PLEASE READ With all the faster leveling changes, by the time you get to this section you already be level 54 (or really close to it). Because of this when following my guide, you should skip this entire section and go right into the section right before 54-54 Felwood below.  I will leave this section for reference purposes only.  However if for some reason you are early into level 53 you can consider doing this section.  If you are NOT doing this section then abandon (if you have it) "Betrayed".]],
        text = [[
01) 54 Azshara
02) Go up to the Wind Rider Master 45.64 and fly to Valormok, Azshara.
03) Once at Valormok, accept "Betrayed" 22.51.
04) Go NE to the hill entrance 53.20...
05) Go up to the top of the hill and accept "Kim'jael Indeed!" 53.22.
06) Go south to Thalassian Base Camp and do "Kim'jael Indeed!" along with "Betrayed": kill the needed Blood Elves, loot Kim'jael's Equipment boxes on the ground and to Find Magus Rimtori's camp (go to 60.31).
07) At the same coordinates as previous step (60.31, #4 on map), from the Kaldorei Tome of Summoning (book on pedestal), turn in "Betrayed", accept the next part.
08) At that same spot, do the next part of "Betrayed": click on an Arcane Focusing Crystal to summon Magus Rimtori and kill/loot her.  You may need to face some guards first so be prepared.
09) Go north to the hill entrance (53.20, #2 on map)...
10) Go up to the top of the hill and turn in "Kim'jael Indeed!" 53.22.  Accept "Kim'jael's "Missing" Equipment".
        ]],
        image = "imagen_018.jpeg",
    },
    [144] = {
        step = 144,
        title = [[Guía de Leveo - Sección #19]],
        text = [[
01) Drop down to The Shattered Strand 51.36 (be careful, its a long drop), then do "Kim'jael's "Missing" Equipment": kill/loot Spitelash naga until Some Rune drops (low drop rate).
02) Leave The Shattered Strand, (an exit is at 46.38, see map for more exits)..
03) Go to Valormok and turn in "Betrayed" 22.51, accept the next part.  Make sure you are repaired/resupplied.
04) Head east to the hill entrance 53.20...
05) Go up to the top of the hill and turn in "Kim'jael's "Missing" Equipment" 53.22.
06) At this point you should almost be lvl 54.  Grind the rest of the way to level 54.5 (10 bars into 54) on Blood Elves around Thalassian Base Camp around 58.28.  NOTES:  Blood Elves are squishy mobs (mobs that have 30% fewer health/armor, than the average mob that level), so they die relatively fast and yield good XP/hour.  They also are a good farm spot for Runecloth, which you will need for cloth donations and First Aid.  OPTIONAL:  Instead of the grinding, you could go do BRD instance instead.
07) Hearth to Orgrimmar.
        ]],
        image = "imagen_019.jpeg",
    },
    [145] = {
        step = 145,
        title = [[Guía de Leveo - Sección #20]],
        text = [[
01) 54 Felwood
02) N/A
03) Go NE to Magar's Cloth Goods and turn in the 60 Runecloth to the Orc's Horde Cloth Quartermaster 64.51.
04) Go north to The Drag (up in Yelmak's Alchemy and Potions) and turn in "Bone-Bladed Weapons" 56.34.
05) N/A
06) If you need to, get new spells/abilities.    Make sure you are repaired/resupplied.
07) Go SW and up to the Wind Rider Master 45.64 and fly to Splintertree Post, Ashenvale.
08) Head north to Felwood (entrance at 56.28 in Ashenvale)..
        ]],
        image = "imagen_020.jpeg",
    },
    [146] = {
        step = 146,
        title = [[Guía de Leveo - Sección #21]],
        text = [[
01) Go north a bit into Felwood to Emerald Sanctuary and get the FP from the Flight Master 52.82 (#1 on map).
02) Accept "Forces of Jaedenar" 51.82.  And next to you in the tent, accept "Verifying the Corruption" 51.82.
03) To the west just off of the main path at Maybess Riverbreeze 47.83, accept "Cleansing Felwood".
04) Start working on "A Sample of Slime...": clear the Cursed Ooze mobs (slimes) at the two green pools (one at around 41.72, and another one at around 42.68).  Eventually get 15 Felwood Slime Samples (once again, 15 is the max you can hold for WOTLK).  You don't need to get all of them now.
05) Go north a bit to Jaedenar entrance 40.58 and do "Forces of Jaedenar": kill the required amount of Jaedenar mobs in the area.
06) Go north a bit around 40.56 and continue working on "A Sample of Slime...": kill/loot Tainted Oozes for getting at least 15 Felwood Slime Samples eventually.  You don't need to get all of them now.
07) Follow Bloodvenom River in the middle of Felwood west to Bloodvenom Post 34.52 and accept "Well of Corruption".  Then at 35.53 "Wild Guardians" and "A Husband's Last Battle".
08) Go up to the Wind Rider Master and get the FP there 34.54.  Make sure you are repaired/resupplied.
09) Go east and finish up collecting at least 15 Felwood Slime Samples for "A Sample of Slime..." by kill/looting the Tainted Oozes, around Bloodvenom Falls around 41.45 (#5 on map).
        ]],
        image = "imagen_021.jpeg",
    },
    [147] = {
        step = 147,
        title = [[Guía de Leveo - Sección #22]],
        text = [[
01) Go up north a bit on the east side of the path to Shatter Scar Vale around 41.42 and do "Verifying the Corruption": walk across one of the craters in the Vale to get it explored, and kill the required amount of Entropic fire elementals.
02) Follow the main path NE to Irontree Woods and do "Cleansing Felwood": kill/loot the Warpwood elementals.  There is more mobs in the Irontree Cavern entrance 56.17.
03) N/A
04) Follow the main path NE (right before the Timbermaw Hold entrance) and accept "Deadwood of the North" 65.8.
05) Drop down west to Felpaw Village around 63.9 and do "Deadwood of the North": kill the needed Deadwood furbolgs.
06) Go back up to Nafien by the Timbermaw Hold entrance (65.8, #4 on map) and turn in "Deadwood of the North".  Accept "Speak to Salfa".  Also turn in any feathers you may have (repeatable quest to increase rep).  NOTE:  Becoming friendlier with Timbermaw Hold will allow you to enter their cave without them attacking you and allowing you to get additional quests and items from them.
07) Enter Timbermaw Hold next to you entrance 65.7 and go through the cave, make a right in the middle after the bridge to enter Moonglade up north.
08) Once in Moonglade, make a left and get the FP from the Wind Rider Master 32.67.
09) Exit Moonglade back to Timbermaw Hold (entrance 35.75 in Moonglade).
10) In Timbermaw Hold, make a right after the stairs to go into Winterspring..
        ]],
        image = "imagen_022.jpeg",
    },
    [148] = {
        step = 148,
        title = [[55 Winterspring]],
        text = [[
01) Right outside of the cave, accept "Winterfall Activity" (28.35 in Winterspring).  Also turn in "Speak to Salfa".
02) Follow the main path south to Donova Snowden 31.45 and accept "Threat of the Winterfall".  Turn in "The New Springs", accept "Strange Sources".  Also turn in "It's a Secret to Everybody", SKIP "The Videre Elixir".  NOTE:  You do not have to wait for the NPC, just leave..
03) Follow the main path east and just to your left as you enter Everlook accept "Are We There, Yeti?" 61.38.
04) From Felnok Steelspring under the blue tent 62.39, turn in "Felnok Steelspring", SKIP "Chillwind Horns" (for now).
05) TBC, 4b) Back in Everlook by the cage 62.38, accept "Ursius of the Shardtooth".
06) South in Everlook, go in the Inn and make Everlook your new home from the Innkeeper 61.39.  Make sure you are repaired/resupplied.
07) Also in the Inn accept "The Everlook Report", "Duke Nicholas Zverenhoff" and "Sister Pamela".
08) Go to Everlook's Bank 61.37 and put the following items in there:  15 Blood Amber, Felwood Slime Samples, Everlook Report, Studies in Spirit Speaking any Core of Elements and (if you have it) Deadwood Ritual Totem.
09) Follow the main path south to discover Darkwhisper Gorge at 60.74 for the quest "Strange Sources".
10) Hearth to Everlook.
11) TBC, 9b) As you go questing, keep an eye out for a bear named Ursius /target (he looks just like all other other ones), if so, kill him for "Ursius of the Shardtooth", but don't intentionally try to find him now:
12) Exit Everlook to the right, then go east to Winterfall Village around 67.35 and do"Winterfall Activity": kill the required amount of Winterfall furbolgs.  NOTE:  This place is usually busy with lvl 60+ players farming Winterfall Firewater here.  If that's the case then this quest can be skipped (there is no follow up).  You can also skip this if you are only level 53 right now as it is kind of a higher level quest.
13) Just north of Everlook (around the mountains 61.33) do part of "Wild Guardians": kill 15 Raging Owlbeasts /target.  Also start working on "Are We There, Yeti?" by kill/looting Ice Thistle Yeti.  Also try to finish "Ursius of the Shardtooth" by finding and killing Ursius /target (white bear), he patrols around on the mountains.
        ]],
        image = "imagen_023.jpeg",
    },
    [149] = {
        step = 149,
        title = [[Guía de Leveo - Sección #24]],
        text = [[
01) Go west starting around 54.37 and finish "Wild Guardians" (kill 15 Ragged Owlbeasts /target) and continue working on "Are We There, Yeti?" (kill/loot Rogue Ice Thistle yeti).  Also work on the next step as well:
02) Do "Threat of the Winterfall": kill the required amount of Winterfall furbolgs.  There are two camps of these mobs (one at around 42.43 and one at around 32.37).  While doing this quest you should find an item, which starts "Winterfall Firewater" (accept it).
03) Go SW to Donova Snowden 31.45 and turn in "Strange Sources", "Threat of the Winterfall" and "Winterfall Firewater", accept "Falling to Corruption".
04) Hearth (or go back) to Everlook.  Make sure you are repaired/resupplied.
05) TBC, 4b) IF YOU DID IT:  Back in Everlook by the cage 62.38, turn in "Ursius of the Shardtooth".
06) Go SE a bit to Ice Thistle Hills around 66.42 (#7 on map) and finish "Are We There, Yeti?": kill/loot Yeti for the Thick Yeti Fur.
07) Hearth (or go back) to Everlook and near the entrance next to the hut, turn in "Are We There, Yeti?" 61.38, accept the next part.
08) Go SE a bit back to Ice Thistle Hills around 66.42 and do "Are We There, Yeti?": kill/loot Ice Thistle Matriarchs and Ice Thistle Patriarchs for the 2 horns (low drop rate).  There is a higher concentration of these mobs in the cave entrance up at 68.42.
09) Hearth (or go back) to Everlook and turn in  "Are We There, Yeti?" 61.38, accept the next part.  NOTE:  If you are deep in the cave you can just die on purpose and res at spirit to get back to Everlook.
10) Do part of "Are We There, Yeti?": at Legacki 62.39 /target (next to the Inn), use Umi's Mechanical Yeti quest item to scare her.
11) Make sure you are repaired/resupplied.
12) Go to Everlook's Bank 61.37 and put the following items into it:  Umi's Mechanical Yeti and (if you have it) Winterfall Ritual Totem.  Get out of the Bank: 15 Blood Amber.
13) Exit Everlook to your right and go to the Wind Rider Master 60.36 to fly to Bloodvenom Post, Felwood.
        ]],
        image = "imagen_024.jpeg",
    },
    [150] = {
        step = 150,
        title = [[56 Felwood]],
        text = [[
01) Once at Bloodvenom Post, turn in "Wild Guardians" 35.53, SKIP the next part (for now).
02) TBC, 1a) At the Wind Rider Master 34.54 fly to Emerald Sanctuary.
03) At Emerald Sanctuary turn in "Forces of Jaedenar" 51.82, accept "Collection of the Corrupt Water".  And next to you in the tent, turn in "Verifying the Corruption" 51.82.
04) Go west to Maybess Riverbreeze and turn in "Cleansing Felwood" 47.83.  Then click the NPC again and talk to her to get a Cenarion Beacon.
05) Just south a bit next to the main path, from Grazle (furblog 51.85), accept "Timbermaw Ally" (no exclamation mark).
06) Go south to Deadwood Village and do "Timbermaw Ally" along with "A Husband's Last Battle": kill the required amount of Deadwood furbolgs and also kill/loot Overlord Ror (gray colored furbolg 48.94).
07) Go north a bit along the main path to Grazle /target (51.85, #4 on map) and turn in "Timbermaw Ally".  Accept "Speak to Nafien".
08) Go up NW in Ruins of Constellas and do "Well of Corruption": use your Hardened Flasket quest item in the green moonwell there 32.67.
09) Follow the main path north to enter Jaedenar entrance 41.58..
10) Go west in Jaedenar and do "Collection of the Corrupt Water": use your Empty Canteen quest item in the green moonwell 35.60.
11) Go north to Bloodvenom Post and turn in "Well of Corruption" (34.52, #1 on map).  Wait a few seconds (do next step while waiting), then accept "Corrupted Sabers".
12) Also at Bloodvenom Post, turn in "A Husband's Last Battle" 35.53.  NOTE:  Do not sell your Corrupted Soul Shards to a vendor.  Make sure you are repaired/resupplied.
13) TBC, 12) At Bloodvenom Post, go to the Wind Rider Master 34.54 and fly to Emerald Sanctuary.
        ]],
        image = "imagen_025.jpeg",
    },
    [151] = {
        step = 151,
        title = [[Orc/Troll - Durotar]],
        text = [[
01) At Emerald Sanctuary turn in "Collection of the Corrupt Water" 51.82, SKIP "Seeking Spiritual Aid".
02) Go west to Maybess Riverbreeze and turn in "Salve Via Hunting" 47.83.  NOTES:  If for some reason you do not have the 6 Corrupted Soul Shards, grind on any mob in Felwood until you get them.  The quest is repeatable, but doesn't yield additional XP.  The reward item Cenarion Plant Salve is used to cleanse the various corrupted plants around Felwood and the reward you get from them is decent (but no XP).
03) Go NW in Ruins of Constellas and do "Corrupted Sabers": use your Winna's Kitten Carrier quest item at the green moonwell there 32.67.
04) Go north to Bloodvenom Post and once you get there talk to the Corrupted Saber that is following you, then turn in "Corrupted Sabers" 34.52.  Make sure you are repaired/resupplied.
05) Follow the main path NE to Felpaw Village and clear the mobs around the Deadwood Cauldron at 60.6, or distract the mobs some how (See Video), then click on the Cauldron to turn in "Falling to Corruption", accept "Mystery Goo".
06) Go NE, right before the Timbermaw Hold entrance and turn in "Speak to Nafien" 65.8.  Also turn in any feathers you may have (repeatable quest to increase rep).
07) Go through the cave to get to Winterspring and right outside of the cave, turn in "Winterfall Activity" (28.34 in Winterspring).
08) Follow the main path south to Donova Snowden 31.45 and turn in "Mystery Goo", accept "Toxic Horrors".  Then if you are not level 56, grind on any mob until you are.
09) Hearth to Everlook.
10) Exit Everlook to your right and go to the Wind Rider Master 60.36 to fly to Orgrimmar, Durotar.
11) Once at Orgrimmar, get your level 56 spells/abilities.
        ]],
        image = "imagen_026.jpeg",
    },
    [152] = {
        step = 152,
        title = [[Orc/Troll - Durotar]],
        text = [[
01) Leave Orgrimmar south and get on the zeppelin (51.14 in Durotar) to go to The Undercity.
02) At the UC go to the Innkeeper and make it your new home 68.38.  Make sure you are repaired/resupplied.
03) Go to the Bank in the middle of the UC 66.44 and get the following items out:  Felwood Slime Samples, Un'goro Slime Samples, Everlook Report and Studies in Spirit Speaking.  And if you have 60 extra Runecloth (for cloth donation) get that out as well.  Put the following items in your bank:  Cenarion Beacon, any Corrupted Soul Shards and any Cenarion Plant Salves.
04) Find Harbinger Balthazad /target, he patrols around the bank (wearing a white shirt with a lantern), once you find him, accept "A Call to Arms: The Plaguelands!".
05) If you have the 60 extra Runecloth, go to the Magic Quarter and turn in "A Donation of Runecloth" 72.29, for undead faction.
06) WOTLK, 5b) If you need to, you can upgrade First Aid from the First Aid Trainer 73.55 at Rogues' Quarter.  NOTE: Runecloth Bandage requires skill 260 and Heavy Runecloth Bandage skill 290.
07) Go SW to The Apothecarium and next to Chemist Fuely 48.73 use the two Testing Equipments (both red and green) to turn your Slime Samples into the quest items you need.  Then turn in "A Sample of Slime..." and "... and a Batch of Ooze".  Accept "Melding of Influences".  NOTE:  You can destroy any remaining Slime Samples to free bag space.
08) Go to the Bank in the middle of the UC (66.44, #3 on map) and put the following items into it:  Encased Corrupt Ooze.   Get out of the bank:  Swim Speed Potions, (if you have all of them) 30+ Dark Iron Scraps and 30+ Savage Fronds.  And there is a quest in Eastern Plaguelands that wants these items:  2 Thorium Bar, Golden Rod, 8 Hi-Explosive Bomb, 8 Unstable Trigger (get these out, either from the AH or bank if you can get all of them).  You can then mail these items (including the 30+ Dark Iron Scraps and 30+ Savage Fronds) to yourself and retrieve them from the mailbox at Light's Hope in EPL later.
09) Leave The Undercity and go east in Tirisfal Glades to the The Bulwark (83.69 in Tirisfal Glades)..
        ]],
        image = "imagen_027.jpeg",
    },
    [153] = {
        step = 153,
        title = [[56 Western Plaguelands]],
        text = [[
01) Make a left on the main path as you enter The Bulwark and turn in "A Call To Arms: The Plaguelands!" (83.69 in Tirisfal Glades), accept "Scarlet Diversions".  Then next to you loot the Box of Incendiaries to obtain a Flame in a Bottle.
02) Next to you, turn in "The Everlook Report" 83.68.  From this same NPC, complete "Argent Dawn Commission".  NOTE:  The trinket received called Argent Dawn Commission will allow you to collect Scourgestones from undead mobs in the Plaguelands (both eastern and western).  Right-click it in your inventory to wear it.  As long as you have it on, this will allow you to increase your rep with The Argent Dawn, which will allow you to buy items such as Enriched Manna Biscuits later.
03) WOTLK, 2a) Get the Flight Path from the Bat Handler 84.70.
04) Go to the other side of The Bulwark, and behind the bigger tent accept "A Plague Upon Thee" 83.72.
05) Go east into Western Plaguelands (WPL) to Felstone Field and up in the house, accept "Better Late Than Never" (38.54 in WPL).
06) Go in the barn next to the house and click on Janice's Parcel 39.55 to turn in "Better Late Than Never".  Then click Janice's Parcel again to accept the next part of "Better Late Than Never".
07) Go just NE a bit to the small Scarlet camp 41.52 and do "Scarlet Diversions": clear the mobs in the area (you need to work quickly to avoid respawns) then click on the Command Tent to burn it and then use the Scourge Banner quest item at the camp. (See Video)
08) Go back to The Bulwark (make a right on the path) and turn in "Scarlet Diversions" (83.69 in Tirisfal Glades, #1 on map).  Accept "The Scourge Cauldrons".
09) Make sure you are resupplied 83.70.  NOTE:  Make sure you save all Bone Fragments you find, you will need 30 of them for a later quest.
10) Go to the other side of The Bulwark and turn in "The Scourge Cauldrons" 83.72, accept "Target: Felstone Field".
        ]],
        image = "imagen_028.jpeg",
    },
    [154] = {
        step = 154,
        title = [[Undead - Tirisfal Glades]],
        text = [[
01) At Felstone Field, do "Target: Felstone Field": kill/loot Cauldron Lord Bilemaw /target 37.57.  Then click on the Scourge Cauldron to turn in "Target: Felstone Field", accept "Return to the Bulwark".
02) Go back to The Bulwark and turn in "Return to the Bulwark" (83.72 in Tirisfal Glades), accept "Target: Dalson's Tears".
03) At Dalson's Tears, do "Target: Dalson's Tears": kill/loot Cauldron Lord Malvinious /target 46.52.  Then click on the Scourge Cauldron to turn in "Target: Dalson's Tears", accept "Return to the Bulwark".
04) There is a small quest chain here at this farm that yields good XP:  Go in the Barn at Dalson's Tears and click on Mrs. Dalson's Diary 48.51 laying on the ground to complete "Mrs. Dalson's Diary".
05) Find and kill/loot the Wandering Skeleton /target.  This one skeleton wanders around the NE side of Dalson's Tears.  He circles around the barn as well.
06) Click on the Outhouse 48.50 behind the barn to complete "Locked Away".  Then Farmer Dalson will spawn next to the Outhouse, kill/loot this zombie.
07) Go up in the house (next to the barn) and click on the Locked Cabinet 47.50 to turn in "Locked Away".  Quest chain complete.
08) Go back to The Bulwark and turn in "Return to the Bulwark" (83.72 in Tirisfal Glades, #2 on map), accept "Target: Writhing Haunt".
09) At The Writhing Haunt, do "Target: Writhing Haunt": kill/loot Cauldron Lord Razarch /target 53.66.  Then click on the Scourge Cauldron to turn in "Target: Writhing Haunt", accept "Return to the Bulwark".
10) Go in the small house at The Writhing Haunt and accept "The Wildlife Suffers Too" 54.65.
11) Go back to The Bulwark and turn in "Return to the Bulwark" (83.72 in Tirisfal Glades, #2 on map), accept "Target: Gahrron's Withering".  Make sure you are resupplied.
12) At Gahrron's Withering, do "Target: Gahrron's Withering": kill/loot Cauldron Lord Soulwrath /target 63.59.  Then click on the Scourge Cauldron to turn in "Target: Gahrron's Withering", accept "Return to the Bulwark".   NOTE:  We will turn this in later.
13) Go east into Eastern Plaguelands (follow path on map) 5.38 in EPL..
        ]],
        image = "imagen_030.jpeg",
    },
    [155] = {
        step = 155,
        title = [[57 Eastern Plaguelands]],
        text = [[
01) Go north along Thondoril River to Tiron Fordring 5.38 and accept "Demon Dogs", "Blood Tinged Skies" and "Carrion Grubbage".
02) Grind SE to The Marris Stead 23.68 and accept "To Kill With Purpose", "Un-Life's Little Annoyances" and "The Ranger Lord's Behest".
03) Go south to The Undercroft and down in the crypt, from the Torn Scroll 24.78 laying on the ground, accept "Hameya's Plea".
04) Grind east to Darrowshire to Pamela Redpath and turn in "Sister Pamela" 32.84, accept "Pamela's Doll".
05) At Darrowshire do "Pamela's Doll": find the 3 parts to Pamela's Doll:  the head, the left side and right side.  These parts have multiple spawn locations around Darrowshire in each of the 3 buildings in the area (excluding the building where Pamela is at).  They look like little yellow things.  Search the buildings for the 3 parts: big house 34.85, torn down house 35.85, small house 35.83, then click one of them to combine them to make Pamela's Doll.  (See Video)
06) Go back to Pamela Redpath at Darrowshire and turn in "Pamela's Doll" ( 32.84, #4 on map).  Accept "Auntie Marlene" and "Uncle Carlin".
07) Around southern EPL around 36.76, finish "Blood Tinged Skies": kill 30 Plaguebats.  Also do part of "Demon Dogs": kill 20 Plaguehound Runts.  And start working on "Carrion Grubbage": kill/loot Carrion mobs for the worm meat.  All of these mobs are found in southern Eastern Plaguelands and the Carrion worm mobs are all over Eastern Plaguelands.  Once you are nearing completion, work your way east to the next step:
08) Grind to Light's Hope Chapel 74.58 and accept "The Restless Souls" and "Zaeldarr the Outcast".
        ]],
        image = "imagen_031.jpeg",
    },
    [156] = {
        step = 156,
        title = [[Guía de Leveo - Sección #32]],
        text = [[
01) Go north a bit and turn in "Duke Nicholas Zverenhoff" 76.54.  Also from this NPC, if you have at least 20 Minion's Scourgestones, complete a "Minion's Scourgestones" (and dont consume the item received).
02) Next to you, turn in "Uncle Carlin" 76.54.  Accept "Defenders of Darrowshire".
03) Get resupplied/repaired from Craftsman Wilhelm 75.54 next to the Forge.  NOTE:  If for some reason you are already Friendly with The Argent Dawn, then stock up on Enriched Manna Biscuits from the female dwarf Miranda Breechlock 76.54 by the tent.
04) WOTLK, 3a) You should be friendly now with The Argent Dawn, if so:  Right in front of the Inn's Entrance, go to Rayne 75.53 and if you have the 30 Savage Fronds (in the mailbox?) accept and turn in "Savage Fronds".
05) WOTLK, 3b) Also (if you are friendly with The Argent Dawn):  Go in the Inn and in the back from the human with black hair 76.52 , accept and turn in "Binding the Dreadnaught" (requires the 30 Dark Iron Scraps, that could be in your mailbox).
06) At the other side of the Inn, from the human on the horse and with your one Argent Dawn Valor Token you might have, accept and turn in "They Call Me "The Rooster" 75.52.  If you dont have it yet, do this when you can.
07) If you were able to obtain the items needed for "That's Asking A Lot", then turn it in (at the dwarf Smokey LaRue by the Campfire, 75.52 ), accept "When Smokey Sings, I Get Violent".
08) North in Light's Hope, get the FP there from the Bat Handler 74.51.
09) OPTIONAL: The quest "Bolstering Our Defenses" 74.52 is a PvP tower capture quest that is optional and up to you if you would like to do it or not, my guide will not cover it further.  I don't recommend doing this if you are trying to level quickly.
        ]],
        image = "imagen_032.jpeg",
    },
    [157] = {
        step = 157,
        title = [[Guía de Leveo - Sección #33]],
        text = [[
01) Go SW to Corin's Crossing around 55.62 and do "To Kill With Purpose": kill/loot the undead mobs there to obtain Living Rot (work fast they only last 10 min), then use your Mortar and Pestle quest item to combine 7 of them to make the item you need.  Also start working on "Defenders of Darrowshire": kill Gibbering Ghouls and then talk to the spirit that spawns (don't need to finish this now though).
02) Just north around 56.50, do part of "Demon Dogs" and "Un-Life's Little Annoyances": kill 5 Plaguehounds /target and 20 Noxious Plaguebats.  These mobs are found in the middle-eastern side of Eastern Plaguelands.
03) Grind north to Zul'Mashar (ramp entrance at 59.19 )..
04) Go up into Zul'Mashar and do "Hameya's Plea": kill/loot Infiltrator Hameya /target.  This troll patrols around in front of the temple 65.13.  Stay away from the dirt mounds in front of the temple as undeads will spawn near them, it's better to wait until Infiltrator Hameya patrols up front for you to take on alone.  Also he hits hard so be prepared.
05) Finish up "Carrion Grubbage", "Demon Dogs" and "Un-Life's Little Annoyances": kill/loot Carrion mobs for the worm meat, kill 5 Frenzied Plaguehounds and kill 10 Monstrous Plaguebats.  These mobs are found NE around the open fields of Eastern Plaguelands around 56.50.  NOTE:  You can find some more spirits for "Defenders of Darrowshire" around 61.35 from the Diseased Flayers, and you can find more on the later steps as well.
06) GROUP 2+ Players (or could be soloable): Go north to Quel'Lithien Lodge entrance 47.17 and try to do "The Ranger Lord's Behest": kill the needed blood elf mobs and go into the lodge, make a right, then loot the Quel'Thalas Registry (book laying on a bench 48.14 ).  This quest may be hard to solo.  If you are almost lvl 57, then grind to it before doing this quest.  You may need to distract the mobs in the lodge, grab the book and run out some how.  If you cannot solo this, or find help then it can be skipped.
07) Go west to Plaguewood (starting at 44.26 ) and do the following 3 quests together:
08) "A Plague Upon Thee": loot the Large Termite Mounds, these are spaced all around Plaguewood (see map).
09) "Defenders of Darrowshire": continue working on this by killing Cannibal Ghouls and talk to the spirits that spawn.  You will have more opportunities later to finish this.
10) If you have it do "When Smokey Sings, I Get Violent": go in the various ziggurats around Plaguewood and use Smokey's Special Compound quest item inside the buildings.
        ]],
        image = "imagen_033.jpeg",
    },
    [158] = {
        step = 158,
        title = [[Guía de Leveo - Sección #34]],
        text = [[
01) Go west to Terrordale and in the hut turn in "The Restless Souls" 11.29, SKIP the next part (dungeon).  And next to you, accept "Augustus' Receipt Book".
02) Do "Augustus' Receipt Book": go NE a bit to the Terrordale Inn (the largest building in the area entrance 14.28 ) and go up in the Inn, make a right and between two split open barrels loot Augustus' Receipt Book 14.26 on the ground.  NOTE:  Kill/loot all Crypt Fiends you see to start obtaining Crypt Fiend Parts (used for a later quest).
03) Go back to the hut in Terrordale and turn in "Augustus' Receipt Book" ( 11.29 , #1 on map).  NOTE:  You can now get resupplied from this NPC.
04) OPTIONAL:  Grind on Crypt Fiend mobs all around Terrordale to collect 30 Crypt Fiend Parts.  This can be used for a later quest.  There is more in the next step as well (but watch out for the Elite):
05) Go through the long cave entrance 12.25.  NOTES:  This cave journey is not easy.  There is a lvl 60 elite spider /target (with a 1 hour respawn) that patrols back and forth to the 2 entrances of this cave.  Try to sneak past it if you can.  If this cave is too hard for you, then another possible quick alternative is to take the Tower Gryphon ride from the Plaguewood Tower 19.27 to the Crown Guard Tower, as long as the horde has control over the towers that is.  Try to get all 30 Crypt Fiend Parts before leaving this area.  If you are still far off from that, then you can skip getting the remaining ones.
06) Once you get out to the other side of the cave (or take the tower ride), north along Thondoril River at Tiron Fordring 5.38 , turn in "Demon Dogs" "Blood Tinged Skies" and "Carrion Grubbage".  Accept "Redemption".  Simply talk to Tiron Fordring to complete "Redemption", accept "Of Forgotten Memories".
07) Grind SE to The Marris Stead 23.68 and turn in "To Kill With Purpose", "Un-Life's Little Annoyances" and (if you did it) "The Ranger Lord's Behest".  Accept "Duskwing, Oh How I Hate Thee..." and "The Corpulent One".
08) TBC, 7b) Do "Duskwing, Oh How I Hate Thee...": kill/loot Duskwing /target.  This large lvl 60 bat patrols just north and NE of The Marris Stead around 28.63.
09) TBC, 7c) Go back to The Marris Stead 23.68 and turn in "Duskwing, Oh How I Hate Thee...".
10) Go south to The Undercroft, go down in the crypt and then do "Zaeldarr the Outcast": kill/loot Zaeldarr the Outcast 24.78.  (See Video)
11) Behind the crypt, next to the wooden wagon, click on the Mound of Dirt 24.79 to turn in "Hameya's Plea".
12) Next to you, do "Of Forgotten Memories": click on the Loose Dirt Mound 25.80 that is next to Tirion Fordring's Grave, then kill/loot Mercutio Filthgorger (he has 3 bodyguards).  IMPORTANT TIP:  These mobs spawn between the two dirt mounds (from the previous step).  Mercutio Filthgorger spawns in first, then his bodyguards soon after.  So act fast and immediately pull Mercutio Filthgorger away from his spawn point to avoid fighting his guards too, as this fight can be really tough to do solo without this tactic.
        ]],
        image = "imagen_034.jpeg",
    },
    [159] = {
        step = 159,
        title = [[Guía de Leveo - Sección #35]],
        text = [[
01) Go NW to Tiron Fordring 5.38 and turn in "Of Forgotten Memories", accept "Of Lost Honor".
02) 1b) Go NE to Corin's Crossing around 54.64 and continue working on (if you still need to) "Defenders of Darrowshire": kill any Gibbering Ghouls or Diseased Flayers and then talk to the spirit that spawns!  You will have another opportunity later to finish this.
03) Go to the south side of Light's Hope Chapel, then turn in "Zaeldarr the Outcast" 74.58.
04) Go north in Light's Hope Chapel and turn in (if it's finished) "Defenders of Darrowshire" 76.54.
05) Next to you at Duke Nicholas Zverenhoff /target 76.54, turn in any Scourgestones you have.  If you haven't yet, save at least one Argent Dawn Valor Token for a later quest.  You can consume the rest to increase rep with The Argent Dawn.
06) Get repaired/resupplied from Craftsman Wilhelm 75.54 next to the Forge.
07) In the Inn, if you have the 30 Crypt Fiend Parts, accept and turn in "Cryptstalker Armor Doesn't Make Itself..." (from Huntsman Leopold).
08) Go north a bit more in Light's Hope Chapel and turn in (if you did it) "When Smokey Sings, I Get Violent" 75.52.  If you turned this in, you can then destroy Smokey's Special Compound.
09) If you still need to:  Next to you at the human on the horse and with your Argent Dawn Valor Token, accept and turn in "They Call Me "The Rooster" 75.52.
10) Go NE a bit around 70.46 and finish (if you still need to) "Defenders of Darrowshire": kill any Gibbering Ghouls or Diseased Flayers and then talk to the spirit that spawns.
11) Grind north to Northdale and do "Of Lost Honor": loot the Symbol of Lost Honor 66.29 (under the lake).
12) TBC, 11b) Do "The Corpulent One": kill/loot Borelgore /target (lvl 60 big yellow worm, around 50.27)
13) IF YOU STILL NEED TO: Go SE to Light's Hope Chapel and turn in "Defenders of Darrowshire" (#3 on map) 76.54.
14) TBC, 12b) Go back to The Marris Stead 23.68 and turn in "The Corpulent One".
15) Grind all the way back west to Tiron Fordring ( 5.38 , #1 on map) and turn in "Of Lost Honor", accept "Of Love and Family".
        ]],
        image = "imagen_035.jpeg",
    },
    [160] = {
        step = 160,
        title = [[Undead - Tirisfal Glades]],
        text = [[
01) Go south at the island of Caer Darrow in Western Plaguelands (use a Swim Speed Potion) and turn in "Of Love and Family" 66.75 in WPL.  SKIP the next part (Dungeon).
02) Hearth to UC.  Make sure you are repaired/resupplied.
03) At the Bank in the middle of the UC, put the following items into it: any remaining Crypt Fiend Parts, Savage Fronds, any Core of Elements and any Insignias.
04) Drop down east to Guild Creation and turn in "Better Late Than Never" 70.43, accept "The Jeremiah Blues".
05) Underneath the bank from the Cockroach Vendor 68.44, turn in "The Jeremiah Blues", accept "Good Luck Charm".
06) Find Harbinger Balthazad /target, he patrols around the bank (wearing a white shirt with a lantern), once you find him, accept "The New Frontier".
07) Also if you still need to turn in 60 extra Runecloth (for cloth donation), go to the Magic Quarter and turn in "A Donation of Runecloth" 72.29, for undead faction.
08) Leave The Undercity and go east in Tirisfal Glades to The Bulwark (83.71 in Tirisfal Glades)..
        ]],
        image = "imagen_036.jpeg",
    },
    [161] = {
        step = 161,
        title = [[58 Western Plaguelands]],
        text = [[
01) Make a right at The Bulwark and turn in "Return to the Bulwark" 83.72.
02) Next to you behind the tent, turn in "A Plague Upon Thee" 83.72, accept the next part.  NOTE:  If you have any remaining Plagueland Termites in your inventory, you can destroy them.
03) TBC, 2a) From the male blood elf 83.71 accept "The So-Called Mark of the Lightbringer".
04) At the other side of The Bulwark, complete "Mission Accomplished!" 83.69.  Also accept "All Along the Watchtowers".
05) If you have turned Friendly with The Argent Dawn, then you can stock up on Enriched Manna Biscuits next to you from Argent Quartermaster Hasana 83.68.  These biscuits will help you level faster by receiving mana faster from consuming these biscuits.
06) Go into Western Plaguelands to Felstone Field and up in the house, turn in "Good Luck Charm" 38.54, accept "Two Halves Become One".
07) Go south of Felstone Field around 37.58 and do "Two Halves Become One": kill/loot the Jabbering Ghoul /target (only one mob spawn that patrols around the farm).  This mob drops Good Luck Other-Half-Charm.  Right-click this item in your inventory.
08) Go back up in the house at Felstone Field and turn in "Two Halves Become One" (38.54, #5 on map).
09) Go north to Northridge Lumber Camp and do "A Plague Upon Thee": clear the mobs at the lumber camp, click on the Northridge Lumber Mill Crate 48.32 to place the termite barrel.  Then click on the spawned Termite Barrel on top of the crate to turn in "A Plague Upon Thee", accept the next part.  (See Video)
10) Go NE down a long slope in Northridge Lumber Camp and accept "Unfinished Business" 52.28.
11) Go south a bit and do "Unfinished Business": kill the required amount of Scarlet humans in the area.  The mages and knights are around 51.41.  NOTE: They share spawns with each other.  See next step for the medics and hunters:
12) Go south a bit to the small Scarlet camp and kill the needed medics and hunters around 52.44.
        ]],
        image = "imagen_037.jpeg",
    },
    [162] = {
        step = 162,
        title = [[Guía de Leveo - Sección #38]],
        text = [[
01) Go back up NE in Northridge Lumber Camp, down the long slope and turn in "Unfinished Business" 52.28, accept the next part.
02) Go east a bit and do "Unfinished Business": kill Huntsman Radley 58.36 /target.  See next step for the other named mob to kill:
03) Kill Cavalier Durgen /target.  He patrols around in the tower 55.24.  Also go up this tower and do "The So-Called Mark of the Lightbringer" by looting the Holy Coffer.
04) Go back down in Northridge Lumber Camp and turn in "Unfinished Business" (52.28, #1 on map), accept the next part.
05) Go north to Hearthglen and do the last part of "Unfinished Business": go to the top of the watchtower 46.18 to complete the quest.  Just mount up and avoid the mobs.  Having a healing potion on hand helps.  (Watch This Video to see a shortcut and how to do this quest).
06) Go back down in Northridge Lumber Camp and turn in "Unfinished Business" (52.28, #1 on map).
07) Make sure "The Wildlife Suffers Too" is finished: kill 8 Diseased Wolves /target.  These wolves are found mostly above Dalson's Tears farm.  They share spawns with the spiders in the area, so kill them if not enough wolves.  Work your way to the next step:
08) Go south to the small house at The Writhing Haunt and turn in "The Wildlife Suffers Too" 54.65, accept the next part.
09) Do "The Wildlife Suffers Too" (part 2): kill 8 Diseased Grizzly /target.  These bears are found north and east of The Writhing Haunt.  They share spawns with the spiders, so kill spiders if not enough bears.
10) Go back to the small house at The Writhing Haunt and turn in "The Wildlife Suffers Too" (54.65, #8 on map).  Accept "Glyphed Oaken Branch".
11) Go SW to Sorrow Hill and in the house (up or down in it) turn in "Auntie Marlene" 49.79, accept "A Strange Historian".
12) Do "A Strange Historian": next to the house your at, loot Joseph Redpath's Monument in the graveyard 50.77.  (See Video)
13) Enter Ruins of Andorhal (bridge entrance at 49.72)..
        ]],
        image = "imagen_038.jpeg",
    },
    [163] = {
        step = 163,
        title = [[Guía de Leveo - Sección #39]],
        text = [[
01) Make a left at the tower and do part of "All Along the Watchtowers": use the Beacon Torch quest item at Tower Four 47.71.
02) Go west and do part of "All Along the Watchtowers": use the Beacon Torch quest item at Tower One 40.72.  NOTE: You must use the torch item right in the doorway of these towers in order for it to work, don't waste your charges!
03) Go north and enter the Andorhal Inn entrance 40.68, go upstairs and turn in "A Strange Historian" 39.67, accept "The Annals of Darrowshire".  Also accept "A Matter of Time".
04) Enter the City Hall building in the middle of Andorhal entrance 44.69 and do "The Annals of Darrowshire": loot the Annals of Darrowshire (blue book).  The actual Annals of Darrowshire book looks different from the others, it has a lighter tint on the top portion of the pages in the book, unlike the rest which has a darker tint on the top portion of the pages. (See Video)
05) Go north and do part of "All Along the Watchtowers": use the Beacon Torch quest item at Tower Two 42.66.
06) Go NE and do the last part of "All Along the Watchtowers": use the Beacon Torch quest item at Tower Three 44.63.
07) Go east a bit and do "A Matter of Time": use the Temporal Displacer quest item near the silos around 47.63 then kill the Temporal Parasites that spawn.  NOTE: The quest item only works on the silos emitting blue beams of light.
08) Go west and enter the Andorhal Inn (entrance 40.68, #3 on map), go upstairs and turn in "A Matter of Time" and "The Annals of Darrowshire".  Accept "Counting Out Time" and "Brother Carlin".
09) All around Ruins of Andorhal do "Counting Out Time": loot the Small Lockboxes all around the broken down houses.  There is usually one at each broken down house.
10) Enter the Andorhal Inn (entrance 40.68, #3 on map), go upstairs and turn in "Counting Out Time".  NOTES:  This quest is repeatable, but you will not get additional XP from it.  The quest reward Attuned Dampener can only be used on Araj the Summoner in the middle of Andorhal, and there will be quests later associated with killing him.
        ]],
        image = "imagen_039.jpeg",
    },
    [164] = {
        step = 164,
        title = [[TBC, 00) Go west and make a left at The Bulwark and turn in "The So-Called Mark of the Lightbringer" (83.71 in Tirisfal Glades, #1 on map).  Wait a few seconds then accept "Defiling Uther's Tomb".]],
        text = [[
01) Turn in "A Plague Upon Thee" 83.72 in Tirisfal.
02) At the other side of The Bulwark turn in "All Along the Watchtowers" 83.69.  Accept "Scholomance".  You can then destroy the Beacon Torch item.
03) Next to you at Argent Officer Garush 83.68, turn in any Scourgestones you may have.  Then use the Argent Dawn Valor Token's received to increase your rep with The Argent Dawn.
04) Make sure you are resupplied.  You can stock up on Enriched Manna Biscuits next to you from Argent Quartermaster Hasana 83.68.  These biscuits will help you level faster by receiving mana faster from eating/drinking.
05) At The Bulwark turn in "Scholomance" 83.69, accept "Skeletal Fragments".
06) Go back to Ruins of Andorhal around 40.69 in WPL and do "Skeletal Fragments": kill/loot skeleton mobs for the 15 Skeletal Fragments.  Also keep grinding until you have collected 30 Bone Fragments for a later quest.
07) TBC, 6a) Go SE to Uther's Tomb 52.84 and do "Defiling Uther's Tomb": equip the quest item Corrupted Mark of the Lightbringer, then use it at the tomb.
08) Go west and make a right at The Bulwark and turn in "Skeletal Fragments" (83.69 in Tirisfal Glades, #2 on map), SKIP "Mold Rhymes With...".
09) Next to you at Argent Officer Garush 83.68, turn in any Scourgestones you may have.
10) If you are a class that uses mana, then stock up on Enriched Manna Biscuits 83.68.  NOTE:  I personally buy about 600 biscuits.
11) TBC, 9a) At the other side of The Bulwark turn in "Defiling Uther's Tomb" 83.71.
12) Go west in Tirisfal Glades and get on the zeppelin 61.59 to go to Orgrimmar.  While waiting, build up First Aid.
        ]],
        image = "imagen_040.jpeg",
    },
    [165] = {
        step = 165,
        title = [[Tauren - Mulgore]],
        text = [[
01) In Orgrimmar, go to the Inn and make Orgrimmar your new home from the Innkeeper 54.68.
02) Go to the Bank 50.69 and put your Enriched Manna Biscuits in there so that you only have about 160 left in your inventory.  Also put into the bank:  your stack of 30+ Bone Fragments, any extra Scourgestones, Extended Annals of Darrowshire and Attuned Dampener.  And get the following items out of the bank:  Umi's Mechanical Yeti, Encased Corrupt Ooze, and your current stack of Core of Elements.
03) Cloth Donations are turned in NE at Magar's Cloth Goods to the Orc's Horde Cloth Quartermaster 64.51.  You may have already turned in the 60 Runecloth to them in the past.
04) Go up the spiral ramp next to you, then go get new spells/abilities.
05) Cloth Donations are also turned in at Darkbriar Lodge (Valley of Spirits) from the Troll's Horde Cloth Quartermaster 38.88.  Following the guide you would still need to turn in 60 Mageweave Cloth and 60 Runecloth to them.  NOTE:  The "Additional Runecloth" quests do NOT yield XP (only rep).
06) Go up to the Wind Rider Master 45.64 and fly to Thunder Bluff, Mulgore.
        ]],
        image = "imagen_041.jpeg",
    },
    [166] = {
        step = 166,
        title = [[Guía de Leveo - Sección #42]],
        text = [[
01) Once at TB, go to The Elder Rise at Nara Wildmane and turn in "Glyphed Oaken Branch" 76.32.
02) Next to you in the same room, from Arch Druid Hamuul Runetotem, turn in "The New Frontier" 79.29, accept "Rabine Saturna".
03) NOTE:  If you have 60 extra Runecloth, get them out (bank is at 47.59) and turn them in for cloth donation, Tauren faction 43.43.
04) Go up to the Wind Rider Master 47.50 and fly to Moonglade (up north).
05) Once in Moonglade, go to Nighthaven and turn in "Rabine Saturna" 52.45, accept "Wasteland".  Also accept "A Reliquary of Purity". NOTE:  In order to accept the purity quest, you need to have been in the Dire Maul zone in Feralas before talking to Rabine Saturna in order to unlock the dialog option (which you also need to read) in order to get this quest.  If you can't get it, you can just skip it and ignore any future notations of it.
06) Hearth to Orgrimmar.
07) 06b) At Orgrimmar, down below accept "Taking Back Silithus" 48.66.
08) Go up to the Wind Rider Master 45.64 and fly to Gadgetzan, Tanaris.
09) N/A
10) NW in Gadgetzan, do part of "Are We There, Yeti?": use Umi's Mechanical Yeti quest item to scare Sprinkle /target 51.27.
11) Go to the Wind Rider Master (north of Gadgetzan, 52.25) and fly to Marshal's Refuge, Un'Goro Crater.
        ]],
        image = "imagen_042.jpeg",
    },
    [167] = {
        step = 167,
        title = [[Guía de Leveo - Sección #43]],
        text = [[
01) At Marshal's Refuge finish "Are We There, Yeti?": use Umi's Mechanical Yeti quest item to scare Quixxil /target 44.9.  See Image of his location.
02) Go just west of Marshal's Refuge and do "Melding of Influences": engage a Primal Ooze /target (there is one at 39.17) and then use the Encased Corrupt Ooze quest item, then kill/loot the Gargantuan Ooze that spawns.  NOTE:  If there is no Primal Ooze there, then there is another one at 46.24.
03) Go into Silithus entrance 29.22..
        ]],
        image = "imagen_043.jpeg",
    },
    [168] = {
        step = 168,
        title = [[59 Silithus]],
        text = [[
01) As you enter Silithus go to the small camp on your left (Valor's Rest) and turn in "Wasteland" 82.19, accept "The Spirits of Southwind".
02) Follow the main path west to Cenarion Hold and turn in "Taking Back Silithus" 51.38, accept "Securing the Supply Lines".
03) Next to you at the Wanted Poster: Deathclasp 51.38, accept "Wanted - Deathclasp, Terror of the Sands" (Elite).
04) Go up in the Inn next to you and accept "Deadly Desert Venom" 52.39.
05) Go up in Cenarion Hold and accept "The Twilight Mystery" 50.37.
06) Behind the moonwell, accept "Secret Communication" 49.38.  And IF YOU ARE LVL 60 accept: "Abyssal Contacts", and (next to you) "Twilight Geolords".
07) Next to you, accept "Report to General Kirika" 49.37.
08) At the Wind Rider Master 49.37 in Cenarion Hold, get the FP.
09) Go in the building next to you and accept "Dearest Natalia" 49.34.
10) Go south to Southwind Village around 62.52 and do "The Spirits of Southwind" along with "A Reliquary of Purity": kill 8 Tortured Druids and 8 Tortured Sentinels around the village and work your way up in the village into the building and loot the Dusty Reliquary 63.55.
11) Grind/loot all mobs as you go NE to Valor's Rest and turn in "The Spirits of Southwind" (82.19, #1 on map), accept "Hive in the Tower".
12) Go back down SW to Southwind Village and do "Hive in the Tower": go to the top of the swarming bug tower 60.53 and click on the Hive'Ashi Pod, then kill/loot the Hive'Ashi Ambushers until you get the Encrusted Silithid Object.  Also while doing Southwind Village quests you should find an item (which drops from the bugs), which starts "Brann Bronzebeard's Lost Letter", accept it.  And keep grinding until you get it.
13) Grind NE to Valor's Rest and turn in "Hive in the Tower" (82.19, #1 on map), accept "Umber, Archivist".
        ]],
        image = "imagen_044.jpeg",
    },
    [169] = {
        step = 169,
        title = [[Guía de Leveo - Sección #45]],
        text = [[
01) Go to the small camp above Staghelm Point around 66.21and do "Secret Communication": kill/loot the Twilight mobs.  NOTE:  IF YOU ARE LVL 60 the quest "Abyssal Contacts" can be done here and multiple times later in this zone but my guide will not cover it or the follow ups, but its worth doing.  And keep the next step in mind:
02) All around NE Silithus do "Deadly Desert Venom" along with "Securing the Supply Lines": kill/loot Stonelash Scorpids (scorpids), kill/loot Sand Skitterers (spiders), and kill 15 Dredge Strikers (snakes).
03) Go to Cenarion Hold and turn in "Securing the Supply Lines" 51.38, accept "Stepping Up Security".
04) Next to you, go up in the Inn and turn in "Deadly Desert Venom" 52.39.  Accept "Noggle's Last Hope".  Make sure you are repaired/resupplied.
05) Go up in Cenarion Hold and behind the moonwell, turn in "Secret Communication" 49.38.  NOTE:  The repeatable quest "Encrypted Twilight Texts" does not yield XP, only rep with the Cenarion Circle.  But save your additional Encryped Twilight Texts for a future quest.
06) Go to the NW end of Silithus around 27.15and do "The Twilight Mystery": loot the tablets on the ground.  And kill/loot Dust Stormers & Whirling Invaders (wind elementals) until you get a total of 30 Core of Elements (used for a later quest), however if you are far off from the 30, you can optionally skip this.
07) All around the middle of Silithus do "Stepping Up Security": kill 20 Dredge Crushers.  Also do part of "Noggle's Last Hope": kill/loot Stonelash Pincers.  Work your way to the next step:
08) SE at the small horde camp, turn in "Report to General Kirika" 51.70, accept "Scouring the Desert".  NOTE:  For "Scouring the Desert", keep an eye out for a Silithyst Geyser which looks like a glowing red thing all around Silithuis, click on it and you will get a buff, maintain the buff while bringing it back to the PVP Horde base and stand in the teleporter looking thing, then turn the quest in for good XP!
09) Grind south to Bronzebeard Encampment and turn in "Brann Bronzebeard's Lost Letter" 41.88.  Also at this same NPC, talk to him to do part of "Dearest Natalia".
10) Next to you at Frankal Stonebridge 41.89(sitting down at a tent), finish "Dearest Natalia" by talking to this NPC.
        ]],
        image = "imagen_045.jpeg",
    },
    [170] = {
        step = 170,
        title = [[Guía de Leveo - Sección #46]],
        text = [[
01) All around southern Silithus finish "Noggle's Last Hope": kill/loot Stonelash Flayers (scorpids) and Rock Stalker (spiders).
02) Grind north to Cenarion Hold and just outside of the Inn, turn in "Stepping Up Security" 51.38.  Make sure you are repaired/resupplied.
03) Go up in the Inn next to you and turn in "Noggle's Last Hope" 52.39.  Then next to you, accept "Noggle's Lost Satchel".
04) Go up in Cenarion Hold and turn in "The Twilight Mystery" 50.37, accept "The Deserter".
05) Go in the building next to you and turn in "Dearest Natalia" 49.34, SKIP "Into The Maw of Madness" (group quest).
06) Go SE to Ortell's Hideout (small cave) and turn in "The Deserter" 67.70, accept "The Twilight Lexicon".
07) Grind NW to Twilight Base Camp and do "The Twilight Lexicon": kill/loot the 3 named mobs.  First one is Twilight Keeper Havunth /target.  This orc patrols around the Twilight Base Camp 41.43.  Also start working on (if you have the lvl 60 quest) "Twilight Geolords" by killing the Twilight Geolords (and you will see more of these mobs in the next 2 camps coming up).  See next steps for the other two:
08) Grind west to Twilight Post and kill/loot Twilight Keeper Mayna /target (female human 26.37).  NOTE:  Feel free to grind on the Twilight mobs here to obtain Encryped Twilight Texts.  You will need 10 for a future quest and you will have one more opportunity in the next step to get some more:
09) Go south to Twilight Outpost and kill/loot Twilight Keeper Exeter /target (red armored human with fiery sword 16.86).  NOTES:  You can avoid Hive'Zora & the Alliance camp by hugging the west side of Silithus mountains.  Also keep grinding on the Twilight mobs until you get 10 Encryped Twilight Texts, this will be used for an easy turn-in quest later.  And make sure "Twilight Geolords" is finished now.
10) Go right behind Bronzebeard Encampment to the mountain entrance 43.90 and try to do "Wanted - Deathclasp, Terror of the Sands" (Elite): kill/loot Deathclasp /target.  This level 59 Elite scorpid is soloable but could give you some troubles.  If you cannot solo it, or find a group to help you, then it can be skipped.  (See Video)
11) Also at the same area of Deathclasp, do "Noggle's Lost Satchel": loot Noggle's Satchel (yellow sack on ground 45.91).  (See Video)
        ]],
        image = "imagen_046.jpeg",
    },
    [171] = {
        step = 171,
        title = [[Orc/Troll - Durotar]],
        text = [[
01) Grind east to Ortell's Hideout (small cave) and turn in "The Twilight Lexicon" 67.70, accept "A Terrible Purpose".  Also accept, and then turn in "True Believers".  Also this quest is repeatable, but no additional XP.
02) Grind back to Cenarion Hold and up in the Inn turn in "Noggle's Lost Satchel" 52.39.
03) Go up in Cenarion Hold and in the building, turn in "A Terrible Purpose" 49.34, SKIP "Into The Maw of Madness" (requires group).  Also, IF YOU ARE LVL 60 turn in "Twilight Geolords" (by the moonwell), NOTE: "Vyral the Vile" is a solable quest that can be done, but wont be covered here.
04) As you exit the building, make a left and go all the way to the top of the tower and turn in (if you did it) "Wanted - Deathclasp, Terror of the Sands" 51.34.
05) Hearth (or fly) to Orgrimmar.  Make sure you are repaired/resupplied.
06) In Orgrimmar, go to the Bank 50.69 and get the following items out:  Extended Annals of Darrowshire and your stack of 30+ Bone Fragments.  Also, (IF you still need to, and have them), get out: 30 Savage Fronds, 30 Dark Iron Scraps.  NOTE:  30 Core of Elements could already be in your inventory, if not get them out too (if you have them).  You can put into the bank any remaining Encrypted Twilight Text you may have.
07) Leave Orgrimmar south and get on the zeppelin (51.14 in Durotar) to go to The Undercity.
08) Once at the UC, go down in The Apothecarium and turn in "Melding of Influences" 47.73.
09) Go up to the Bat Handler 63.49 and fly to Light's Hope Chapel, Eastern Plaguelands.
10) Once at Light's Hope Chapel, go in the Inn and from the female human 76.52 sitting at the table, accept and turn in The Elemental Equation.
11) Also in the Inn from Rohan 76.53 (in purple standing near the entrance), accept and turn in "Bonescythe Digs".
12) ONLY do the following 3 if you still need to:
13) Back in the Inn from Korfax 76.52 (human with black hair), accept and turn in "Binding the Dreadnaught".
14) Also in the Inn from Huntsman Leopold 76.53 (balding male standing near the entrance), accept and turn in "Cryptstalker Armor Doesn't Make Itself...".
15) Just outside of the Inn on your left, accept and turn in "Savage Flora" 75.53.
        ]],
        image = "imagen_047.jpeg",
    },
    [172] = {
        step = 172,
        title = [[Guía de Leveo - Sección #48]],
        text = [[
01) Outside at the campfire / tent, turn in "Brother Carlin" 76.54, accept "Villains of Darrowshire".  Make sure you are repaired/resupplied.  NOTE:  "Heroes of Darrowshire" (and all follow up quests) is a quest chain you could do if you have a group, and it's worth doing, especially later when you get the chance.
02) Go west to Blackwood Lake and do "Villains of Darrowshire": loot Horgus' Skull under the water (look for the purple glow 47.44).  See next step for the other item to loot:
03) Go south to The Infectis Scar and loot Shattered Sword of Marduk 49.60.  Look for the pink glow.
04) Go back to Light's Hope Chapel at the campfire / tent and turn in "Villains of Darrowshire" ( 76.54, #1 on map).
05) Go SW to Corin's Crossing 55.62 and grind on the mobs there until your Hearthstone cooldown is up, then Hearth to Orgrimmar.  Also, another decent grinding spot is The Noxious Glade 70.45.  ALTERNATIVELY:  If you did not do "The Ranger Lord's Behest", then you could try that now:  Go north to Quel'Lithien Lodge entrance 47.17 and kill the needed blood elf mobs and go into the lodge, make a right, then loot the Quel'Thalas Registry (book laying on a bench 48.14).  You may need to distract the mobs in the lodge, grab the book and run out some how.  If you still cannot solo this, or find help then it can be skipped. .  Also, you can do (if you still need to) "Duskwing, Oh How I Hate Thee...": kill/loot Duskwing /target.  This lvl 60 bat patrols just above The Marris Stead.  And: "The Corpulent One", Borelgore /target (lvl 60, around 50.27).  These get accepted/turned in at The Marris Stead 23.68.
