    [173] = {
        step = 173,
        title = [[60 Winterspring]],
        text = [[
01) After you have Hearthed to Orgrimmar, go to the Bank 50.69 and put the following items into it:  any remaining Core of Elements, Bone Fragments, Savage Fronds, Dark Iron Scraps and any Insignias.
02) Go up to the Wind Rider Master 45.64 and fly to Bloodvenom Post, Felwood.
03) At Bloodvenom Post, accept "Wild Guardians" 35.53.  Make sure you are repaired/resupplied.
04) Go NE to Irontree Woods (around 50.23 in Felwood) and do "Toxic Horrors": kill/loot Toxic Horrors (green water elementals).
05) Go through Timbermaw Hold entrance 65.7 and make a right in the middle after the bridge to enter Moonglade up north.
06) Once in Moonglade, go to Nighthaven and at Umber, turn in "Umber, Archivist" 45.36 or could be at 48.40, accept "Uncovering Past Secrets".
07) Go into Nighthaven and turn in "A Reliquary of Purity" 52.45, SKIP "Shards of the Felvine" (Dungeon).  Also turn in "Uncovering Past Secrets".
08) Go back to Umber at Nighthaven and complete "Under the Chitin Was..." (48.40 or could be at 45.36, #6 on map).
09) Exit Moonglade at the SW path to go back to Timbermaw Hold (36.72 in Moonglade).
10) In Timbermaw Hold, make a right after the stairs (NOT the bridge) to go into Winterspring..
11) Go south to Donova Snowden (31.45 in Winterspring) and turn in "Toxic Horrors", accept "Winterfall Runners".
12) Try to do "Winterfall Runners": try to find the pack of Winterfall Runners (three lvl 57s) that patrols the main path from the Timbermaw Hold cave 28.34 to Winterfall Village 68.38 and kill/loot them for the Winterfall Crate.  See map for exact patrol path.  If after making one pass and you cannot find these mobs, then this can be skipped for now.
13) If (or when ever) you have completed "Winterfall Runners", go west to Donova Snowden (31.45, #11 on map) and turn it in.  Accept "High Chief Winterfall" .  NOTE:  My guide will not cover "High Chief Winterfall".
14) Follow the main path east to Everlook.
        ]],
        image = "imagen_049.jpeg",
